# ADR 0003: Context Engineering e Redução de Tokens

## Status
Proposto

## Contexto
Enviar o projeto inteiro para um modelo é caro, lento e aumenta alucinações. O ai-devkit precisa fornecer contexto mínimo, correto e verificável.

## Decisão
Adicionar uma camada de context engineering composta por:

- `project-index.json`;
- `dependency-map.md`;
- `api-map.md`;
- `ui-map.md`;
- context packs por tarefa;
- seleção de arquivos relevantes;
- resumos incrementais.

## Consequências
- Redução significativa de tokens.
- Menos ambiguidade para modelos locais e remotos.
- Melhor rastreabilidade.
- Necessidade de scripts de atualização e validação.

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, printHelp, parseArgs, slugify } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
const name = args._.join(' ')

if (args.help || !name) {
  printHelp('acceptance-generate.js', 'node .ai/bin/acceptance-generate.js <feature-name> [--out <dir>]', [
    '--out <dir>  Output dir (default: .ai/testing/acceptance/)',
    '--help        Show this help'
  ])
  process.exit(args.help ? 0 : 1)
}

const slug = slugify(name)
const outDir = path.join(ROOT, args.out || '.ai/testing/acceptance')
fs.mkdirSync(outDir, { recursive: true })

const scenarios = [
  { name: 'Happy path', given: 'valid input data is provided', when: 'the feature is executed', then: 'the expected result is returned' },
  { name: 'Missing required field', given: 'a required field is empty', when: 'the feature is executed', then: 'VALIDATION_ERROR is returned' },
  { name: 'Invalid input type', given: 'a field has wrong type', when: 'the feature is executed', then: 'VALIDATION_ERROR is returned' },
  { name: 'Unauthorized access', given: 'user has no permission', when: 'the feature is executed', then: 'FORBIDDEN is returned' },
  { name: 'Resource not found', given: 'target resource does not exist', when: 'the feature is executed', then: 'NOT_FOUND is returned' },
  { name: 'Duplicate resource', given: 'a resource with same key exists', when: 'the feature is executed', then: 'CONFLICT is returned' },
]

const gherkin = [
  '# Acceptance Criteria: ' + name,
  '', 'Generated: ' + new Date().toISOString(), '',
  '```gherkin', 'Feature: ' + name, ''
]
for (const s of scenarios) {
  const safeName = s.name.replace(/\s+/g, '-').toLowerCase()
  gherkin.push('  Scenario: ' + s.name)
  gherkin.push('    Given ' + s.given)
  gherkin.push('    When ' + s.when)
  gherkin.push('    Then ' + s.then)
  gherkin.push('')
}
gherkin.push('```', '')

const specPath = path.join(outDir, slug + '.acceptance.md')
fs.writeFileSync(specPath, gherkin.join('\n'), 'utf-8')

const testContent = [
  "import { describe, it, expect, beforeAll } from '@jest/globals'",
  '',
  "describe('" + name + "', () => {",
  "  beforeAll(async () => {",
  "    // Setup: seed data, configure test environment",
  "  })",
  '',
]
for (const s of scenarios) {
  const testName = 'should handle: ' + s.name
  testContent.push('  it(\'' + testName + '\', async () => {')
  testContent.push('    // Given ' + s.given)
  testContent.push('    // When ' + s.when)
  testContent.push('    // Then ' + s.then)
  testContent.push('    // PENDING_ACTION: implement test')
  testContent.push('  })')
  testContent.push('')
}
testContent.push('})', '')

const testDir = path.join(ROOT, 'tests/acceptance')
fs.mkdirSync(testDir, { recursive: true })
const testPath = path.join(testDir, slug + '.acceptance.spec.ts')
if (!fs.existsSync(testPath)) fs.writeFileSync(testPath, testContent.join('\n'), 'utf-8')

info('Acceptance tests generated: ' + slug + '.acceptance.md + test skeleton (' + scenarios.length + ' scenarios)')

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, printHelp, parseArgs, writeTextIdempotent } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('adr-index.js', 'node .ai/bin/adr-index.js', ['--help  Mostra esta ajuda'])
  process.exit(0)
}

const dir = path.join(ROOT, '.ai/architecture/adr')
const files = fs.existsSync(dir) ? fs.readdirSync(dir).filter(f => f.endsWith('.md') && f !== 'README.md').sort() : []

const lines = ['# ADR Index', '', '| ADR | Arquivo |', '|-----|---------|']
files.forEach(f => lines.push('| ' + f.replace(/\.md$/, '') + ' | [' + f + '](./' + f + ') |'))
lines.push('')

writeTextIdempotent(path.join(dir, 'README.md'), lines.join('\n'))
info('.ai/architecture/adr/README.md atualizado com ' + files.length + ' ADR(s)')

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, printHelp, parseArgs, writeTextIdempotent, slugify } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
const title = args._.join(' ')

if (args.help || !title) {
  printHelp('adr-new.js', 'node .ai/bin/adr-new.js <titulo da decisao>', ['--help  Mostra esta ajuda'])
  process.exit(args.help ? 0 : 1)
}

const dir = path.join(ROOT, '.ai/architecture/adr')
fs.mkdirSync(dir, { recursive: true })
const existing = fs.readdirSync(dir).filter(f => /^\d{4}-/.test(f))
const next = existing.length + 1
const number = String(next).padStart(4, '0')
const slug = slugify(title)
const today = new Date().toISOString().split('T')[0]

const content = [
  '# ADR-' + number + ' -- ' + title,
  '',
  '## Status: proposed | Data: ' + today,
  '',
  '## Contexto',
  '[Por que esta decisao foi necessaria?]',
  '',
  '## Decisao',
  '[O que foi decidido?]',
  '',
  '## Consequencias',
  '- Positivo: [beneficio]',
  '- Negativo: [custo]',
  '',
  '## Alternativas consideradas',
  '- [Alternativa]: descartada por [motivo]',
  ''
].join('\n')

const out = path.join(dir, number + '-' + slug + '.md')
writeTextIdempotent(out, content)
info('ADR criada: .ai/architecture/adr/' + number + '-' + slug + '.md')

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, printHelp, parseArgs, writeTextIdempotent, readTextSafe } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('agent-plan.js', 'node .ai/bin/agent-plan.js', ['--help  Mostra esta ajuda'])
  process.exit(0)
}

const taskPath = path.join(ROOT, '.ai/tasks/current-task.md')
const task = readTextSafe(taskPath) || '# Nenhuma tarefa definida em .ai/tasks/current-task.md'

const content = [
  '# Execution Plan',
  '',
  'Gerado a partir de `.ai/tasks/current-task.md`.',
  '',
  '## Tarefa atual',
  '',
  '```markdown',
  task.trim(),
  '```',
  '',
  '## Passos sugeridos',
  '',
  '1. Ler contexto (`.ai/context/ai-handoff.md`).',
  '2. Validar prontidao (`.ai/checklists/implementation-readiness-checklist.md`).',
  '3. Implementar em blocos pequenos e verificaveis.',
  '4. Rodar lint, typecheck e testes.',
  '5. Atualizar memoria e contexto ao concluir.',
  ''
].join('\n')

const out = path.join(ROOT, '.ai/agents/execution-plan.md')
const result = writeTextIdempotent(out, content)
info(result.changed ? 'execution-plan.md atualizado' : 'execution-plan.md ja estava atualizado')

#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');
const Handlebars = require('handlebars');
const { parseArgs, printHelp, ensureDir, log, info, warn } = require('./lib/common');
const { toPascalCase, toCamelCase } = require('../generators/helpers/naming');

const args = parseArgs(process.argv.slice(2));

if (args.help || args._.length === 0) {
  printHelp(
    'api-client-generate.js — Gera TypeScript API client a partir de spec OpenAPI 3',
    'node .ai/bin/api-client-generate.js <spec.yaml|json> [--name <name>] [--out <dir>]',
    [
      '--name <name>  Client name (default: derivado do filename)',
      '--out <dir>    Output dir (default: src/api-client/)',
    ]
  );
  process.exit(0);
}

const specFile = args._[0];
const specPath = path.resolve(process.cwd(), specFile);

if (!fs.existsSync(specPath)) {
  console.error(`Spec file not found: ${specFile}`);
  process.exit(1);
}

const clientName = toPascalCase(args.name || path.basename(specFile, path.extname(specFile)));
const outDir = args.out || path.join('src', 'api-client');
const templateDir = path.join(__dirname, '..', 'generators', 'templates', 'api-client');

let specContent = fs.readFileSync(specPath, 'utf-8');
let spec;

if (specFile.endsWith('.yaml') || specFile.endsWith('.yml')) {
  try {
    const yaml = require('js-yaml');
    spec = yaml.load(specContent);
  } catch (e) {
    console.error(`YAML parse error: ${e.message}`);
    process.exit(1);
  }
} else {
  try {
    spec = JSON.parse(specContent);
  } catch (e) {
    console.error(`JSON parse error: ${e.message}`);
    process.exit(1);
  }
}

if (!spec.openapi || !spec.openapi.startsWith('3')) {
  console.error('Only OpenAPI 3.x specs are supported.');
  process.exit(1);
}

function resolveRef(spec, ref) {
  if (!ref || !ref.startsWith('#/')) return null;
  const parts = ref.replace('#/', '').split('/');
  let current = spec;
  for (const part of parts) {
    current = current[part];
    if (!current) return null;
  }
  return current;
}

function schemaToTs(schema, spec) {
  if (!schema) return 'unknown';
  if (schema.$ref) {
    const resolved = resolveRef(spec, schema.$ref);
    if (resolved) return schemaToTs(resolved, spec);
    const refName = schema.$ref.split('/').pop();
    return toPascalCase(refName);
  }
  switch (schema.type) {
    case 'string': return 'string';
    case 'integer': case 'number': return 'number';
    case 'boolean': return 'boolean';
    case 'array':
      return `${schemaToTs(schema.items, spec)}[]`;
    case 'object': {
      if (schema.properties) {
        const props = Object.entries(schema.properties).map(([k, v]) => {
          const req = (schema.required || []).includes(k);
          return `  ${k}${req ? '' : '?'}: ${schemaToTs(v, spec)};`;
        }).join('\n');
        return `{\n${props}\n}`;
      }
      return 'Record<string, unknown>';
    }
    default: return 'unknown';
  }
}

const schemas = [];
const schemaDefs = spec.components?.schemas || {};
for (const [name, schema] of Object.entries(schemaDefs)) {
  const properties = [];
  if (schema.properties) {
    const required = schema.required || [];
    for (const [propName, propSchema] of Object.entries(schema.properties)) {
      properties.push({
        name: propName,
        type: schemaToTs(propSchema, spec),
        required: required.includes(propName),
      });
    }
  }
  schemas.push({ name: toPascalCase(name), properties });
}

const operations = [];
const paths = spec.paths || {};
for (const [pathStr, methods] of Object.entries(paths)) {
  for (const [method, op] of Object.entries(methods)) {
    if (['get', 'post', 'put', 'patch', 'delete'].indexOf(method) === -1) continue;
    const opId = op.operationId || `${method}${toPascalCase(pathStr.replace(/[{}\/]/g, '-'))}`;
    const funcName = toCamelCase(opId);

    const hasBody = ['post', 'put', 'patch'].includes(method);
    const hasParams = !!(op.parameters && op.parameters.length > 0);

    let bodyType = 'unknown';
    if (hasBody && op.requestBody) {
      const content = op.requestBody.content;
      if (content && content['application/json'] && content['application/json'].schema) {
        bodyType = schemaToTs(content['application/json'].schema, spec);
      }
    }

    let responseType = 'unknown';
    const okResp = op.responses?.['200'] || op.responses?.['201'] || op.responses?.['default'];
    if (okResp && okResp.content && okResp.content['application/json'] && okResp.content['application/json'].schema) {
      responseType = schemaToTs(okResp.content['application/json'].schema, spec);
    }

    let paramsType = 'Record<string, string>';
    if (hasParams) {
      const params = op.parameters.map(p => `  ${p.name}${p.required ? '' : '?'}: string;`).join('\n');
      paramsType = `{\n${params}\n}`;
    }

    operations.push({
      functionName: funcName,
      method,
      path: pathStr,
      hasBody,
      hasParams,
      bodyType,
      responseType,
      paramsType,
    });
  }
}

function renderTemplate(file, data) {
  const tpl = fs.readFileSync(path.join(templateDir, file), 'utf-8');
  return Handlebars.compile(tpl)(data);
}

const typesContent = renderTemplate('types.ts.hbs', { schemas });
const clientContent = renderTemplate('client.ts.hbs', { operations });

const outBase = path.join(process.cwd(), outDir);
const typesFile = path.join(outBase, 'types.ts');
const clientFile = path.join(outBase, 'client.ts');

let created = 0;
let skipped = 0;

for (const [filePath, content] of [[typesFile, typesContent], [clientFile, clientContent]]) {
  if (fs.existsSync(filePath)) {
    warn(`Skip (exists): ${path.relative(process.cwd(), filePath)}`);
    skipped++;
    continue;
  }
  ensureDir(path.dirname(filePath));
  fs.writeFileSync(filePath, content, 'utf-8');
  log(`Create: ${path.relative(process.cwd(), filePath)}`);
  created++;
}

console.log('');
info(`Client: ${clientName}`);
info(`Schemas: ${schemas.length} | Operations: ${operations.length}`);
info(`Created: ${created} | Skipped: ${skipped}`);

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, fail, printHelp, parseArgs } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('asyncapi-validate.js', 'node .ai/bin/asyncapi-validate.js', ['--help  Mostra esta ajuda'])
  process.exit(0)
}

const file = path.join(ROOT, args.file || 'docs/api/asyncapi.yaml')
if (!fs.existsSync(file)) {
  console.warn('WARN: docs/api/asyncapi.yaml nao encontrado — nada a validar (skip).')
  process.exit(0)
}
const content = fs.readFileSync(file, 'utf-8')

const errors = []
if (!/^asyncapi:/m.test(content)) errors.push('campo "asyncapi" ausente')
if (!/^info:/m.test(content)) errors.push('campo "info" ausente')
if (!/^channels:/m.test(content)) errors.push('campo "channels" ausente')

if (errors.length) { errors.forEach(e => fail(e)); process.exit(1) }
info('docs/api/asyncapi.yaml passou na validacao estrutural basica')

#!/usr/bin/env node
'use strict'

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { ROOT, info, warn } = require('./lib/common');

const LOG_PATH = path.join(ROOT, '.ai/memory/agent-activity-log.md');

info('Iniciando Audit Agent (TSK-2.3)');

function generateAuditReport() {
    let report = `## Auditoria Semanal (${new Date().toISOString().split('T')[0]})\n\n`;

    // Testar cobertura de boundaries
    try {
        execSync('node .ai/bin/check-boundaries.js', { cwd: ROOT });
        report += `- [x] Boundaries: Nenhuma violação detectada.\n`;
    } catch(e) {
        report += `- [ ] Boundaries: Falhou na verificação. O sistema requer autocura ou intervenção.\n`;
    }

    // Verificar atualização do Contexto
    const handoffPath = path.join(ROOT, '.ai/context/ai-handoff.md');
    if (fs.existsSync(handoffPath)) {
        const stats = fs.statSync(handoffPath);
        const daysOld = (Date.now() - stats.mtimeMs) / (1000 * 60 * 60 * 24);
        if (daysOld > 7) {
            report += `- [ ] Contexto: ai-handoff.md desatualizado há mais de ${Math.round(daysOld)} dias.\n`;
        } else {
            report += `- [x] Contexto: Atualizado recentemente.\n`;
        }
    }

    report += '\n---\n\n';

    if (!fs.existsSync(LOG_PATH)) {
        fs.writeFileSync(LOG_PATH, '# Log de Atividades dos Agentes\n\n', 'utf8');
    }

    const currentLog = fs.readFileSync(LOG_PATH, 'utf8');
    const header = '# Log de Atividades dos Agentes\n\n';
    const insertPoint = currentLog.indexOf(header);
    const newLog = insertPoint === -1
        ? header + report + currentLog
        : currentLog.slice(0, insertPoint + header.length) + report + currentLog.slice(insertPoint + header.length);
    fs.writeFileSync(LOG_PATH, newLog, 'utf8');

    info('Relatório de Auditoria anexado em agent-activity-log.md');
}

generateAuditReport();

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const { execSync } = require('child_process');

const ROOT = process.cwd();
const BACKUP_DIR = path.join(ROOT, '.ai/audit/backup');
const BACKUP_GIT_DIR = path.join(BACKUP_DIR, 'repo');
const ARCHIVE_DIR = path.join(BACKUP_DIR, 'archives');
const CONFIG_PATH = path.join(BACKUP_DIR, 'backup-config.json');
const LEDGER_PATH = path.join(ROOT, '.ai/audit/ledger.jsonl');

const MAX_BYTES = 2 * 1024 * 1024 * 1024;
const GC_THRESHOLD = 0.80 * MAX_BYTES;
const ROTATE_THRESHOLD = 0.90 * MAX_BYTES;
const HARD_THRESHOLD = 0.97 * MAX_BYTES;

function loadConfig() {
    if (!fs.existsSync(CONFIG_PATH)) return { githubRemote: null, githubEnabled: false, maxBytes: MAX_BYTES };
    return JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
}

function saveConfig(cfg) {
    fs.mkdirSync(BACKUP_DIR, { recursive: true });
    fs.writeFileSync(CONFIG_PATH, JSON.stringify(cfg, null, 2));
}

function sh(cmd, cwd) {
    return execSync(cmd, { cwd: cwd || BACKUP_GIT_DIR, stdio: 'pipe', encoding: 'utf-8' });
}

function ensureBackupRepo() {
    fs.mkdirSync(BACKUP_GIT_DIR, { recursive: true });
    fs.mkdirSync(ARCHIVE_DIR, { recursive: true });
    if (!fs.existsSync(path.join(BACKUP_GIT_DIR, '.git'))) {
        sh('git init -q', BACKUP_GIT_DIR);
        sh('git config user.email "ledger-backup@ai-devkit.local"', BACKUP_GIT_DIR);
        sh('git config user.name "AI-DevKit Backup Bot"', BACKUP_GIT_DIR);
    }
}

function dirSize(dir) {
    let total = 0;
    if (!fs.existsSync(dir)) return 0;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        total += entry.isDirectory() ? dirSize(full) : fs.statSync(full).size;
    }
    return total;
}

function getBackupSize() { return dirSize(BACKUP_DIR); }

function commitToBackup(entry) {
    ensureBackupRepo();
    fs.copyFileSync(LEDGER_PATH, path.join(BACKUP_GIT_DIR, 'ledger.jsonl'));
    try {
        sh('git add ledger.jsonl');
        sh(`git commit -q --allow-empty -m "seq:${entry.seq} hash:${entry.thisHash.slice(0,12)} exit:${entry.exitCode}"`);
    } catch (e) {}
    enforceQuota();
    maybePushToGithub();
}

function enforceQuota() {
    const size = getBackupSize();
    if (size < GC_THRESHOLD) return { action: 'none', size };
    try { sh('git gc --aggressive --prune=now -q'); } catch (e) {}
    let newSize = getBackupSize();
    if (newSize < ROTATE_THRESHOLD) return { action: 'gc', size: newSize };
    rotateOldestHistory();
    newSize = getBackupSize();
    if (newSize >= HARD_THRESHOLD) { deleteOldestArchive(); newSize = getBackupSize(); }
    return { action: 'rotated', size: newSize };
}

function rotateOldestHistory() {
    const log = sh('git log --reverse --format=%H').trim().split('\n').filter(Boolean);
    if (log.length < 20) return;
    const cutIndex = Math.floor(log.length / 2);
    const cutCommit = log[cutIndex];
    const oldContent = sh(`git show ${log[0]}:ledger.jsonl`);
    const archiveName = `ledger-archive-${Date.now()}.jsonl.gz`;
    fs.writeFileSync(path.join(ARCHIVE_DIR, archiveName), zlib.gzipSync(oldContent));
    sh(`git checkout --orphan __rotated_tmp__ ${cutCommit}`);
    sh(`git commit -q -m "rotated-base referencia-arquivo:${archiveName}"`);
    try { sh('git branch -D master'); } catch (e) {}
    try { sh('git branch -D main'); } catch (e) {}
    sh('git branch -m master');
    sh('git gc --aggressive --prune=now -q');
}

function deleteOldestArchive() {
    const files = fs.readdirSync(ARCHIVE_DIR).map(f => ({ f, t: fs.statSync(path.join(ARCHIVE_DIR, f)).mtimeMs })).sort((a, b) => a.t - b.t);
    if (files.length === 0) return;
    fs.unlinkSync(path.join(ARCHIVE_DIR, files[0].f));
    console.warn(`⚠️ Cota de 2GB atingida. Arquivo mais antigo removido: ${files[0].f}. Configure GitHub para histórico ilimitado.`);
}

function configureGithub(remoteUrl) {
    ensureBackupRepo();
    try { sh('git remote remove origin'); } catch (e) {}
    sh(`git remote add origin ${remoteUrl}`);
    const cfg = loadConfig();
    cfg.githubRemote = remoteUrl;
    cfg.githubEnabled = true;
    saveConfig(cfg);
}

function maybePushToGithub() {
    const cfg = loadConfig();
    if (!cfg.githubEnabled || !cfg.githubRemote) return;
    try { sh('git push -u origin master --quiet 2>/dev/null || git push -u origin main --quiet 2>/dev/null'); }
    catch (e) { console.warn('⚠️ Push para GitHub falhou. Backup local permanece intacto.'); }
}

function status() {
    const size = getBackupSize();
    const cfg = loadConfig();
    return {
        sizeMB: (size / (1024 * 1024)).toFixed(2),
        quotaMB: (MAX_BYTES / (1024 * 1024)).toFixed(0),
        percentUsed: ((size / MAX_BYTES) * 100).toFixed(1),
        githubEnabled: cfg.githubEnabled,
        githubRemote: cfg.githubRemote,
        archiveCount: fs.existsSync(ARCHIVE_DIR) ? fs.readdirSync(ARCHIVE_DIR).length : 0,
    };
}

module.exports = { commitToBackup, enforceQuota, getBackupSize, configureGithub, status, ensureBackupRepo };

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const sourceDir = process.cwd();
const targetDir = path.resolve(process.cwd(), '../ai-devkit-txt-export');

const ORPHAN_PATTERN = /^(fix|patch|dummy|run_|test_|tamper|copy_|audit-|apply-)[-_a-zA-Z0-9]*\.(js|ts)$/i;

if (fs.existsSync(targetDir)) {
    fs.rmSync(targetDir, { recursive: true, force: true });
}
fs.mkdirSync(targetDir, { recursive: true });

function copyToTxtExport(currentPath, currentTarget) {
    const items = fs.readdirSync(currentPath, { withFileTypes: true });

    for (const item of items) {
        if (['node_modules', '.git', 'dist'].includes(item.name)) continue;

        const srcPath = path.join(currentPath, item.name);
        const destPath = path.join(currentTarget, item.name);

        if (item.isDirectory()) {
            if (!fs.existsSync(destPath)) {
                fs.mkdirSync(destPath, { recursive: true });
            }
            copyToTxtExport(srcPath, destPath);
        } else {
            if (ORPHAN_PATTERN.test(item.name) && !srcPath.includes('06-PATCH-HISTORY')) {
                continue;
            }
            fs.copyFileSync(srcPath, destPath + '.txt');
        }
    }
}

