#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, warn, fail, printHelp, parseArgs, readTextSafe } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('check-boundaries.js', 'node .ai/bin/check-boundaries.js [--modules <file>] [--json]', [
    '--modules <file>  Modules definition (default: .ai/modules.yaml)',
    '--json            Output results as JSON',
    '--help             Show this help'
  ])
  process.exit(0)
}

const modulesFile = path.join(ROOT, args.modules || '.ai/modules.yaml')
const allowedDeps = {}

if (fs.existsSync(modulesFile)) {
  const yaml = fs.readFileSync(modulesFile, 'utf-8')
  const modRegex = /-\s+name:\s*(\S+)\s*\n(?:\s+dependsOn:\s*\n((?:\s+-\s+\S+\s*\n)*))?/g
  let m
  while ((m = modRegex.exec(yaml)) !== null) {
    const modName = m[1]
    const deps = m[2] ? m[2].match(/-\s+(\S+)/g)?.map(d => d.replace('- ', '').trim()) || [] : []
    allowedDeps[modName] = new Set(deps)
  }
}

const srcDir = path.join(ROOT, 'src/modules')
if (!fs.existsSync(srcDir)) {
  info('No modules found in src/modules/')
  process.exit(0)
}

const modules = fs.readdirSync(srcDir).filter(d => fs.statSync(path.join(srcDir, d)).isDirectory())
const imports = {}

for (const mod of modules) {
  imports[mod] = { internal: new Set(), external: new Set(), domain: 0, infra: 0, app: 0 }
  const walk = (dir) => {
    if (!fs.existsSync(dir)) return
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, e.name)
      if (e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules') { walk(full); continue }
      if (!e.name.endsWith('.ts') && !e.name.endsWith('.tsx')) continue
      const content = fs.readFileSync(full, 'utf-8')
      if (full.includes(path.sep + 'domain' + path.sep)) imports[mod].domain++
      if (full.includes(path.sep + 'infrastructure' + path.sep)) imports[mod].infra++
      if (full.includes(path.sep + 'application' + path.sep)) imports[mod].app++
      const im = content.matchAll(/from\s+['"]\.\.?\/([^'"]+)['"]/g)
      for (const i of im) {
        const p = i[1]
        for (const other of modules) {
          if (other === mod) continue
          if (p.startsWith(other + '/') || p.startsWith('../' + other + '/')) {
            imports[mod].internal.add(other)
          }
        }
      }
    }
  }
  walk(path.join(srcDir, mod))
}

const violations = []
for (const [mod, data] of Object.entries(imports)) {
  for (const dep of data.internal) {
    const allowed = allowedDeps[mod]?.has(dep)
    if (Object.keys(allowedDeps).length > 0 && !allowed) {
      violations.push({ module: mod, dependsOn: dep, allowed: !!allowedDeps[mod]?.size })
    }
  }
}

if (args.json) {
  console.log(JSON.stringify({ modules, imports, violations, totalModules: modules.length, totalViolations: violations.length }, null, 2))
  process.exitCode = violations.length > 0 ? 1 : 0
  process.exit()
}

info('Modules: ' + modules.length + ' — ' + modules.join(', '))
for (const [mod, data] of Object.entries(imports)) {
  const layers = []
  if (data.domain) layers.push('domain(' + data.domain + ')')
  if (data.app) layers.push('app(' + data.app + ')')
  if (data.infra) layers.push('infra(' + data.infra + ')')
  const deps = data.internal.size > 0 ? ' -> [' + [...data.internal].join(', ') + ']' : ''
  info('  ' + mod + ': ' + (layers.join('/') || 'empty') + deps)
}

if (violations.length > 0) {
  violations.forEach(v => warn('Boundary violation: ' + v.module + ' -> ' + v.dependsOn + (v.allowed ? ' (allowed)' : ' (NOT in modules.yaml)')))
  fail(violations.length + ' boundary violation(s) found')
  process.exit(1)
}
info('No boundary violations. All cross-module imports are declared in modules.yaml.')

#!/usr/bin/env node
'use strict'
const { execFileSync } = require('child_process')
const path = require('path')
const { ROOT, info, warn, fail, printHelp, parseArgs, writeTextIdempotent } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('check-contracts.js', 'node .ai/bin/check-contracts.js [--strict] [--json] [--report]', [
    '--strict   Exit with error on warnings too',
    '--json     Output results as JSON',
    '--report   Generate Markdown report in .ai/reports/',
    '--help      Show this help'
  ])
  process.exit(0)
}

const scripts = ['openapi-validate.js', 'asyncapi-validate.js', 'graphql-validate.js']
const results = []
let hasError = false

for (const script of scripts) {
  const scriptPath = path.join(__dirname, script)
  try {
    const output = execFileSync(process.execPath, [scriptPath], { encoding: 'utf-8', stdio: ['pipe','pipe','pipe'] })
    results.push({ script, status: 'pass', output: output.trim() })
    info(script + ': OK')
    if (!args.json) console.log(output.trim())
  } catch (err) {
    hasError = true
    const stderr = (err.stderr || '').toString().trim()
    results.push({ script, status: 'fail', error: stderr || err.message })
    warn(script + ': FAIL')
  }
}

const health = {
  timestamp: new Date().toISOString(),
  total: scripts.length,
  passed: results.filter(r => r.status === 'pass').length,
  failed: results.filter(r => r.status === 'fail').length,
  results
}

if (args.json) {
  console.log(JSON.stringify(health, null, 2))
}

if (args.report) {
  const lines = [
    '# Contract Validation Report',
    '',
    'Generated: ' + health.timestamp,
    '',
    '## Summary',
    '',
    '| Metric | Value |',
    '|--------|-------|',
    '| Validators | ' + health.total + ' |',
    '| Passed | ' + health.passed + ' |',
    '| Failed | ' + health.failed + ' |',
    '| Status | ' + (health.failed === 0 ? '✅ PASS' : '❌ FAIL') + ' |',
    '',
    '## Results',
    '',
  ]
  for (const r of results) {
    lines.push('### ' + r.script + ' — ' + (r.status === 'pass' ? '✅' : '❌'))
    lines.push('')
    lines.push('```')
    lines.push((r.output || r.error || '').trim())
    lines.push('```')
    lines.push('')
  }
  const reportPath = path.join(ROOT, '.ai/reports/contract-validation.md')
  writeTextIdempotent(reportPath, lines.join('\n'))
  info('Report: .ai/reports/contract-validation.md')
}

const exitCode = args.strict ? (health.failed > 0 ? 1 : 0) : (hasError ? 1 : 0)
process.exitCode = exitCode

if (health.failed > 0 && args.strict) {
  fail('Strict mode: ' + health.failed + ' validator(s) failed')
}

const fs = require("fs");
const path = require("path");
const ROOT = process.cwd();

const IGNORE_DIRS = new Set(["node_modules", ".git", "dist", "coverage", ".ai/backups", "legado", "templates"]);
const IGNORE_FILES = new Set([".gitkeep", "ai-caused-incidents.md"]);
const EXECUTABLE_EXTS = new Set([".js", ".ts", ".sh", ".ps1", ".bat"]);
const DOC_EXTS = new Set([".md", ".yaml", ".yml", ".json"]);

const findings = [];

function walk(dir, files = []) {
  if (!fs.existsSync(dir)) return files;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (IGNORE_DIRS.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, files);
    } else {
      files.push(full);
    }
  }
  return files;
}

function rel(file) {
  return path.relative(ROOT, file).replace(/\\/g, "/");
}

function isScriptWithNoBehavior(content) {
  const hasConsole = /console\.(log|warn|error)/.test(content);
  const hasFs = /fs\.|require\(["']fs["']\)|from ["']node:fs["']/.test(content);
  const hasSpawn = /spawnSync|execSync|child_process/.test(content);
  const hasProcessExit = /process\.exit/.test(content);
  const hasArgs = /process\.argv|commander|Command/.test(content);
  const hasExports = /module\.exports|export |export default/.test(content);
  return hasConsole && !hasFs && !hasSpawn && !hasProcessExit && !hasArgs && !hasExports;
}

for (const file of walk(ROOT)) {
  const name = path.basename(file);
  const relative = rel(file);
  if (IGNORE_FILES.has(name)) continue;

  const ext = path.extname(file);
  if (!EXECUTABLE_EXTS.has(ext) && !DOC_EXTS.has(ext)) continue;

  const content = fs.readFileSync(file, "utf8").trim();
  if (content.length < 20) {
    findings.push({ file: relative, issue: "File is too small to provide real value" });
    continue;
  }

  if (ext === ".md") {
    const lines = content.split(/\r?\n/).filter((line) => line.trim());
    const nonHeading = lines.filter((line) => !line.trim().startsWith("#"));
    if (nonHeading.length === 0) {
      findings.push({ file: relative, issue: "Markdown contains only headings — no real content" });
    }
  }

  if (EXECUTABLE_EXTS.has(ext) && isScriptWithNoBehavior(content)) {
    findings.push({ file: relative, issue: "Executable file appears to only print messages without real behavior" });
  }
}

if (findings.length > 0) {
  console.error("Empty/decorative files check failed:");
  for (const finding of findings) {
    console.error(`- ${finding.file}: ${finding.issue}`);
  }
  process.exit(1);
}
console.log("Empty/decorative files check passed.");

