];

function toRel(file) {
  return path.relative(ROOT, file).replace(/\\/g, "/");
}

function isAllowed(rel, patternId) {
  if (rel.includes("node_modules") || rel.includes("legado")) return true;
  return ALLOWLIST.some((entry) => rel.endsWith(entry.file.split("/").pop()) && entry.ids.includes(patternId));
}

function classify(file) {
  const ext = path.extname(file);
  if (EXECUTABLE_EXTS.has(ext)) return "executable";
  if (CONFIG_EXTS.has(ext)) return "configuration";
  if (DOC_EXTS.has(ext)) return "documentation";
  return "other";
}

function walk(dir, files = []) {
  if (!fs.existsSync(dir)) return files;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (IGNORE_DIRS.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, files);
      continue;
    }
    const ext = path.extname(entry.name);
    if (EXECUTABLE_EXTS.has(ext) || CONFIG_EXTS.has(ext) || DOC_EXTS.has(ext)) {
      files.push(full);
    }
  }
  return files;
}

const findings = [];
for (const file of walk(ROOT)) {
  const rel = toRel(file);
  const content = fs.readFileSync(file, "utf8");
  const fileClass = classify(file);

  for (const pattern of DEFAULT_PATTERNS) {
    const matches = Array.from(content.matchAll(pattern.regex));
    if (matches.length === 0) continue;
    if (isAllowed(rel, pattern.id)) continue;

    findings.push({
      file: rel,
      fileClass,
      patternId: pattern.id,
      severity: pattern.severity,
      count: matches.length,
      action: (pattern.severity === "warn" || pattern.severity === "medium") ? "warn" : ((fileClass === "executable" || fileClass === "configuration") ? "fail" : "warn")
    });
  }
}

fs.mkdirSync(path.dirname(REPORT_PATH), { recursive: true });
fs.writeFileSync(REPORT_PATH, JSON.stringify({ generatedAt: new Date().toISOString(), findings }, null, 2));

const blocking = findings.filter((finding) => finding.action === "fail");
if (blocking.length > 0) {
  console.error("Placeholder policy failed:");
  for (const finding of blocking) {
    console.error(`- [${finding.severity}] ${finding.file} ${finding.patternId} (${finding.count})`);
  }
  process.exit(1);
}

if (findings.length > 0) {
  console.warn("Placeholder policy warnings:");
  for (const finding of findings) {
    console.warn(`- [${finding.severity}] ${finding.file} ${finding.patternId} (${finding.count})`);
  }
}
console.log("Placeholder policy check passed.");

const fs = require("fs");
const path = require("path");
const ROOT = process.cwd();

const FORBIDDEN_PATTERNS = [
  { id: "absolute.home.user", regex: /\/home\/user\//g },
  { id: "absolute.users", regex: /\/Users\/[^\/]+/g },
  { id: "absolute.windows.users", regex: /[A-Z]:\\\\Users\\\\[^\\\\]+/g },
  { id: "shell.cp", regex: /\bcp\s+-r\b/g },
  { id: "spawn.cp", regex: /spawnSync\(['"]cp['"]/g },
  { id: "shell.rm.rf", regex: /\brm\s+-rf\b/g },
  { id: "shell.xcopy", regex: /\bxcopy\b/g },
  { id: "shell.robocopy", regex: /\brobocopy\b/g }
];

const SCAN_EXTENSIONS = new Set([".js", ".ts", ".sh", ".ps1", ".bat", ".json", ".yaml", ".yml", ".md"]);
const IGNORE_DIRS = new Set(["node_modules", ".git", "dist", "coverage", "legado", "uploads", "index"]);

// Context Allowlist - Permite padrões em contextos inofensivos ou documentações ativas
const ALLOWLIST = [
  "active-prevention-rules.yaml",
  "command-policy.md",
  "permissions.yaml",
  "check-portability.js",
  "setup-report.md",
  "system-audit-execution.log",
  "latest-sync-report.json",
  "system-audit-execution.log"
];

function walk(dir, files = []) {
  if (!fs.existsSync(dir)) return files;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (IGNORE_DIRS.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, files);
    } else if (SCAN_EXTENSIONS.has(path.extname(entry.name))) {
      files.push(full);
    }
  }
  return files;
}

let failures = [];
for (const file of walk(ROOT)) {
  const isAllowlisted = ALLOWLIST.some(al => file.includes(al));
  if (isAllowlisted) continue;

  const content = fs.readFileSync(file, "utf8");
  for (const rule of FORBIDDEN_PATTERNS) {
    const matches = content.match(rule.regex);
    if (matches) {
      failures.push({
        rule: rule.id,
        file: path.relative(ROOT, file),
        matches: Array.from(new Set(matches))
      });
    }
  }
}

if (failures.length > 0) {
  console.error("Portability check failed:");
  for (const failure of failures) {
    console.error(`- [${failure.rule}] ${failure.file}: ${failure.matches.join(", ")}`);
  }
  process.exit(1);
}
console.log("Portability check passed. Allowed files bypassed via Policy.");

