#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, warn, printHelp, parseArgs } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('e2e-plan.js', 'node .ai/bin/e2e-plan.js [--out <dir>]', [
    '--out <dir>   Output dir for test files (default: tests/e2e/)',
    '--api <file>  OpenAPI spec path (default: docs/api/openapi.yaml)',
    '--help         Show this help'
  ])
  process.exit(0)
}

const apiPath = path.join(ROOT, args.api || 'docs/api/openapi.yaml')
if (!fs.existsSync(apiPath)) {
  warn('OpenAPI spec not found: ' + apiPath)
  info('Create docs/api/openapi.yaml first, then re-run.')
  process.exit(0)
}

const spec = fs.readFileSync(apiPath, 'utf-8')

const paths = []
const pathRegex = /^\s{2}(\/[^:]+):/gm
let m
while ((m = pathRegex.exec(spec)) !== null) {
  paths.push(m[1])
}

if (paths.length === 0) {
  warn('No paths found in OpenAPI spec')
  process.exit(0)
}

const outDir = path.join(ROOT, args.out || 'tests/e2e')
fs.mkdirSync(outDir, { recursive: true })

let generated = 0

for (const apiPath of paths) {
  const safeName = apiPath.replace(/[\/{}]/g, '_').replace(/^_|_$/g, '').replace(/_+/g, '-') || 'root'
  const methods = []
  if (spec.includes(apiPath + ':')) {
    const section = spec.split(apiPath + ':')[1]?.split(/\n\S/)[0] || ''
    if (section.includes('get:')) methods.push('GET')
    if (section.includes('post:')) methods.push('POST')
    if (section.includes('put:')) methods.push('PUT')
    if (section.includes('delete:')) methods.push('DELETE')
    if (section.includes('patch:')) methods.push('PATCH')
  }

  const testContent = [
    'import request from 'supertest''
    ''
    "const BASE_URL = process.env.TEST_URL || 'http://localhost:3000'"
    "const apiPath = '" + apiPath + "'"
    ''
    "describe('" + apiPath + "', () => {"
  ]

  for (const method of methods) {
    const httpMethod = method.toLowerCase()
    testContent.push("  describe('" + method + " " + apiPath + "', () => {")
    testContent.push("    it('should return valid response', async () => {")
    testContent.push("      const res = await request(BASE_URL)." + httpMethod + "(apiPath)")
    testContent.push("      expect(res.status).toBeGreaterThanOrEqual(200)")
    testContent.push("      expect(res.status).toBeLessThan(500)")
    testContent.push("    })")

    testContent.push('')
    testContent.push("    it('should handle authentication', async () => {")
    testContent.push("      const res = await request(BASE_URL)." + httpMethod + "(apiPath)")
    testContent.push("      expect([401, 403, 200]).toContain(res.status)")
    testContent.push("    })")

    if (['POST', 'PUT', 'PATCH'].includes(method)) {
      testContent.push('')
      testContent.push("    it('should reject invalid input', async () => {")
      testContent.push("      const res = await request(BASE_URL)." + httpMethod + "(apiPath).send({})")
      testContent.push("      expect([400, 422, 401, 403]).toContain(res.status)")
      testContent.push("    })")
    }
    testContent.push('  })')
    testContent.push('')
  }

  testContent.push('})')
  testContent.push('')

  const filePath = path.join(outDir, safeName + '.e2e-spec.ts')
  if (!fs.existsSync(filePath)) {
    fs.writeFileSync(filePath, testContent.join('\n'), 'utf-8')
    generated++
  }
}

info('E2E test skeletons generated: ' + generated + ' files in ' + path.relative(ROOT, outDir))
if (generated > 0) {
  info('Run with: npm run test:e2e')
}

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const yaml = require('js-yaml')
const { ROOT, info, printHelp, parseArgs, slugify } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
const name = args._[0]

if (args.help || !name) {
  printHelp('endpoint-generate.js', 'node .ai/bin/endpoint-generate.js <METHOD /path> [--module <name>]', [
    '<METHOD /path>   e.g. "POST /api/v1/users"',
    '--module <name>   Target module',
    '--help             Show this help'
  ])
  process.exit(args.help ? 0 : 1)
}

const parts = name.split(/\s+/)
const method = parts[0].toUpperCase()
const endpoint = parts[1] || '/'
const slug = slugify(endpoint.replace(/\//g, '-'))

const authzPath = path.join(ROOT, '.ai/permissions/matrix.md')
fs.mkdirSync(path.dirname(authzPath), { recursive: true })
const matrix = fs.existsSync(authzPath) ? fs.readFileSync(authzPath, 'utf-8') : '# Permissions Matrix\n\n| Endpoint | Method | SUPER_ADMIN | ADMIN | USER | Guest |\n|----------|--------|-------------|-------|------|-------|\n'

if (!matrix.includes(endpoint)) {
  const row = '| ' + endpoint + ' | ' + method + ' | S | S | N | N |'
  const lines = matrix.split(/\r?\n/)
  let insertAt = -1
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*\|[-\s|]+\|\s*$/.test(lines[i]) && i > 0) {
      insertAt = i + 1
      break
    }
  }
  if (insertAt === -1) {
    lines.push(row)
  } else {
    lines.splice(insertAt, 0, row)
  }
  const updated = lines.join('\n')
  fs.writeFileSync(authzPath, updated, 'utf-8')
  info('Permissions matrix updated: ' + method + ' ' + endpoint)
}

const openApiPath = path.join(ROOT, 'docs/api/openapi.yaml')
if (fs.existsSync(openApiPath)) {
  const raw = fs.readFileSync(openApiPath, 'utf-8')
  if (!raw.includes(endpoint + ':')) {
    try {
      const doc = yaml.load(raw) || {}
      doc.paths = doc.paths || {}
      doc.paths[endpoint] = doc.paths[endpoint] || {}
      doc.paths[endpoint][method.toLowerCase()] = {
        summary: 'PENDING_ACTION',
        operationId: slug.replace(/-/g, '_'),
        responses: {
          '200': { description: 'OK' },
          '400': { description: 'Bad Request' }
        }
      }
      const updated = yaml.dump(doc, { lineWidth: 120, noRefs: true })
      fs.writeFileSync(openApiPath, updated, 'utf-8')
      info('OpenAPI updated with ' + method + ' ' + endpoint)
    } catch (e) {
      info('WARN: nao foi possivel parsear docs/api/openapi.yaml como YAML (' + e.message + ') — endpoint ' + method + ' ' + endpoint + ' nao adicionado')
    }
  }
}

const planDir = path.join(ROOT, '.ai/features', slug)
fs.mkdirSync(planDir, { recursive: true })
const plan = [
  '# Endpoint Plan: ' + method + ' ' + endpoint,
  '', 'Generated: ' + new Date().toISOString(), '',
  '| Aspect | Value |', '|--------|-------|',
  '| Method | ' + method + ' |',
  '| Path | ' + endpoint + ' |',
  '| Required Role | ADMIN |',
  '| Rate Limit | 100/min |',
  '', '## Input', '- PENDING_ACTION', '', '## Output', '- PENDING_ACTION', '',
  'Permissions: .ai/permissions/matrix.md',
  'OpenAPI: docs/api/openapi.yaml'
].join('\n')
fs.writeFileSync(path.join(planDir, 'endpoint-plan.md'), plan, 'utf-8')

info('Endpoint generated: ' + method + ' ' + endpoint + ' (permissions + OpenAPI updated)')

#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { ROOT, info, printHelp, parseArgs } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('errors-map.js', 'node .ai/bin/errors-map.js [--catalog <file>]', [
    '--catalog <file>  Error catalog (default: .ai/errors/error-catalog.md)',
    '--help             Show this help'
  ])
  process.exit(0)
}

const catalogPath = path.join(ROOT, args.catalog || '.ai/errors/error-catalog.md')
if (!fs.existsSync(catalogPath)) {
  info('No error catalog found — run setup.js first')
  process.exit(0)
}

const content = fs.readFileSync(catalogPath, 'utf-8')

const errors = []
const headerPattern = /^###\s+(AIDK-\w+-\d+)\s+[—\-]\s+(.+)$/gm
let headerMatch
while ((headerMatch = headerPattern.exec(content)) !== null) {
  const code = headerMatch[1]
  const title = headerMatch[2].trim()

  const blockStart = headerMatch.index
  const nextHeader = content.indexOf('\n### ', blockStart + 1)
  const blockEnd = nextHeader === -1 ? content.length : nextHeader
  const block = content.slice(blockStart, blockEnd)

  const descMatch = block.match(/\*\*Descrição\*\*\s*:\s*(.+)/)
  const sevMatch = block.match(/\*\*Severidade\*\*\s*:\s*(.+)/)
  const actionMatch = block.match(/\*\*Ação\*\*\s*:\s*(.+)/)

  errors.push({
    code,
    title,
    description: descMatch ? descMatch[1].trim() : title,
    severity: sevMatch ? sevMatch[1].trim().toLowerCase() : 'error',
    action: actionMatch ? actionMatch[1].trim() : 'PENDING_ACTION'
  })
}

if (errors.length === 0) {
  console.warn('WARN: nenhuma entrada de erro extraida de ' + path.relative(ROOT, catalogPath) + ' — verifique se o catalogo usa o formato ### AIDK-CODE — descricao')
}

const mapPath = path.join(ROOT, '.ai/errors/error-flow-map.md')
const lines = [
  '# Error Flow Map',
  '', 'Generated: ' + new Date().toISOString(),
  'Total errors in catalog: ' + errors.length, '',
  '| Code | Title | Description | Severity | Action |',
  '|------|-------|-------------|----------|--------|',
]

