const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');
const backupManager = require('./backup-manager.js');

const LEDGER_PATH = path.join(process.cwd(), '.ai/audit/ledger.jsonl');
const GENESIS_HASH = '0'.repeat(64);

function getGitHead() {
    try { return execSync('git rev-parse HEAD', { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'ignore'] }).trim(); }
    catch (e) { return 'NO_GIT_REPO'; }
}

function getLastEntry() {
    if (!fs.existsSync(LEDGER_PATH)) return null;
    const lines = fs.readFileSync(LEDGER_PATH, 'utf-8').trim().split('\n').filter(Boolean);
    if (lines.length === 0) return null;
    return JSON.parse(lines[lines.length - 1]);
}

function computeEntryHash(entry) {
    const payload = `${entry.prevHash}|${entry.seq}|${entry.timestamp}|${entry.command}|${entry.exitCode}|${entry.outputHash}|${entry.gitHead}`;
    return crypto.createHash('sha256').update(payload).digest('hex');
}

function appendEntry(command, exitCode, output) {
    fs.mkdirSync(path.dirname(LEDGER_PATH), { recursive: true });
    const last = getLastEntry();
    const seq = last ? last.seq + 1 : 0;
    const prevHash = last ? last.thisHash : GENESIS_HASH;
    const outputHash = crypto.createHash('sha256').update(output).digest('hex');
    const entry = { seq, timestamp: new Date().toISOString(), command, exitCode, outputHash, gitHead: getGitHead(), prevHash };
    entry.thisHash = computeEntryHash(entry);
    fs.appendFileSync(LEDGER_PATH, JSON.stringify(entry) + '\n');
    backupManager.commitToBackup(entry);
    return entry;
}

function verifyLedger() {
    if (!fs.existsSync(LEDGER_PATH)) {
        return { valid: true, message: 'Ledger vazio (nenhuma execução registrada ainda).', entries: 0 };
    }
    const lines = fs.readFileSync(LEDGER_PATH, 'utf-8').trim().split('\n').filter(Boolean);
    let expectedPrev = GENESIS_HASH;
    for (let i = 0; i < lines.length; i++) {
        const entry = JSON.parse(lines[i]);
        if (entry.seq !== i) return { valid: false, message: `Sequência corrompida na linha ${i + 1}`, brokenAt: i };
        if (entry.prevHash !== expectedPrev) return { valid: false, message: `Cadeia de hash QUEBRADA na linha ${i + 1}. Entrada editada ou removida.`, brokenAt: i };
        const recomputed = computeEntryHash({ ...entry, thisHash: undefined });
        if (recomputed !== entry.thisHash) return { valid: false, message: `Hash da entrada ${i + 1} não confere. Conteúdo ADULTERADO.`, brokenAt: i };
        expectedPrev = entry.thisHash;
    }
    return { valid: true, message: `✅ Cadeia íntegra. ${lines.length} execuções verificadas.`, entries: lines.length };
}

module.exports = { appendEntry, verifyLedger, getLastEntry };

#!/usr/bin/env node
'use strict'
// Biblioteca comum para scripts em .ai/bin
const fs = require('fs')
const path = require('path')

const ROOT = path.resolve(__dirname, '../../..')

const COLORS = { g: '\x1b[32m', y: '\x1b[33m', r: '\x1b[31m', c: '\x1b[36m', reset: '\x1b[0m' }

function log(msg)  { console.log(COLORS.g + msg + COLORS.reset) }
function info(msg) { console.log(COLORS.c + '-> ' + msg + COLORS.reset) }
function warn(msg) { console.log(COLORS.y + 'AVISO: ' + msg + COLORS.reset) }
function fail(msg) { console.error(COLORS.r + 'ERRO: ' + msg + COLORS.reset); process.exit(1) }

function parseArgs(argv) {
  const args = { _: [] }
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]
    if (a === '--help' || a === '-h') { args.help = true; continue }
    if (a.startsWith('--')) {
      const key = a.slice(2)
      const next = argv[i + 1]
      if (next && !next.startsWith('--')) { args[key] = next; i++ } else { args[key] = true }
      continue
    }
    args._.push(a)
  }
  return args
}

function printHelp(name, usage, options) {
  console.log('Uso: ' + usage)
  console.log('')
  console.log(name)
  if (options && options.length) {
    console.log('')
    console.log('Opcoes:')
    options.forEach(o => console.log('  ' + o))
  }
}

function ensureDir(p) { fs.mkdirSync(p, { recursive: true }) }

function readTextSafe(p) {
  try { return fs.readFileSync(p, 'utf-8') } catch (e) { return null }
}

function writeTextIdempotent(p, content) {
  ensureDir(path.dirname(p))
  const current = readTextSafe(p)
  if (current === content) return { changed: false }
  fs.writeFileSync(p, content, 'utf-8')
  return { changed: true, created: current === null }
}

function slugify(str) {
  return String(str)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
}

module.exports = {
  ROOT, log, info, warn, fail, parseArgs, printHelp,
  ensureDir, readTextSafe, writeTextIdempotent, slugify
}

#!/usr/bin/env node
'use strict'
// Renderizador simples de templates com placeholders {{variavel}}

function render(templateStr, vars) {
  vars = vars || {}
  return templateStr.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (match, key) => {
    return Object.prototype.hasOwnProperty.call(vars, key) ? String(vars[key]) : match
  })
}

function renderFile(fs, filePath, vars) {
  const raw = fs.readFileSync(filePath, 'utf-8')
  return render(raw, vars)
}

module.exports = { render, renderFile }

#!/usr/bin/env node
'use strict'
// Validadores basicos reutilizaveis pelos scripts de .ai/bin

function isNonEmptyString(v) { return typeof v === 'string' && v.trim().length > 0 }
function isKebabCase(v) { return typeof v === 'string' && /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/.test(v) }
function assert(condition, message) { if (!condition) throw new Error(message) }
function hasKeys(obj, keys) {
  return keys.every(k => obj && Object.prototype.hasOwnProperty.call(obj, k))
}

module.exports = { isNonEmptyString, isKebabCase, assert, hasKeys }

