#!/usr/bin/env node
'use strict'
const fs = require('fs')
const path = require('path')
const { execSync } = require('child_process')
const { ROOT, info, printHelp, parseArgs, readTextSafe, writeTextIdempotent } = require('./lib/common')

const args = parseArgs(process.argv.slice(2))
if (args.help) {
  printHelp('release-notes.js', 'node .ai/bin/release-notes.js [--out <file>] [--since <tag>]', [
    '--out <file>    Output path (default: .ai/release/release-notes-draft.md)',
    '--since <tag>   Git ref to start from (default: last tag)',
    '--help           Show this help'
  ])
  process.exit(0)
}

function getGitLog(since) {
  try {
    const range = since || (function() {
      try { return execSync('git describe --tags --abbrev=0 2>nul', { cwd: ROOT, encoding: 'utf-8' }).trim() } catch(e) { return '' }
    })()
    const cmd = range ? `git log ${range}..HEAD --format="%s"` : 'git log --format="%s"'
    const output = execSync(cmd, { cwd: ROOT, encoding: 'utf-8', stdio: ['pipe','pipe','ignore'] })
    return output.trim().split(/\r?\n/).filter(Boolean)
  } catch (e) {
    return []
  }
}

function parseConventionalCommit(msg) {
  const m = msg.match(/^(\w+)(\(([^)]+)\))?(!)?\s*:\s*(.+)/)
  if (!m) return { type: 'other', scope: '', breaking: false, desc: msg }
  return { type: m[1], scope: m[3] || '', breaking: !!m[4] || msg.includes('BREAKING CHANGE'), desc: m[5].trim() }
}

const commits = getGitLog(args.since)
const parsed = commits.map(parseConventionalCommit)

const byType = {}
const typeLabels = { feat: 'Features', fix: 'Bug Fixes', docs: 'Documentation', style: 'Styles', refactor: 'Refactoring', perf: 'Performance', test: 'Tests', build: 'Build', ci: 'CI', chore: 'Chores', revert: 'Reverts', other: 'Other' }
for (const c of parsed) {
  const key = c.type
  if (!byType[key]) byType[key] = []
  byType[key].push(c)
}

const order = ['feat', 'fix', 'perf', 'refactor', 'test', 'docs', 'style', 'build', 'ci', 'chore', 'revert', 'other']

let hasBreaking = false
let hasFeat = false
let hasFix = false

const lines = [
  '# Release Notes (rascunho)',
  '',
  `Gerado em: ${new Date().toISOString()}`,
  `Commits analisados: ${commits.length}`,
  ''
]

for (const type of order) {
  const items = byType[type]
  if (!items || items.length === 0) continue
  lines.push('## ' + (typeLabels[type] || type))
  lines.push('')
  for (const item of items) {
    const scope = item.scope ? '**' + item.scope + '**: ' : ''
    const breaking = item.breaking ? ' [BREAKING]' : ''
    lines.push('- ' + scope + item.desc + breaking)
  }
  lines.push('')
}

for (const c of parsed) {
  if (c.type === 'feat') hasFeat = true
  if (c.type === 'fix') hasFix = true
  if (c.breaking) hasBreaking = true
}

let bump = 'patch'
if (hasBreaking) bump = 'major'
else if (hasFeat) bump = 'minor'

lines.push('## Suggested Version Bump')
lines.push('')
lines.push('- **' + bump.toUpperCase() + '** (' + (hasBreaking ? 'breaking changes detected' : hasFeat ? 'new features' : 'fixes only') + ')')
lines.push('')

const changesetDir = path.join(ROOT, '.changeset')
const changesets = fs.existsSync(changesetDir)
  ? fs.readdirSync(changesetDir).filter(f => f.endsWith('.md') && f !== 'README.md')
  : []
if (changesets.length > 0) {
  lines.push('## Changesets pendentes (' + changesets.length + ')')
  lines.push('')
  changesets.forEach(f => {
    const content = readTextSafe(path.join(changesetDir, f))
    lines.push('### ' + f)
    lines.push('')
    lines.push(content || '(vazio)')
    lines.push('')
  })
}

const done = readTextSafe(path.join(ROOT, '.ai/tasks/done.md'))
if (done) {
  lines.push('## Tarefas concluidas (.ai/tasks/done.md)')
  lines.push('')
  lines.push(done.trim())
  lines.push('')
}

const outPath = path.join(ROOT, args.out || '.ai/release/release-notes-draft.md')
writeTextIdempotent(outPath, lines.join('\n'))
info('Release notes generated: ' + path.relative(ROOT, outPath) + ' (suggested bump: ' + bump + ')')

#!/usr/bin/env node
// release.js -- valida checklists e artefatos de entrega
'use strict'
const fs = require('fs')
const path = require('path')
const ROOT = path.resolve(__dirname, '../..')

const checks = [
  { path: '.ai/checklists/release-readiness-checklist.md', label: 'Release readiness checklist' },
  { path: '.ai/checklists/ai-release-checklist.md', label: 'AI release checklist' },
  { path: '.ai/context/ai-handoff.md', label: 'AI handoff context' },
  { path: '.ai/tasks/current-task.md', label: 'Current task' },
  { path: '.ai/project-manifest.yaml', label: 'Project manifest' },
  { path: '.ai/architecture/adr', label: 'Architecture ADRs', optionalDir: true },
  { path: '.ai/errors/error-catalog.md', label: 'Error catalog' },
  { path: '.ai/technologies/ai-guide.md', label: 'AI delivery guide' },
  { path: '.ai/reports', label: 'Reports directory', optionalDir: true },
]

const requiredInReleaseChecklist = [
  'Prompt de release escolhido: 26-high-quality-delivery.md',
  'Contexto de projeto atualizado em .ai/context/ai-handoff.md',
  'Tarefa atual definida em .ai/tasks/current-task.md',
  'Stack e regras confirmadas em .ai/project-manifest.yaml',
  'Decisões recentes documentadas em .ai/architecture/adr/',
  'Erros e contratos revisados em .ai/errors/error-catalog.md e .ai/contracts/',
]
const requiredInReadinessChecklist = [
  'Todos os testes passando',
  'Segurança revisado',
  'Deploy documentado e rollback previsto',
  'Documentação dos módulos atualizada',
  'Contexto da IA e session-log atualizados',
]

let errors = []
let warnings = []

function exists(file) {
  return fs.existsSync(path.join(ROOT, file))
}

function read(file) {
  const full = path.join(ROOT, file)
  return fs.existsSync(full) ? fs.readFileSync(full, 'utf-8') : ''
}

console.log('\nrelease.js -- validando artefatos de entrega...\n')

for (const check of checks) {
  const full = path.join(ROOT, check.path)
  if (!fs.existsSync(full)) {
    errors.push(`FALHA: ${check.label} ausente (${check.path})`)
    continue
  }
  if (check.optionalDir && fs.statSync(full).isDirectory()) {
    console.log(`OK: ${check.label}`)
    continue
  }
  const content = fs.readFileSync(full, 'utf-8')
  if (content.trim().length === 0) {
    errors.push(`FALHA: ${check.label} vazio (${check.path})`)
  } else {
    console.log(`OK: ${check.label}`)
  }
}

const releaseChecklist = read('.ai/checklists/ai-release-checklist.md')
for (const marker of requiredInReleaseChecklist) {
  if (!releaseChecklist.includes(marker)) {
    warnings.push(`Aviso: item ausente em ai-release-checklist.md => ${marker}`)
  }
}

const readinessChecklist = read('.ai/checklists/release-readiness-checklist.md')
for (const marker of requiredInReadinessChecklist) {
  if (!readinessChecklist.includes(marker)) {
    warnings.push(`Aviso: item ausente em release-readiness-checklist.md => ${marker}`)
  }
}

const reportPath = path.join(ROOT, '.ai/reports/release-report.md')
const reportLines = [
  '# Release Report',
  '',
  `Data: ${new Date().toISOString()}`,
  '',
  '## Status',
  errors.length > 0 ? 'FAILED' : 'OK',
  '',
  '## Erros',
  errors.length > 0 ? errors.map(e => '- ' + e).join('\n') : '- Nenhum',
  '',
  '## Avisos',
  warnings.length > 0 ? warnings.map(w => '- ' + w).join('\n') : '- Nenhum',
  '',
  '## Checagens',
  checks.map(check => `- [${exists(check.path) ? 'x' : ' '}] ${check.label}`).join('\n'),
]
fs.mkdirSync(path.dirname(reportPath), { recursive: true })
fs.writeFileSync(reportPath, reportLines.join('\n'), 'utf-8')

console.log('\nRelatorio de release gerado: .ai/reports/release-report.md')
if (errors.length > 0) {
  console.error('\nErros detectados:')
  errors.forEach(line => console.error('  ' + line))
  console.error('\nCorrija os erros e execute novamente: npm run ai:release')
  process.exit(1)
}

if (warnings.length > 0) {
  console.warn('\nAvisos:')
  warnings.forEach(line => console.warn('  ' + line))
  console.log('\nRevise os avisos antes de liberar.')
} else {
  console.log('\nRelease validation passed. Pronto para entregar.')
}

