import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

export interface Attestation {
  id: string;
  timestamp: string;
  check_type: string;
  result: 'pass' | 'fail' | 'warn';
  details?: string;
  signature: string;
  prev_signature: string;
  revoked?: boolean;
  revoke_reason?: string;
}

const SECRET_FILE = '.ai/audit/secret';
const STORAGE_DIR = '.ai/attestations';

function getOrCreateSecret(root: string): string {
  const secretPath = path.join(root, SECRET_FILE);
  const dir = path.dirname(secretPath);

  if (fs.existsSync(secretPath)) {
    return fs.readFileSync(secretPath, 'utf8').trim();
  }

  fs.mkdirSync(dir, { recursive: true });
  const secret = crypto.randomBytes(32).toString('hex');
  fs.writeFileSync(secretPath, secret, { mode: 0o600 });
  return secret;
}

function computeSignature(data: string, key: string): string {
  return crypto.createHmac('sha256', key).update(data).digest('hex');
}

function getLastAttestation(root: string): Attestation | null {
  const storagePath = path.join(root, STORAGE_DIR);
  const filePath = path.join(storagePath, 'chain.jsonl');
  if (!fs.existsSync(filePath)) return null;

  const lines = fs.readFileSync(filePath, 'utf8').trim().split('\n').filter(Boolean);
  if (lines.length === 0) return null;

  try {
    return JSON.parse(lines[lines.length - 1]) as Attestation;
  } catch {
    return null;
  }
}

function appendAttestation(root: string, attestation: Attestation): void {
  const storagePath = path.join(root, STORAGE_DIR);
  fs.mkdirSync(storagePath, { recursive: true });
  const filePath = path.join(storagePath, 'chain.jsonl');
  fs.appendFileSync(filePath, JSON.stringify(attestation) + '\n');
}

export function createAttestation(
  root: string,
  checkType: string,
  result: 'pass' | 'fail' | 'warn',
  details?: string
): Attestation {
  const secret = getOrCreateSecret(root);
  const last = getLastAttestation(root);
  const prevSignature = last ? last.signature : 'genesis';

  const id = crypto.randomUUID();
  const timestamp = new Date().toISOString();
  const payload = JSON.stringify({ id, timestamp, check_type: checkType, result, prev_signature: prevSignature, details });
  const signature = computeSignature(payload, secret);

  const attestation: Attestation = { id, timestamp, check_type: checkType, result, details, signature, prev_signature: prevSignature };
  appendAttestation(root, attestation);
  return attestation;
}

export function loadChain(root: string): Attestation[] {
  const storagePath = path.join(root, STORAGE_DIR);
  const filePath = path.join(storagePath, 'chain.jsonl');
  if (!fs.existsSync(filePath)) return [];

  return fs.readFileSync(filePath, 'utf8')
    .trim()
    .split('\n')
    .filter(Boolean)
    .map(line => JSON.parse(line) as Attestation);
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  attestations: number;
}

export function validateChain(root: string): ValidationResult {
  const chain = loadChain(root);
  const errors: string[] = [];
  const secret = getOrCreateSecret(root);

  for (let i = 0; i < chain.length; i++) {
    const att = chain[i];

    const expectedPrev = i === 0 ? 'genesis' : chain[i - 1].signature;
    if (att.prev_signature !== expectedPrev) {
      errors.push(`Atestacao ${att.id}: prev_signature invalida (elo ${i})`);
    }

    const payload = JSON.stringify({ id: att.id, timestamp: att.timestamp, check_type: att.check_type, result: att.result, prev_signature: expectedPrev, details: att.details });
    const expectedSig = computeSignature(payload, secret);
    if (att.signature !== expectedSig) {
      errors.push(`Atestacao ${att.id}: assinatura invalida (elo ${i}) — ATESTACAO ADULTERADA`);
    }
  }

  return { valid: errors.length === 0, errors, attestations: chain.length };
}

export function revokeAttestation(root: string, id: string, reason?: string): boolean {
  const chain = loadChain(root);
  const idx = chain.findIndex(a => a.id === id);
  if (idx === -1) return false;

  chain[idx].revoked = true;
  chain[idx].revoke_reason = reason || 'Revogado manualmente';

  const storagePath = path.join(root, STORAGE_DIR);
  fs.mkdirSync(storagePath, { recursive: true });
  fs.writeFileSync(path.join(storagePath, 'chain.jsonl'), chain.map(a => JSON.stringify(a)).join('\n') + '\n');
  return true;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";

interface AdapterInfo {
  name: string;
  path: string;
  hasPackageJson: boolean;
  hasReadme: boolean;
  hasSrcOrIndex: boolean;
}

const KNOWN_ADAPTER_DIR_PREFIX = "adapter-";

function findMonorepoRoot(startDir: string): string | null {
  let dir = startDir;
  for (let i = 0; i < 6; i++) {
    if (fs.existsSync(path.join(dir, "packages"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

function listAdapters(root: string): AdapterInfo[] {
  const packagesDir = path.join(root, "packages");
  if (!fs.existsSync(packagesDir)) return [];

  return fs
    .readdirSync(packagesDir)
    .filter((name) => name.startsWith(KNOWN_ADAPTER_DIR_PREFIX))
    .map((name) => {
      const adapterPath = path.join(packagesDir, name);
      return {
        name,
        path: adapterPath,
        hasPackageJson: fs.existsSync(path.join(adapterPath, "package.json")),
        hasReadme:
          fs.existsSync(path.join(adapterPath, "README.md")) ||
          fs.existsSync(path.join(adapterPath, "readme.md")),
        hasSrcOrIndex:
          fs.existsSync(path.join(adapterPath, "src")) ||
          fs.existsSync(path.join(adapterPath, "index.js")) ||
          fs.existsSync(path.join(adapterPath, "index.ts")),
      };
    });
}

function detectProjectStack(projectRoot: string): string[] {
  const detected: string[] = [];

  const pkgJsonPath = path.join(projectRoot, "package.json");
  if (fs.existsSync(pkgJsonPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(pkgJsonPath, "utf8"));
      const deps = { ...pkg.dependencies, ...pkg.devDependencies };
      if (deps["@nestjs/core"]) detected.push("nestjs");
      if (deps["fastify"]) detected.push("fastify");
      if (deps["express"]) detected.push("express");
      if (deps["next"]) detected.push("nextjs");
    } catch {
      // package.json malformado — reportar mas não travar
      detected.push("unknown (package.json inválido)");
    }
  }

  if (fs.existsSync(path.join(projectRoot, "requirements.txt"))) {
    const content = fs.readFileSync(path.join(projectRoot, "requirements.txt"), "utf8");
    if (/fastapi/i.test(content)) detected.push("fastapi");
  }

  if (fs.existsSync(path.join(projectRoot, "go.mod"))) {
    detected.push("go");
  }

  return detected;
}

function validateAdapter(adapter: AdapterInfo): string[] {
  const problems: string[] = [];
  if (!adapter.hasPackageJson) problems.push("missing package.json");
  if (!adapter.hasReadme) problems.push("missing README.md");
  if (!adapter.hasSrcOrIndex) problems.push("missing src/ or index entrypoint");
  return problems;
}

export function adapterCommand(): Command {
  const adapterCmd = new Command("adapter")
    .description("Lista, detecta e valida adapters");

  adapterCmd
    .command("list")
    .description("Lista todos os adapters disponíveis no monorepo")
    .action(() => {
      const root = findMonorepoRoot(process.cwd());
      if (!root) {
        console.error("❌ Não foi possível localizar o diretório packages/ (monorepo).");
        process.exitCode = 1;
        return;
      }

      const adapters = listAdapters(root);
      if (adapters.length === 0) {
        console.log("Nenhum adapter encontrado em packages/.");
        return;
      }

      console.log(`Adapters encontrados (${adapters.length}):\n`);
      for (const a of adapters) {
        console.log(`- ${a.name}`);
      }
    });

  adapterCmd
    .command("detect")
    .description("Detecta a stack do projeto atual")
    .action(() => {
      const detected = detectProjectStack(process.cwd());
      if (detected.length === 0) {
        console.log("Nenhuma stack conhecida detectada no projeto atual.");
        process.exitCode = 1;
        return;
      }
      console.log("Stack(s) detectada(s):\n");
      detected.forEach((s) => console.log(`- ${s}`));
    });

  adapterCmd
    .command("validate")
    .description("Valida a integridade dos adapters do monorepo")
    .action(() => {
      const root = findMonorepoRoot(process.cwd());
      if (!root) {
        console.error("❌ Não foi possível localizar o diretório packages/ (monorepo).");
        process.exitCode = 1;
        return;
      }

      const adapters = listAdapters(root);
      if (adapters.length === 0) {
        console.log("Nenhum adapter encontrado para validar.");
        return;
      }

      let hasProblems = false;
      for (const adapter of adapters) {
        const problems = validateAdapter(adapter);
        if (problems.length === 0) {
          console.log(`✅ ${adapter.name}: OK`);
        } else {
          hasProblems = true;
          console.log(`❌ ${adapter.name}:`);
          problems.forEach((p) => console.log(`   - ${p}`));
        }
      }

      if (hasProblems) process.exitCode = 1;
    });

  return adapterCmd;
}

