        });
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { computeStatus } from "./status";

type AuditFinding = {
  id: string;
  severity: "low" | "medium" | "high" | "critical";
  category: "security" | "architecture" | "quality" | "documentation" | "ux" | "communication";
  title: string;
  description: string;
  recommendation: string;
};

function exists(file: string): boolean {
  return fs.existsSync(path.join(process.cwd(), file));
}

function auditProject(): AuditFinding[] {
  const findings: AuditFinding[] = [];

      const auditChecks = [
        ".ai/bin/check-placeholder-policy.js",
        ".ai/bin/check-generated-code-risk.js",
        ".ai/bin/check-package-scripts.js",
        ".ai/bin/check-template-consistency.js",
        ".ai/bin/check-artifact-manifest.js"
      ];

      console.log("\nRunning deep audit checks...");
      for (const check of auditChecks) {
         const fullPath = path.join(process.cwd(), check);
         if (fs.existsSync(fullPath)) {
            const res = spawnSync("node", [fullPath], { stdio: "inherit", cwd: process.cwd(), env: { ...process.env, AI_DEVKIT_STRICT_AUDIT: "1" } });
            if (res.status !== 0) {
               console.log(`\n❌ Audit failed at ${check}`);
               process.exit(1);
            }
         }
      }

      const statusReport = computeStatus();
      if (statusReport.belowRecommended) {
         findings.push({
           id: "STATUS-CHECK-FAILED",
           severity: "high",
           category: "architecture",
           title: "Project Status Check Failed",
           description: "The 'ai-devkit status' command reported health issues.",
           recommendation: "Run 'ai-devkit status' and resolve the reported issues."
         });
      }


  if (!exists(".ai/security/agent-safety-policy.md")) {
    findings.push({
      id: "SEC-AGENT-POLICY-MISSING",
      severity: "high",
      category: "security",
      title: "Política de segurança dos agentes ausente",
      description: "Agentes ativos sem política formal podem realizar ações inseguras.",
      recommendation: "Criar .ai/security/agent-safety-policy.md."
    });
  }

  if (!exists(".ai/architecture/adapter-contract.md")) {
    findings.push({
      id: "ARCH-ADAPTER-CONTRACT-MISSING",
      severity: "high",
      category: "architecture",
      title: "Contrato de adapters ausente",
      description: "Sem contrato, adapters podem divergir e quebrar suporte multi-linguagem.",
      recommendation: "Criar .ai/architecture/adapter-contract.md."
    });
  }

  if (!exists(".ai/quality/definition-of-done.md")) {
    findings.push({
      id: "QLT-DOD-MISSING",
      severity: "medium",
      category: "quality",
      title: "Definition of Done ausente",
      description: "Funcionalidades podem ser consideradas prontas sem verificação ponta a ponta.",
      recommendation: "Criar .ai/quality/definition-of-done.md."
    });
  }

  if (!exists(".ai/context/communication-protocol.md")) {
    findings.push({
      id: "COMM-PROTOCOL-MISSING",
      severity: "medium",
      category: "communication",
      title: "Protocolo de comunicação ausente",
      description: "Sem protocolo interpretativo, modelos de IA podem entender mal pedidos humanos.",
      recommendation: "Criar .ai/context/communication-protocol.md."
    });
  }

  if (!exists(".ai/architecture/ui-ux-intelligence-engine.md")) {
    findings.push({
      id: "UX-ENGINE-MISSING",
      severity: "medium",
      category: "ux",
      title: "UI/UX Intelligence Engine ausente",
      description: "Modelos podem gerar telas funcionais, mas pobres em usabilidade e refinamento visual.",
      recommendation: "Criar .ai/architecture/ui-ux-intelligence-engine.md."
    });
  }

  if (!exists(".ai/design/design-system.md")) {
    findings.push({
      id: "DESIGN-SYSTEM-MISSING",
      severity: "medium",
      category: "ux",
      title: "Design System ausente",
      description: "Sem design system, interfaces tendem a ficar inconsistentes entre telas.",
      recommendation: "Criar .ai/design/design-system.md."
    });
  }

  if (!exists(".ai/design/interface-quality-gate.md")) {
    findings.push({
      id: "INTERFACE-QUALITY-GATE-MISSING",
      severity: "medium",
      category: "ux",
      title: "Interface Quality Gate ausente",
      description: "Sem quality gate visual, telas ruins podem ser consideradas prontas.",
      recommendation: "Criar .ai/design/interface-quality-gate.md."
    });
  }

  return findings;
}

export function auditCommand(): Command {
  return new Command("audit")
    .description("Executa auditoria de segurança, arquitetura, qualidade, documentação, comunicação e UX")
    .option("--json", "Emitir JSON")
    .option("--dry-run", "Não criar relatório")
    .action((options) => {
      const findings = auditProject();
      const ok = !findings.some((finding) => ["high", "critical"].includes(finding.severity));

      if (options.json) {
        console.log(JSON.stringify({ ok, findings }, null, 2));
        process.exit(ok ? 0 : 1);
      }

      console.log("\nAI DevKit Audit\n");

      if (findings.length === 0) {
        console.log("✅ Nenhum problema encontrado.");
        return;
      }

      for (const finding of findings) {
        const icon =
          finding.severity === "critical"
            ? "🔴"
            : finding.severity === "high"
              ? "🟠"
              : finding.severity === "medium"
                ? "🟡"
                : "🔵";

        console.log(`${icon} [${finding.severity}] ${finding.title}`);
        console.log(`   Categoria: ${finding.category}`);
        console.log(`   ${finding.description}`);
        console.log(`   Recomendação: ${finding.recommendation}\n`);
      }

      if (!options.dryRun) {
        const reportDir = path.join(process.cwd(), ".ai/reports");
        fs.mkdirSync(reportDir, { recursive: true });

        const report = `# Audit Report — ${new Date().toISOString()}

${findings
  .map(
    (finding) => `## ${finding.id} — ${finding.title}

- Severidade: ${finding.severity}
- Categoria: ${finding.category}

### Descrição

${finding.description}

### Recomendação

${finding.recommendation}
`
  )
  .join("\n")}
`;

        fs.writeFileSync(path.join(reportDir, `audit-${new Date().toISOString().slice(0, 10)}.md`), report, "utf8");
      }

      process.exit(ok ? 0 : 1);
    });
}

