// ============================================================
// TASK-GAP-01: 13+ formatos de compilação
// TASK-GAP-02: Path-Scoped Rules para monorepos
// ============================================================

const TARGETS = [
  'claude', 'cursor', 'copilot', 'windsurf', 'cline',
  'gemini', 'continue', 'zed', 'amazon-q', 'codex',
  'aider', 'cursor-mdc', 'github-actions',
] as const;
type Target = typeof TARGETS[number];

interface LawsConfig {
  architecture?: string;
  defensive_programming?: boolean;
  contract_first?: boolean;
  rules?: string[];
  path_scoped_rules?: Record<string, string[]>;
}

interface PathScopedOutput {
  path: string;
  content: string;
}

function readLaws(root: string): LawsConfig {
  const lawsPath = path.join(root, '.ai/laws.yaml');
  if (!fs.existsSync(lawsPath)) return { rules: [] };
  try { return YAML.parse(fs.readFileSync(lawsPath, 'utf8')) || {}; }
  catch { return { rules: [] }; }
}

function readManifest(root: string): Record<string, unknown> {
  const manifestPath = path.join(root, '.ai/project-manifest.yaml');
  if (!fs.existsSync(manifestPath)) return {};
  try { return YAML.parse(fs.readFileSync(manifestPath, 'utf8')) || {}; }
  catch { return {}; }
}

function readGlobalRules(root: string): string[] {
  const rulesPath = path.join(root, '.ai/rules/global.rules.md');
  if (fs.existsSync(rulesPath)) {
    return fs.readFileSync(rulesPath, 'utf8').split('\n')
      .map(l => l.replace(/^- /, '').trim())
      .filter(l => l.length > 0 && !l.startsWith('#'));
  }
  return [];
}

function readPolicies(root: string): string[] {
  const policiesDir = path.join(root, '.ai/policies');
  const policyLines: string[] = [];
  if (fs.existsSync(policiesDir)) {
    const files = fs.readdirSync(policiesDir).filter(f => f.endsWith('.yaml') || f.endsWith('.yml'));
    for (const file of files) {
      const content = fs.readFileSync(path.join(policiesDir, file), 'utf8');
      const parsed = YAML.parse(content);
      if (parsed?.forbidden_tokens) {
        policyLines.push(`Forbidden tokens: ${parsed.forbidden_tokens.join(', ')}`);
      }
      if (parsed?.required_files) {
        policyLines.push(`Required files: ${parsed.required_files.join(', ')}`);
      }
    }
  }
  return policyLines;
}

function getBaseRules(laws: LawsConfig, globalRules: string[], policies: string[]): string[] {
  return [...(laws.rules || []), ...globalRules, ...policies];
}

function getProjectName(manifest: Record<string, unknown>): string {
  return ((manifest as any)?.project?.name) || 'project';
}

function getFramework(manifest: Record<string, unknown>): string {
  return (manifest as any)?.backend?.framework || 'unknown';
}

function getCoverageMin(manifest: Record<string, unknown>): number {
  return (manifest as any)?.quality?.coverage_min || 80;
