export function compileCommand(): Command {
  const cmd = new Command('compile')
    .description('Compila regras de governanca para formatos nativos de ferramentas de IA (13+ formatos)');

  cmd
    .command('all')
    .description('Compila para todos os 13 formatos disponiveis')
    .option('--dry-run', 'Mostra o que seria gerado sem escrever')
    .action((options: { dryRun?: boolean }) => {
      const root = process.cwd();
      const manifest = readManifest(root);
      const laws = readLaws(root);
      const globalRules = readGlobalRules(root);
      const policies = readPolicies(root);

      printHeader('Governance Compiler — 13+ Targets');
      printLine(`Rules found: ${(laws.rules?.length || 0) + globalRules.length + policies.length}`);
      printLine(`Targets: ${TARGETS.join(', ')}`);

      const generated: string[] = [];
      const errors: string[] = [];

      for (const target of TARGETS) {
        const content = COMPILERS[target](manifest, laws, globalRules, policies);
        const relativePath = TARGET_PATHS[target];
        const fullPath = path.join(root, relativePath);

        if (!options.dryRun) {
          try {
            fs.mkdirSync(path.dirname(fullPath), { recursive: true });
            fs.writeFileSync(fullPath, content);
            printResult(target, true, relativePath);
            generated.push(relativePath);
          } catch (err: unknown) {
            const msg = err instanceof Error ? err.message : String(err);
            printResult(target, false, msg);
            errors.push(msg);
          }
        } else {
          printLine(`[DRY-RUN] ${relativePath} (${content.length} bytes)`);
          generated.push(`${relativePath} (dry-run)`);
        }
      }

      // TASK-GAP-02: Path-Scoped Rules
      const scopedOutputs = getPathScopedOutputs(root, manifest, laws, globalRules, policies);
      for (const output of scopedOutputs) {
        if (!options.dryRun) {
          try {
            const fullPath = path.join(root, output.path);
            fs.mkdirSync(path.dirname(fullPath), { recursive: true });
            fs.writeFileSync(fullPath, output.content);
            printLine(`  [SCOPED] ${output.path}`);
            generated.push(output.path);
          } catch (err: unknown) {
            const msg = err instanceof Error ? err.message : String(err);
            errors.push(msg);
          }
        } else {
          printLine(`[DRY-RUN] [SCOPED] ${output.path} (${output.content.length} bytes)`);
          generated.push(`${output.path} (dry-run)`);
        }
      }

      const ok = errors.length === 0;
      finish({
        checkpoint: 'compile',
        ok,
        status: ok ? 'passed' : 'failed',
        context_summary: ok
          ? `Compilado ${generated.length} arquivos: ${generated.join(', ')}`
          : `Erros: ${errors.join('; ')}`,
        data: { generated, errors, targetsCount: TARGETS.length },
      });
    });

  cmd
    .command('list')
    .description('Lista os 13 formatos disponiveis')
    .action(() => {
      printHeader('Formatos Disponiveis (13 targets)');
      for (const target of TARGETS) {
        printLine(`  ${target.padEnd(15)} → ${TARGET_PATHS[target]}`);
      }
      printLine('');
      printLine('Path-Scoped Rules:');
      printLine('  Gera .clinerules e .cursorrules por subdiretorio');
      printLine('  Configure em .ai/laws.yaml > path_scoped_rules');
    });

  // TASK-GAP-03: Auto-Recompile Watch
  cmd
    .command('watch')
    .description('Monitora .ai/laws.yaml e recompila automaticamente ao detectar mudancas')
    .option('--interval <ms>', 'Intervalo de verificacao em milissegundos', '5000')
    .action((options: { interval?: string }) => {
      const root = process.cwd();
      const intervalMs = parseInt(options.interval || '5000', 10);
      printHeader('Auto-Recompile Watch (TASK-GAP-03)');
      printLine(`Root: ${root}`);
      printLine(`Interval: ${intervalMs}ms`);
      printLine('Press Ctrl+C to stop');
      printLine('');

      // Compile once at start
      const manifest = readManifest(root);
      const laws = readLaws(root);
      const globalRules = readGlobalRules(root);
      const policies = readPolicies(root);

      for (const target of TARGETS) {
        const content = COMPILERS[target](manifest, laws, globalRules, policies);
        const relativePath = TARGET_PATHS[target];
        const fullPath = path.join(root, relativePath);
        fs.mkdirSync(path.dirname(fullPath), { recursive: true });
        fs.writeFileSync(fullPath, content);
      }
      printLine(`[WATCH] Initial compile complete (${TARGETS.length} targets)`);

      const timer = startWatch(root, intervalMs);

      // Keep process alive
      process.on('SIGINT', () => {
        clearInterval(timer);
        printLine('[WATCH] Stopped');
        process.exit(0);
      });
    });

  // Comandos individuais por target
  TARGETS.forEach(target => {
    cmd
      .command(target)
      .description(`Compila apenas para ${target} (${TARGET_PATHS[target]})`)
      .option('--dry-run', 'Mostra o que seria gerado sem escrever')
      .action((options: { dryRun?: boolean }) => {
        const root = process.cwd();
        const manifest = readManifest(root);
        const laws = readLaws(root);
        const globalRules = readGlobalRules(root);
        const policies = readPolicies(root);

        const rulesCount = (laws.rules?.length || 0) + globalRules.length + policies.length;
        printHeader(`Compile: ${target}`);
        printLine(`Rules: ${rulesCount}`);

        const content = COMPILERS[target](manifest, laws, globalRules, policies);
        const relativePath = TARGET_PATHS[target];
        const fullPath = path.join(root, relativePath);

        if (!options.dryRun) {
          try {
            fs.mkdirSync(path.dirname(fullPath), { recursive: true });
            fs.writeFileSync(fullPath, content);
            printResult(target, true, relativePath);
          } catch (err: unknown) {
            const msg = err instanceof Error ? err.message : String(err);
            printResult(target, false, msg);
          }
        } else {
          printLine(`[DRY-RUN] ${relativePath} (${content.length} bytes)`);
        }

        finish({
          checkpoint: `compile_${target}`,
          ok: true,
          status: 'passed',
          context_summary: `Compilado ${target} → ${relativePath}`,
          data: { target, path: relativePath, rules: rulesCount },
        });
      });
  });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printLine, printResult } from "../utils/output";
import { listFrameworks, getFramework } from '../compliance/frameworks';
import { mapRulesToFramework, generateReport } from '../compliance/mapper';

const ROOT = process.cwd();

function complianceMapAction(): void {
  const frameworks = listFrameworks();
  printLine(`Mapeando regras para ${frameworks.length} frameworks:\n`);

  for (const fwId of frameworks) {
    const mapping = mapRulesToFramework(ROOT, fwId);
    const bar = '█'.repeat(Math.round(mapping.score / 10)) + '░'.repeat(10 - Math.round(mapping.score / 10));
    printLine(`  ${mapping.frameworkName} (${fwId}): ${bar} ${mapping.score}% (${mapping.matched}/${mapping.total})`);
  }

  printLine('');
  printResult('Mapeamento concluido. Use "compliance report" para relatorio detalhado.', true);
}

function complianceCheckAction(framework: string): void {
  const mapping = mapRulesToFramework(ROOT, framework);
  const fw = getFramework(framework);

  if (!fw) {
    printResult(`Framework "${framework}" nao encontrado. Disponiveis: ${listFrameworks().join(', ')}`, false);
    return;
  }

  printLine(`=== ${mapping.frameworkName} (${framework}) ===`);
  printLine(`Conformidade: ${mapping.score}% (${mapping.matched}/${mapping.total} requisitos)\n`);

  if (mapping.matches.length > 0) {
    printLine(`Regras correspondentes (${mapping.matches.length}):`);
    for (const m of mapping.matches) {
      printLine(`  ✓ ${m.requirement}: ${m.rule.slice(0, 70)}`);
    }
    printLine('');
  }

  if (mapping.gaps.length > 0) {
    printLine(`Lacunas (${mapping.gaps.length}):`);
    for (const gap of mapping.gaps) {
      printLine(`  ✗ ${gap}`);
    }
    printLine('');
  }
}

function complianceReportAction(): void {
  const report = generateReport(ROOT);

  printLine('=== RELATORIO DE CONFORMIDADE ===\n');
  printLine(`Score geral: ${report.overallScore}%\n`);

  for (const m of report.mappings) {
    const bar = '█'.repeat(Math.round(m.score / 10)) + '░'.repeat(10 - Math.round(m.score / 10));
    printLine(`${m.frameworkName} (${m.framework}): ${bar} ${m.score}%`);
    printLine(`  Requisitos: ${m.matched}/${m.total} atendidos`);
    printLine(`  Gaps: ${m.gaps.length}`);
    printLine(`  Relatorio: .ai/reports/compliance/${m.framework}.json`);
    printLine('');
  }

  if (report.overallScore >= 80) {
    printResult(`Conformidade geral: ${report.overallScore}% — BOM`, true);
  } else if (report.overallScore >= 50) {
    printResult(`Conformidade geral: ${report.overallScore}% — MEDIO`, false);
  } else {
    printResult(`Conformidade geral: ${report.overallScore}% — BAIXO`, false);
  }
}

function complianceGapAction(framework: string): void {
  const mapping = mapRulesToFramework(ROOT, framework);
  const fw = getFramework(framework);

  if (!fw) {
    printResult(`Framework "${framework}" nao encontrado.`, false);
    return;
  }

  if (mapping.gaps.length === 0) {
    printResult(`Nenhuma lacuna para ${mapping.frameworkName}. Todos os requisitos atendidos!`, true);
    return;
  }

  printLine(`Lacunas para ${mapping.frameworkName} (${mapping.gaps.length}):\n`);
  for (const gap of mapping.gaps) {
    printLine(`  ✗ ${gap}`);
  }
  printLine('');
  printLine(`Sugestao: Use "compliance import ${framework}" para importar regras sugeridas.`);
}

function complianceBadgesAction(): void {
  const frameworks = listFrameworks();
  printLine('Badges de conformidade:\n');

  for (const fwId of frameworks) {
    const mapping = mapRulesToFramework(ROOT, fwId);
    const fw = getFramework(fwId);
    const status = mapping.score >= 80 ? 'passing' : mapping.score >= 50 ? 'partial' : 'failing';
    const color = status === 'passing' ? 'brightgreen' : status === 'partial' ? 'yellow' : 'red';
    const badgeUrl = `https://img.shields.io/badge/${encodeURIComponent(fwId)}-${mapping.score}%25-${color}`;
    const badge = `![${fwId}](${badgeUrl})`;
    printLine(`  ${fw?.name || fwId}: ${badge}`);
    printLine(`    Score: ${mapping.score}% (${mapping.matched}/${mapping.total})`);
  }
}

function complianceImportAction(framework: string): void {
  const fw = getFramework(framework);
  if (!fw) {
    printResult(`Framework "${framework}" nao encontrado.`, false);
    return;
  }

  const templateDir = path.join(ROOT, '.ai/compliance/templates');
  fs.mkdirSync(templateDir, { recursive: true });

  const content = `# Regras sugeridas para ${fw.name} (${fw.id})
# Adicione estas regras ao seu .ai/laws.yaml ou policy files

${fw.requirements.map(req => `# ${req.id}: ${req.title}
# ${req.description}
# Keywords: ${req.keywords.join(', ')}
- [${fw.id}] Implementar ${req.title.toLowerCase()}`).join('\n\n')}
`;

  const filePath = path.join(templateDir, `${fw.id}-rules.md`);
  fs.writeFileSync(filePath, content);
  printResult(`Regras sugeridas para ${fw.name} importadas para ${filePath}`, true);
  printLine(`  Adicione manualmente as regras relevantes ao seu .ai/laws.yaml`);
}

export function complianceCommand(): Command {
  const cmd = new Command('compliance')
    .description('Mapeamento regulatorio e conformidade');

  cmd
    .command('map')
    .description('Mapeia regras atuais para frameworks regulatorios')
    .action(complianceMapAction);

  cmd
    .command('check')
    .description('Verifica conformidade com framework especifico')
    .argument('<framework>', `Framework: ${listFrameworks().join(', ')}`)
    .action(complianceCheckAction);

  cmd
    .command('report')
    .description('Gera relatorio completo de conformidade')
    .action(complianceReportAction);

  cmd
    .command('gap')
    .description('Mostra requisitos nao atendidos para framework')
    .argument('<framework>', `Framework: ${listFrameworks().join(', ')}`)
    .action(complianceGapAction);

  cmd
    .command('badges')
    .description('Gera badges de conformidade')
    .action(complianceBadgesAction);

  cmd
    .command('import')
    .description('Importa regras sugeridas para framework')
    .argument('<framework>', `Framework: ${listFrameworks().join(', ')}`)
    .action(complianceImportAction);

  return cmd;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { printHeader, printLine, printResult, finish } from "../utils/output";

function getAstSignatures(dir: string): string {
  let astSlicerPath: string | null = null;
  try {
    astSlicerPath = require.resolve('@ai-devkit/core/bin/v3-engines/ast-slicer');
  } catch {
    const fallback = path.join(process.cwd(), 'packages/core/bin/v3-engines/ast-slicer.js');
    if (fs.existsSync(fallback)) astSlicerPath = fallback;
  }
  if (!astSlicerPath) return "";

  const { getSignatures } = require(astSlicerPath);
  const files: string[] = [];

  function walk(current: string) {
     if (!fs.existsSync(current)) return;
     for (const item of fs.readdirSync(current, { withFileTypes: true })) {
         const full = path.join(current, item.name);
         if (item.isDirectory() && !['node_modules', 'dist', '.git', 'legado'].includes(item.name)) {
             walk(full);
         } else if (full.endsWith('.ts') && !full.includes('.spec.')) {
             files.push(full);
         }
     }
  }

  walk(dir);
  let finalAst = "";
  for (const f of files) {
      try {
          finalAst += `\n--- Arquivo: ${path.relative(process.cwd(), f)} ---\n`;
          finalAst += getSignatures(f) + "\n";
      } catch(e) {
          // Skip file if parser fails
      }
  }
  return finalAst;
}

export function contextCommand(): Command {
  const cmd = new Command("context").description("Context Engine Real (Otimização via AST Slicing)");

  cmd.action(() => {
    console.log("\\n🧠 Context Engine AI-DevKit\\n");
    console.log("Use o subcomando 'pack' para compilar o RAG Local.\\n");
    cmd.help();
  });

  cmd.command("pack <name>")
     .description("Vetoriza fisicamente as assinaturas do projeto")
     .action((name) => {
       const root = process.cwd();
       const dir = path.join(root, ".ai", "context-packs");
       if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

       console.log(`[Context Engine] Agregando Manifest e Leis...`);
       let contextBlob = `# Context Pack: ${name}\n\n`;

       const manifestPath = path.join(root, ".ai/project-manifest.yaml");
       if (fs.existsSync(manifestPath)) {
           contextBlob += `## Governanca e Stack\n\`\`\`yaml\n${fs.readFileSync(manifestPath, 'utf8')}\n\`\`\`\n\n`;
       }

       console.log(`[Context Engine] Aplicando AST Slicing no diretório src/ (Drop de 90% dos Tokens)...`);
       const srcDir = path.join(root, 'src');
       if (fs.existsSync(srcDir)) {
          const astSignatures = getAstSignatures(srcDir);
          if (astSignatures) {
             contextBlob += `## Assinaturas do Projeto (Corpos Ocultados)\n\`\`\`typescript\n${astSignatures}\n\`\`\`\n`;
          } else {
             contextBlob += `> Nenhum código fonte TS encontrado.\n`;
          }
       } else {
          contextBlob += `> Diretório src/ ausente.\n`;
       }

       const target = path.join(dir, `${name}.md`);
       fs.writeFileSync(target, contextBlob);
       console.log(`\n✅ Otimização de Contexto Finalizada! Pack '${name}' gerado em: ${target}`);

       const tokenEst = Math.round(contextBlob.length / 4);
       console.log(`📉 Estimativa de Carga na API do LLM: ~${tokenEst} Tokens.`);
      });

  cmd
    .command('start')
    .description('Gera contexto de pre-start para a sessao da IA')
    .action(() => {
      const root = process.cwd();
      const scriptPath = path.join(root, '.ai/bin/pre-start-context.js');

      if (!fs.existsSync(scriptPath)) {
        printResult('pre-start-context', false, 'script nao encontrado em .ai/bin/pre-start-context.js');
        finish({ checkpoint: 'context_start', ok: false, status: 'failed', context_summary: 'Script pre-start-context.js nao encontrado.' });
        return;
      }

      const result = spawnSync('node', [scriptPath], { cwd: root, encoding: 'utf8', stdio: 'pipe' });
      const stdout = result.stdout?.trim() || '';
      const stderr = result.stderr?.trim() || '';

      if (!isLLMMode()) console.log(stdout);

      const ok = result.status === 0;
      finish({
        checkpoint: 'context_start',
        ok,
        status: ok ? 'passed' : 'failed',
        context_summary: ok ? 'Contexto de sessao carregado.' : `Erro: ${stderr || 'unknown'}`,
        data: { stdout, stderr },
      });
    });

  cmd
    .command('end')
    .description('Valida e documenta a sessao encerrada')
    .option('--summary <text>', 'Resumo do que foi feito na sessao')
    .option('--decisions <text>', 'Decisoes tomadas (separadas por ;)')
    .option('--next <text>', 'Proxima tarefa a ser feita')
    .action((options) => {
      const root = process.cwd();
      const scriptPath = path.join(root, '.ai/bin/post-start-validation.js');

      if (!fs.existsSync(scriptPath)) {
        printResult('post-start-validation', false, 'script nao encontrado em .ai/bin/post-start-validation.js');
        finish({ checkpoint: 'context_end', ok: false, status: 'failed', context_summary: 'Script post-start-validation.js nao encontrado.' });
        return;
      }

      const env: Record<string, string> = { ...process.env as Record<string, string> };
      if (options.summary) env.AI_SESSION_SUMMARY = options.summary;
      if (options.decisions) env.AI_SESSION_DECISIONS = options.decisions;
      if (options.next) env.AI_SESSION_NEXT_TASK = options.next;

      const result = spawnSync('node', [scriptPath], { cwd: root, encoding: 'utf8', stdio: 'pipe', env });
      const stdout = result.stdout?.trim() || '';
      const stderr = result.stderr?.trim() || '';

      if (!isLLMMode()) console.log(stdout);

      const ok = result.status === 0;
      finish({
        checkpoint: 'context_end',
        ok,
        status: ok ? 'passed' : 'failed',
        context_summary: ok ? 'Sessao validada e documentada.' : `Erro: ${stderr || 'unknown'}`,
        data: { stdout, stderr },
      });
    });

   return cmd;
}

function isLLMMode(): boolean {
  return process.env.AI_LLM_MODE === '1';
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { validateSpec, detectSpecType } from '../contracts/validator';
import { diffSpecs } from '../contracts/differ';
import { lintSpec } from '../contracts/linter';
import { generateClient, generateServer } from '../contracts/generator';
import { printHeader, printLine, printResult, finish } from "../utils/output";

export function contractCommand(): Command {
  const cmd = new Command('contract')
    .description('Validacao, diff, lint e geracao de contratos de API');

  cmd
    .command('validate')
    .description('Valida uma spec de API (openapi, asyncapi, graphql)')
    .argument('<type>', 'Tipo: openapi, asyncapi ou graphql')
    .argument('<file>', 'Caminho do arquivo de spec')
    .action((type: string, file: string) => {
      const filePath = path.resolve(file);
      if (!fs.existsSync(filePath)) {
        printResult('Erro', false, `Arquivo nao encontrado: ${filePath}`);
        finish({ checkpoint: 'contract_validate', ok: false, status: 'failed', context_summary: `Arquivo nao encontrado: ${filePath}` });
        return;
      }

      const detected = detectSpecType(filePath);
      if (type !== 'auto' && type !== detected && type !== 'graphql') {
        printResult('Aviso', false, `Tipo declarado "${type}" difere do detectado "${detected}" — usando detectado`);
      }

      printHeader(`Validando spec ${type}: ${file}`);
      const result = validateSpec(filePath);

      for (const err of result.errors) printResult('Erro', false, err);
      for (const warn of result.warnings) printResult('Aviso', false, warn);

      if (result.valid) {
        printResult('Validacao', true, `${result.specType} — ${Object.keys(result.info).length} campos analisados`);
      } else {
        printResult('Validacao', false, `${result.errors.length} erro(s), ${result.warnings.length} aviso(s)`);
      }

      finish({
        checkpoint: 'contract_validate',
        ok: result.valid,
        status: result.valid ? 'passed' : 'failed',
        context_summary: result.valid
          ? `${result.specType} valido: ${result.info.title || '(sem titulo)'} v${result.info.version || '?'}`
          : `${result.errors.length} erro(s), ${result.warnings.length} aviso(s)`,
        data: {
          specType: result.specType,
          valid: result.valid,
          errors: result.errors.length,
          warnings: result.warnings.length,
          info: result.info,
        },
      });
    });

  cmd
    .command('diff')
    .description('Compara duas specs e detecta breaking changes')
    .argument('<old-file>', 'Spec antiga')
    .argument('<new-file>', 'Spec nova')
    .action((oldFile: string, newFile: string) => {
      const oldPath = path.resolve(oldFile);
      const newPath = path.resolve(newFile);

      if (!fs.existsSync(oldPath)) { printResult('Erro', false, `Arquivo nao encontrado: ${oldPath}`); process.exit(1); }
      if (!fs.existsSync(newPath)) { printResult('Erro', false, `Arquivo nao encontrado: ${newPath}`); process.exit(1); }

      printHeader(`Diff: ${oldFile} vs ${newFile}`);
      const result = diffSpecs(oldPath, newPath);

      printLine(`Tipo: ${result.specType}`);
      printLine(`Total de mudancas: ${result.total}`);
      printLine(`Breaking: ${result.breaking.length}`);
      printLine(`Non-breaking: ${result.nonBreaking.length}`);
      printLine('');

      if (result.breaking.length > 0) {
        printLine('--- Breaking Changes ---');
        for (const b of result.breaking) printResult(`[BREAKING] ${b.field}`, false, b.change);
        printLine('');
      }

      if (result.nonBreaking.length > 0) {
        printLine('--- Non-Breaking Changes ---');
        for (const nb of result.nonBreaking) printLine(`  ${nb.field}: ${nb.change}`);
        printLine('');
      }

      const ok = result.breaking.length === 0;
      finish({
        checkpoint: 'contract_diff',
        ok,
        status: ok ? 'passed' : 'failed',
        context_summary: ok
          ? `${result.total} mudancas, nenhuma breaking`
          : `${result.breaking.length} breaking change(s) encontrada(s)`,
        data: { specType: result.specType, breaking: result.breaking.length, nonBreaking: result.nonBreaking.length, total: result.total },
      });
    });

  cmd
    .command('lint')
    .description('Analisa boas praticas de uma spec de API')
    .argument('<file>', 'Caminho do arquivo de spec')
    .action((file: string) => {
      const filePath = path.resolve(file);
      if (!fs.existsSync(filePath)) { printResult('Erro', false, `Arquivo nao encontrado: ${filePath}`); process.exit(1); }

      printHeader(`Lint: ${file}`);
      const result = lintSpec(filePath);

      printLine(`Tipo: ${result.specType}`);
      printLine(`Score: ${result.score}/100`);
      printLine('');

      for (const issue of result.issues) {
        const icon = issue.severity === 'error' ? '❌' : issue.severity === 'warning' ? '⚠️' : 'ℹ️';
        printLine(`${icon} [${issue.rule}] ${issue.path}: ${issue.message}`);
      }

      if (result.issues.length === 0) printLine('Nenhum problema encontrado!');

      finish({
        checkpoint: 'contract_lint',
        ok: result.score >= 60,
        status: result.score >= 80 ? 'passed' : result.score >= 60 ? 'warning' : 'failed',
        context_summary: `Score: ${result.score}/100 — ${result.issues.filter(i => i.severity === 'error').length} erros, ${result.issues.filter(i => i.severity === 'warning').length} warnings`,
        data: { specType: result.specType, score: result.score, issues: result.issues.length, errors: result.issues.filter(i => i.severity === 'error').length, warnings: result.issues.filter(i => i.severity === 'warning').length },
      });
    });

  cmd
    .command('generate-client')
    .description('Gera cliente TypeScript a partir de spec OpenAPI')
    .argument('<spec>', 'Caminho da spec OpenAPI')
    .option('-o, --out <dir>', 'Diretorio de saida', '.')
    .action((spec: string, options: { out: string }) => {
      const specPath = path.resolve(spec);
      if (!fs.existsSync(specPath)) { printResult('Erro', false, `Arquivo nao encontrado: ${specPath}`); process.exit(1); }

      printHeader(`Gerando cliente: ${spec}`);
      const files = generateClient(specPath, path.resolve(options.out));

      for (const f of files) {
        const outPath = path.resolve(f.path);
        fs.mkdirSync(path.dirname(outPath), { recursive: true });
        fs.writeFileSync(outPath, f.content);
        printResult('Gerado', true, f.path);
      }

      finish({
        checkpoint: 'contract_generate_client',
        ok: true,
        status: 'passed',
        context_summary: `${files.length} arquivo(s) gerado(s) em ${options.out}`,
        data: { files: files.map(f => f.path), generated: files.length },
      });
    });

  cmd
    .command('generate-server')
    .description('Gera server stub Express a partir de spec OpenAPI')
    .argument('<spec>', 'Caminho da spec OpenAPI')
    .option('-o, --out <dir>', 'Diretorio de saida', '.')
    .action((spec: string, options: { out: string }) => {
      const specPath = path.resolve(spec);
      if (!fs.existsSync(specPath)) { printResult('Erro', false, `Arquivo nao encontrado: ${specPath}`); process.exit(1); }

      printHeader(`Gerando server stub: ${spec}`);
      const files = generateServer(specPath, path.resolve(options.out));

      for (const f of files) {
        const outPath = path.resolve(f.path);
        fs.mkdirSync(path.dirname(outPath), { recursive: true });
        fs.writeFileSync(outPath, f.content);
        printResult('Gerado', true, f.path);
      }

      finish({
        checkpoint: 'contract_generate_server',
        ok: true,
        status: 'passed',
        context_summary: `${files.length} arquivo(s) gerado(s) em ${options.out}`,
        data: { files: files.map(f => f.path), generated: files.length },
      });
    });

  cmd
    .command('check-all')
    .description('Executa todas as validacoes em specs encontradas no projeto')
    .option('--dir <path>', 'Diretorio para buscar specs', '.')
    .action((options: { dir: string }) => {
      const root = path.resolve(options.dir);
      printHeader('Contract Check-All');

      const specFiles: string[] = [];
      function findSpecs(dir: string): void {
        try {
          const entries = fs.readdirSync(dir, { withFileTypes: true });
          for (const e of entries) {
            if (e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules') findSpecs(path.join(dir, e.name));
            else if (e.isFile() && /\.(yaml|yml|json|graphql|gql)$/i.test(e.name)) specFiles.push(path.join(dir, e.name));
          }
        } catch { /* skip unreadable */ }
      }
      findSpecs(root);

      const contractFiles = specFiles.filter(f => {
        try { return detectSpecType(f) !== 'unknown'; } catch { return false; }
      });

      if (contractFiles.length === 0) {
        printLine('Nenhuma spec de API encontrada no projeto.');
        finish({ checkpoint: 'contract_check_all', ok: true, status: 'passed', context_summary: 'Nenhuma spec encontrada', data: { total: 0, valid: 0, invalid: 0 } });
        return;
      }

      let valid = 0;
      let invalid = 0;
      let totalWarnings = 0;
      let totalScore = 0;

      for (const f of contractFiles) {
        const valResult = validateSpec(f);
        const lintResult = lintSpec(f);
        const relPath = path.relative(root, f);

        if (valResult.valid) {
          printResult(`${relPath}`, true, `Score: ${lintResult.score}/100`);
          valid++;
        } else {
          printResult(`${relPath}`, false, `${valResult.errors.length} erro(s)`);
          invalid++;
        }
        totalWarnings += valResult.warnings.length;
        totalScore += lintResult.score;
      }

      const avgScore = contractFiles.length > 0 ? Math.round(totalScore / contractFiles.length) : 100;

      printLine('');
      printResult('Total', true, `${contractFiles.length} spec(s) — ${valid} validas, ${invalid} invalidas, media score ${avgScore}/100`);

      finish({
        checkpoint: 'contract_check_all',
        ok: invalid === 0,
        status: invalid === 0 ? 'passed' : 'failed',
        context_summary: `${contractFiles.length} specs: ${valid} validas, ${invalid} invalidas, media ${avgScore}/100`,
        data: { total: contractFiles.length, valid, invalid, warnings: totalWarnings, averageScore: avgScore },
      });
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printHeader, printLine, printResult, finish } from "../utils/output";

export interface StackInfo {
  languages: string[];
  frameworks: string[];
  packageManager: string | null;
  ciProviders: string[];
  buildTool: string | null;
  testFramework: string | null;
}

const STACK_FILE = '.ai/stack.json';

function hasFile(root: string, file: string): boolean {
  return fs.existsSync(path.join(root, file));
}

function readFile(root: string, file: string): string {
  try {
    return fs.readFileSync(path.join(root, file), 'utf8');
  } catch {
    return '';
  }
}

export function detectStack(root?: string): StackInfo {
  const cwd = root || process.cwd();
  const info: StackInfo = {
    languages: [],
    frameworks: [],
    packageManager: null,
    ciProviders: [],
    buildTool: null,
    testFramework: null,
  };

  // Languages
  if (hasFile(cwd, 'package.json')) info.languages.push('nodejs');
  if (hasFile(cwd, 'pyproject.toml') || hasFile(cwd, 'requirements.txt')) info.languages.push('python');
  if (hasFile(cwd, 'go.mod')) info.languages.push('go');
  if (hasFile(cwd, 'Cargo.toml')) info.languages.push('rust');

  // Package managers
  if (hasFile(cwd, 'pnpm-lock.yaml')) info.packageManager = 'pnpm';
  else if (hasFile(cwd, 'yarn.lock')) info.packageManager = 'yarn';
  else if (hasFile(cwd, 'package-lock.json')) info.packageManager = 'npm';
  else if (hasFile(cwd, 'poetry.lock')) info.packageManager = 'poetry';
  else if (hasFile(cwd, 'requirements.txt')) info.packageManager = 'pip';

  // Frameworks (Node.js)
  if (hasFile(cwd, 'package.json')) {
    const pkg = readFile(cwd, 'package.json');
    try {
      const parsed = JSON.parse(pkg);
      const deps = { ...parsed.dependencies, ...parsed.devDependencies };
      if (deps['@nestjs/core']) info.frameworks.push('nestjs');
      if (deps['fastify']) info.frameworks.push('fastify');
      if (deps['express']) info.frameworks.push('express');
      if (deps['next']) info.frameworks.push('nextjs');
    } catch {
      // ignore malformed package.json
    }
  }

  // Frameworks (Python)
  const reqTxt = readFile(cwd, 'requirements.txt');
  if (/fastapi/i.test(reqTxt)) info.frameworks.push('fastapi');
  const pyproject = readFile(cwd, 'pyproject.toml');
  if (/fastapi/i.test(pyproject)) info.frameworks.push('fastapi');

  // CI providers
  if (hasFile(cwd, '.github/workflows')) info.ciProviders.push('github-actions');
  if (hasFile(cwd, '.gitlab-ci.yml')) info.ciProviders.push('gitlab-ci');

  // Build tools
  if (info.languages.includes('nodejs')) {
    if (hasFile(cwd, 'tsconfig.json')) info.buildTool = 'typescript';
    else info.buildTool = 'node';
  } else if (info.languages.includes('python')) {
    info.buildTool = 'python';
  } else if (info.languages.includes('go')) {
    info.buildTool = 'go';
  } else if (info.languages.includes('rust')) {
    info.buildTool = 'cargo';
  }

  // Test frameworks (Node.js)
  if (hasFile(cwd, 'package.json')) {
    const pkg = readFile(cwd, 'package.json');
    try {
      const parsed = JSON.parse(pkg);
      const devDeps = parsed.devDependencies || {};
      if (devDeps['jest']) info.testFramework = 'jest';
      else if (devDeps['vitest']) info.testFramework = 'vitest';
      else if (devDeps['mocha']) info.testFramework = 'mocha';
    } catch {
      // ignore
    }
  }

  return info;
}

export function saveStack(root: string, info: StackInfo): void {
  const stackPath = path.join(root, STACK_FILE);
  fs.mkdirSync(path.dirname(stackPath), { recursive: true });
  const data = {
    detectedAt: new Date().toISOString(),
    ...info,
  };
  fs.writeFileSync(stackPath, JSON.stringify(data, null, 2));
}

export function detectCommand(): Command {
  const cmd = new Command('detect')
    .description('Detecta a stack tecnologica do projeto atual');

  cmd
    .command('stack')
    .description('Detecta e exibe a stack do projeto')
    .action(() => {
      const root = process.cwd();
      const info = detectStack(root);
      saveStack(root, info);

      printHeader('Stack Detectada');
      printLine(`Linguagens: ${info.languages.join(', ') || 'nenhuma'}`);
      printLine(`Frameworks: ${info.frameworks.join(', ') || 'nenhum'}`);
      printLine(`Gerenciador de pacotes: ${info.packageManager || 'não detectado'}`);
      printLine(`Build tool: ${info.buildTool || 'não detectado'}`);
      printLine(`Test framework: ${info.testFramework || 'não detectado'}`);
      printLine(`CI providers: ${info.ciProviders.join(', ') || 'nenhum'}`);

      const ok = info.languages.length > 0;
      finish({
        checkpoint: 'detect',
        ok,
        status: ok ? 'passed' : 'failed',
        context_summary: ok
          ? `Stack detectada: ${info.languages.join(', ')}`
          : 'Nenhuma stack conhecida detectada.',
        data: info as unknown as Record<string, unknown>,
      });
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { printHeader, printLine, printResult, finish } from "../utils/output";

function checkEnv() {
    let score = 100;
    const report: string[] = [];

    // Check Node version
    const nodeVersion = process.versions.node;
    report.push(`[OK] Node.js Version: ${nodeVersion}`);

    // Check global dependencies
    try {
       execSync('git --version', { stdio: 'ignore' });
       report.push(`[OK] Git is installed`);
    } catch {
       report.push(`[ERR] Git is missing`);
       score -= 20;
    }

    // Check project setup
    const root = process.cwd();
    if (fs.existsSync(path.join(root, '.ai/project-manifest.yaml'))) {
       report.push(`[OK] AI-Devkit initialized (.ai/project-manifest.yaml exists)`);
    } else {
       report.push(`[WARN] AI-Devkit not initialized. Run 'ai-devkit init'`);
       score -= 30;
    }

    return { score, report };
}

export function doctorCommand(): Command {
  return new Command('doctor')
    .description('Diagnose AI-Devkit installation environment')
    .action(() => {
      printHeader('AI-Devkit Doctor');
      const { score, report } = checkEnv();
      report.forEach(r => printLine(r));
      const ok = score >= 90;
      finish({
        checkpoint: "doctor",
        ok,
        status: ok ? "passed" : "failed",
        context_summary: ok
          ? `Environment Health: ${score}/100`
          : `Environment Health: ${score}/100 — abaixo do mínimo recomendado (90)`,
        data: { environmentHealth: score, checks: report },
      });
    });
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";

export interface DriftFinding {
  type: "stale" | "orphan" | "reality" | "completeness";
  source?: string;
  target?: string;
  message: string;
  severity: "low" | "medium" | "high";
}

export interface DriftReport {
  timestamp: string;
  total_findings: number;
  findings: DriftFinding[];
  status: "clean" | "drift_detected";
}

const SOURCE_DIRS = [
  ".ai/policies",
  ".ai/laws.yaml",
  ".ai/governance.md",
  ".ai/security",
  ".ai/quality"
];

const TARGET_FILES = [
  "CLAUDE.md",
  ".cursorrules",
  ".cursor/rules/*.mdc",
  ".github/copilot-instructions.md",
  ".windsurf/rules/governance.md",
  ".clinerules",
  ".continuerules",
  "GEMINI.md",
  "AGENTS.md",
  ".amazonq/rules/governance.md",
  ".rules"
];

function getFileStats(filePath: string): { exists: boolean; mtime?: Date } {
  try {
    const stats = fs.statSync(filePath);
    return { exists: true, mtime: stats.mtime };
  } catch {
    return { exists: false };
  }
}

function findFilesByPattern(pattern: string): string[] {
  if (pattern.includes("*")) {
    const dir = path.dirname(pattern);
    const fullDir = path.join(process.cwd(), dir);

    if (!fs.existsSync(fullDir)) {
      return [];
    }

    const files = fs.readdirSync(fullDir);
    const ext = path.extname(pattern);
    return files
      .filter(f => f.endsWith(ext))
      .map(f => path.join(dir, f));
  }

  return [pattern];
}

function checkStaleFiles(): DriftFinding[] {
  const findings: DriftFinding[] = [];

  SOURCE_DIRS.forEach(sourcePattern => {
    const sourceFiles = findFilesByPattern(sourcePattern);

    sourceFiles.forEach(sourceFile => {
      const sourceStats = getFileStats(sourceFile);
      if (!sourceStats.exists || !sourceStats.mtime) return;
      const sourceMtime = sourceStats.mtime;

      TARGET_FILES.forEach(targetPattern => {
        const targetFiles = findFilesByPattern(targetPattern);

        targetFiles.forEach(targetFile => {
          const targetStats = getFileStats(targetFile);
          if (!targetStats.exists || !targetStats.mtime) return;

          if (sourceMtime > targetStats.mtime) {
            findings.push({
              type: "stale",
              source: sourceFile,
              target: targetFile,
              message: `Target '${targetFile}' is older than source '${sourceFile}'`,
              severity: "medium"
            });
          }
        });
      });
    });
  });

  return findings;
}

function checkOrphanFiles(): DriftFinding[] {
  const findings: DriftFinding[] = [];

  TARGET_FILES.forEach(targetPattern => {
    const targetFiles = findFilesByPattern(targetPattern);

    targetFiles.forEach(targetFile => {
      const targetStats = getFileStats(targetFile);
      if (!targetStats.exists) return;

      const hasSource = SOURCE_DIRS.some(sourcePattern => {
        const sourceFiles = findFilesByPattern(sourcePattern);
        return sourceFiles.some(sf => getFileStats(sf).exists);
      });

      if (!hasSource) {
        findings.push({
          type: "orphan",
          target: targetFile,
          message: `Target '${targetFile}' exists but no source files found`,
          severity: "low"
        });
      }
    });
  });

  return findings;
}

function checkRealityFiles(): DriftFinding[] {
  const findings: DriftFinding[] = [];

  const tools = {
    "CLAUDE.md": "Claude Code",
    ".cursorrules": "Cursor",
    ".github/copilot-instructions.md": "GitHub Copilot",
    ".windsurf/rules/governance.md": "Windsurf",
    ".clinerules": "Cline",
    ".continuerules": "Continue",
    "GEMINI.md": "Gemini",
    "AGENTS.md": "Codex/Aider",
    ".amazonq/rules/governance.md": "Amazon Q",
    ".rules": "Zed"
  };

  Object.entries(tools).forEach(([file, tool]) => {
    const stats = getFileStats(file);
    if (stats.exists) {
      const toolConfigDir = path.dirname(file);
      if (toolConfigDir && !fs.existsSync(path.join(process.cwd(), toolConfigDir))) {
        findings.push({
          type: "reality",
          target: file,
          message: `Target '${file}' references '${tool}' but config directory doesn't exist`,
          severity: "low"
        });
      }
    }
  });

  return findings;
}

function checkCompleteness(): DriftFinding[] {
  const findings: DriftFinding[] = [];

  const hasSource = SOURCE_DIRS.some(sourcePattern => {
    const sourceFiles = findFilesByPattern(sourcePattern);
    return sourceFiles.some(sf => getFileStats(sf).exists);
  });

  if (hasSource) {
    const hasAnyTarget = TARGET_FILES.some(targetPattern => {
      const targetFiles = findFilesByPattern(targetPattern);
      return targetFiles.some(tf => getFileStats(tf).exists);
    });

    if (!hasAnyTarget) {
      findings.push({
        type: "completeness",
        message: "Source files exist but no compiled targets generated",
        severity: "high"
      });
    }
  }

  return findings;
}

export function detectDrift(): DriftReport {
  const findings: DriftFinding[] = [
    ...checkStaleFiles(),
    ...checkOrphanFiles(),
    ...checkRealityFiles(),
    ...checkCompleteness()
  ];

  return {
    timestamp: new Date().toISOString(),
    total_findings: findings.length,
    findings,
    status: findings.length > 0 ? "drift_detected" : "clean"
  };
}

function saveDriftReport(report: DriftReport): void {
  const reportsDir = path.join(process.cwd(), ".ai/reports/drift");
  if (!fs.existsSync(reportsDir)) {
    fs.mkdirSync(reportsDir, { recursive: true });
  }

  const reportFile = path.join(reportsDir, "latest.json");
  fs.writeFileSync(reportFile, JSON.stringify(report, null, 2));
}

function printDriftReport(report: DriftReport): void {
  console.log("\n╔═══════════════════════════════════════════════════════════╗");
  console.log("║              DRIFT DETECTION REPORT                      ║");
  console.log("╚═══════════════════════════════════════════════════════════╝\n");

  console.log(`📅 Timestamp: ${report.timestamp}`);
  console.log(`📊 Status: ${report.status === "clean" ? "✅ Clean" : "❌ Drift Detected"}`);
  console.log(`🔍 Total findings: ${report.total_findings}\n`);

  if (report.findings.length === 0) {
    console.log("✅ No drift detected. All sources and targets are synchronized.\n");
    return;
  }

  const grouped = report.findings.reduce((acc, f) => {
    if (!acc[f.type]) acc[f.type] = [];
    acc[f.type].push(f);
    return acc;
  }, {} as Record<string, DriftFinding[]>);

  Object.entries(grouped).forEach(([type, findings]) => {
    console.log(`\n┌─────────────────────────────────────────────────────────┐`);
    console.log(`│ ${type.toUpperCase()} (${findings.length})`);
    console.log(`└─────────────────────────────────────────────────────────┘\n`);

    findings.forEach((f, index) => {
      console.log(`${index + 1}. ${f.message}`);
      if (f.source) console.log(`   Source: ${f.source}`);
      if (f.target) console.log(`   Target: ${f.target}`);
      console.log(`   Severity: ${f.severity}`);
      console.log();
    });
  });

  console.log("═".repeat(60));
  console.log(`Status: ${report.status}`);
  console.log("═".repeat(60) + "\n");
}

export function driftCommand(): Command {
  const drift = new Command("drift")
    .description("Detecta divergências entre fontes de governança e alvos compilados");

  drift
    .command("check")
    .description("Verifica drift entre fontes e alvos")
    .option("--json", "Retorna resultado em JSON")
    .option("--fix", "Recompila alvos stale automaticamente (requer compilador)")
    .action((options) => {
      const report = detectDrift();
      saveDriftReport(report);

      if (options.json) {
        console.log(JSON.stringify(report, null, 2));
      } else {
        printDriftReport(report);
      }

      if (options.fix) {
        console.log("\n🔧 Auto-fix not yet implemented. Requires multi-format compiler (Fase 2).");
        console.log("   Run 'ai-devkit compile' manually to regenerate targets.\n");
      }

      if (report.status === "drift_detected") {
        process.exit(1);
      }
    });

  drift
    .command("status")
    .description("Exibe status do último drift check")
    .action(() => {
      const reportFile = path.join(process.cwd(), ".ai/reports/drift/latest.json");

      if (!fs.existsSync(reportFile)) {
        console.log("No drift check performed yet. Run 'ai-devkit drift check' first.");
        return;
      }

      const report: DriftReport = JSON.parse(fs.readFileSync(reportFile, "utf8"));
      console.log(`\n📊 Last drift check: ${report.timestamp}`);
      console.log(`Status: ${report.status === "clean" ? "✅ Clean" : "❌ Drift Detected"}`);
      console.log(`Findings: ${report.total_findings}\n`);
    });

  return drift;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { printHeader, printLine, printResult, finish } from "../utils/output";

function getNodeVersion(): string {
  try { return process.version; } catch { return 'desconhecido'; }
}

function getPackageVersion(root: string, name: string): string {
  const pkgPath = path.join(root, 'packages', name, 'package.json');
  if (fs.existsSync(pkgPath)) {
    try { return JSON.parse(fs.readFileSync(pkgPath, 'utf-8')).version; } catch { return 'erro'; }
  }
  const rootPkg = path.join(root, 'package.json');
  if (fs.existsSync(rootPkg)) {
    try { return JSON.parse(fs.readFileSync(rootPkg, 'utf-8')).version; } catch { return 'erro'; }
  }
  return 'N/A';
}

function countPlugins(root: string): number {
  const pluginsDir = path.join(root, '.ai', 'plugins');
  if (!fs.existsSync(pluginsDir)) return 0;
  try { return fs.readdirSync(pluginsDir).filter(d => !d.startsWith('.')).length; } catch { return 0; }
}

function countRules(root: string): number {
  const rulesDir = path.join(root, '.ai', 'rules');
  if (!fs.existsSync(rulesDir)) return 0;
  try {
    return fs.readdirSync(rulesDir).filter(f => f.endsWith('.yaml') || f.endsWith('.yml') || f.endsWith('.md')).length;
  } catch { return 0; }
}

export function ecosystemCommand(): Command {
  const cmd = new Command('ecosystem')
    .description('Gerenciamento do ecossistema ai-devkit');

  cmd
    .command('status')
    .description('Exibe status do ecossistema')
    .action(() => {
      const root = process.cwd();
      printHeader('Ecosystem Status');

      const cliVersion = getPackageVersion(root, 'cli');
      const coreVersion = getPackageVersion(root, 'core');
      const nodeVersion = getNodeVersion();
      const pluginCount = countPlugins(root);
      const ruleCount = countRules(root);

      printLine(`CLI Version: ${cliVersion}`);
      printLine(`Core Version: ${coreVersion}`);
      printLine(`Node.js: ${nodeVersion}`);
      printLine(`Plugins instalados: ${pluginCount}`);
      printLine(`Rule packs: ${ruleCount}`);

      const pkgManagers = ['pnpm', 'yarn', 'npm'];
      let activePm = 'npm';
      for (const pm of pkgManagers) {
        if (pm === 'pnpm' && fs.existsSync(path.join(root, 'pnpm-lock.yaml'))) { activePm = 'pnpm'; break; }
        if (pm === 'yarn' && fs.existsSync(path.join(root, 'yarn.lock'))) { activePm = 'yarn'; break; }
      }
      printLine(`Package Manager: ${activePm}`);

      finish({
        checkpoint: 'ecosystem_status',
        ok: true,
        status: 'passed',
        context_summary: `CLI ${cliVersion}, Core ${coreVersion}, ${pluginCount} plugins, ${ruleCount} rules`,
        data: { cliVersion, coreVersion, nodeVersion, pluginCount, ruleCount, packageManager: activePm },
      });
    });

  cmd
    .command('doctor')
    .description('Diagnostico completo do ecossistema')
    .action(() => {
      const root = process.cwd();
      printHeader('Ecosystem Doctor');

      const checks: { label: string; passed: boolean; detail: string }[] = [];

      const cliPkg = path.join(root, 'packages', 'cli', 'package.json');
      const distIndex = path.join(root, 'packages', 'cli', 'dist', 'index.js');
      checks.push({
        label: 'CLI package.json',
        passed: fs.existsSync(cliPkg),
        detail: fs.existsSync(cliPkg) ? 'OK' : 'Ausente',
      });
      checks.push({
        label: 'CLI dist/index.js',
        passed: fs.existsSync(distIndex),
        detail: fs.existsSync(distIndex) ? 'OK' : 'Ausente (rode npm run build)',
      });

      const corePkg = path.join(root, 'packages', 'core', 'package.json');
      checks.push({
        label: 'Core package.json',
        passed: fs.existsSync(corePkg),
        detail: fs.existsSync(corePkg) ? 'OK' : 'Ausente',
      });

      const aiDir = path.join(root, '.ai');
      checks.push({
        label: '.ai/ directory',
        passed: fs.existsSync(aiDir),
        detail: fs.existsSync(aiDir) ? 'OK' : 'Ausente (rode ai-devkit init)',
      });

      const masterPlan = path.join(root, '.ai', 'tasks', 'master-plan.md');
      checks.push({
        label: 'Master plan',
        passed: fs.existsSync(masterPlan),
        detail: fs.existsSync(masterPlan) ? 'OK' : 'Ausente',
      });

      for (const c of checks) printResult(c.label, c.passed, c.detail);

      const allPassed = checks.every(c => c.passed);
      finish({
        checkpoint: 'ecosystem_doctor',
        ok: allPassed,
        status: allPassed ? 'passed' : 'warning',
        context_summary: `${checks.filter(c => c.passed).length}/${checks.length} checks OK`,
        data: { checks, allPassed },
      });
    });

  cmd
    .command('update')
    .description('Atualiza ai-devkit para ultima versao estavel')
    .action(() => {
      printHeader('Ecosystem Update');
      const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';
      try {
        printLine('Verificando atualizacoes...');
        execSync(`${npmBin} update 2>&1`, { cwd: process.cwd(), stdio: 'pipe', timeout: 120000 });
        printResult('Atualizacao', true, 'Dependencias atualizadas');

        try {
          const gitPull = execSync('git pull --rebase 2>&1', { cwd: process.cwd(), encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
          printLine(gitPull.split('\n')[0] || '');
        } catch { /* no git */ }

        finish({
          checkpoint: 'ecosystem_update',
          ok: true,
          status: 'passed',
          context_summary: 'Ai-devkit atualizado',
          data: { updated: true },
        });
      } catch (e: unknown) {
        const errorMsg = e instanceof Error ? e.message : String(e);
        finish({
          checkpoint: 'ecosystem_update',
          ok: false,
          status: 'failed',
          context_summary: `Falha na atualizacao: ${errorMsg}`,
          data: { error: errorMsg },
        });
      }
    });

  cmd
    .command('metrics')
    .description('Metricas de uso do ecossistema')
    .action(() => {
      const root = process.cwd();
      printHeader('Ecosystem Metrics');

      const pluginCount = countPlugins(root);
      const ruleCount = countRules(root);
      let totalDownloads = 0;

      const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';
      try {
        const view = execSync(`${npmBin} view @ai-devkit/cli downloads 2>&1`, { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
        totalDownloads = parseInt(view.trim(), 10) || 0;
      } catch { totalDownloads = 0; }

      const lastUpdated = fs.existsSync(path.join(root, 'package.json'))
        ? new Date(fs.statSync(path.join(root, 'package.json')).mtime).toISOString().split('T')[0]
        : 'N/A';

      printLine(`Plugins ativos: ${pluginCount}`);
      printLine(`Rule packs: ${ruleCount}`);
      printLine(`Downloads (npm): ${totalDownloads > 0 ? totalDownloads.toLocaleString() : 'N/A'}`);
      printLine(`Ultima atualizacao: ${lastUpdated}`);

      finish({
        checkpoint: 'ecosystem_metrics',
        ok: true,
        status: 'passed',
        context_summary: `${pluginCount} plugins, ${ruleCount} rules`,
        data: { plugins: pluginCount, rules: ruleCount, downloads: totalDownloads, lastUpdated },
      });
    });

  cmd
    .command('security-advisory')
    .description('Verifica advisories de seguranca para dependencias')
    .action(() => {
      printHeader('Security Advisory Check');
      const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';

      try {
        const audit = execSync(`${npmBin} audit --json 2>&1`, { cwd: process.cwd(), encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
        const auditData = JSON.parse(audit);
        const vulnerabilities = auditData.vulnerabilities || {};
        const totalVulns = Object.keys(vulnerabilities).length;
        const criticalVulns = Object.values(vulnerabilities).filter((v: unknown) => (v as { severity: string }).severity === 'critical').length;
        const highVulns = Object.values(vulnerabilities).filter((v: unknown) => (v as { severity: string }).severity === 'high').length;

        printLine(`Total de vulnerabilidades: ${totalVulns}`);
        printLine(`  Criticas: ${criticalVulns}`);
        printLine(`  Altas: ${highVulns}`);
        printLine(`  Moderadas: ${Object.values(vulnerabilities).filter((v: unknown) => (v as { severity: string }).severity === 'moderate').length}`);

        for (const [name, info] of Object.entries(vulnerabilities)) {
          const i = info as { severity: string; via: unknown[] };
          if (i.severity === 'critical' || i.severity === 'high') {
            printResult(name, false, `${i.severity}: ${i.via?.length || 0} caminho(s)`);
          }
        }

        finish({
          checkpoint: 'ecosystem_security_advisory',
          ok: criticalVulns === 0,
          status: criticalVulns > 0 ? 'failed' : highVulns > 0 ? 'warning' : 'passed',
          context_summary: `${totalVulns} vulnerabilidades (${criticalVulns} criticas, ${highVulns} altas)`,
          data: { total: totalVulns, critical: criticalVulns, high: highVulns },
        });
      } catch {
        printLine('Nenhuma auditoria disponivel ou npm audit falhou.');
        finish({
          checkpoint: 'ecosystem_security_advisory',
          ok: true,
          status: 'passed',
          context_summary: 'Auditoria nao disponivel',
          data: { error: 'npm audit falhou' },
        });
      }
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printHeader, printLine, printResult, finish } from "../utils/output";

const FLAGS_CONFIG_PATH = '.ai/feature-flags/flags.yaml';

interface FeatureFlag {
  name: string;
  description: string;
  status: 'active' | 'inactive' | 'rolled-out';
  type: 'boolean' | 'percentage' | 'targeting';
  percentage?: number;
  targetingRules?: string[];
  createdAt: string;
  updatedAt: string;
}

function loadFlags(root: string): FeatureFlag[] {
  const cfgPath = path.join(root, FLAGS_CONFIG_PATH);
  if (!fs.existsSync(cfgPath)) return [];
  const raw = fs.readFileSync(cfgPath, 'utf-8');
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveFlags(root: string, flags: FeatureFlag[]): void {
  const cfgPath = path.join(root, FLAGS_CONFIG_PATH);
  fs.mkdirSync(path.dirname(cfgPath), { recursive: true });
  fs.writeFileSync(cfgPath, JSON.stringify(flags, null, 2));
}

export function featureFlagCommand(): Command {
  const cmd = new Command('feature-flag')
    .description('Gerenciamento de feature flags');

  cmd
    .command('plan')
    .description('Gera blueprint de uma nova feature flag')
    .argument('<name>', 'Nome da feature flag')
    .action((name: string) => {
      const root = process.cwd();
      printHeader(`Feature Flag Plan: ${name}`);

      const flags = loadFlags(root);
      if (flags.some(f => f.name === name)) {
        printResult('Erro', false, `Feature flag "${name}" ja existe`);
        finish({ checkpoint: 'feature_flag_plan', ok: false, status: 'failed', context_summary: `Flag "${name}" ja existe` });
        return;
      }

      const newFlag: FeatureFlag = {
        name,
        description: `Feature flag para ${name}`,
        status: 'inactive',
        type: 'boolean',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      flags.push(newFlag);
      saveFlags(root, flags);

      printLine(`Blueprint gerado para "${name}":`);
      printLine(`  Tipo: ${newFlag.type}`);
      printLine(`  Status: ${newFlag.status}`);
      printLine(`  Provider: boolean toggle`);

      finish({
        checkpoint: 'feature_flag_plan',
        ok: true,
        status: 'passed',
        context_summary: `Flag "${name}" criada com tipo boolean`,
        data: { name, type: 'boolean', status: 'inactive' },
      });
    });

  cmd
    .command('list')
    .description('Lista todas as feature flags')
    .action(() => {
      const root = process.cwd();
      printHeader('Feature Flags');

      const flags = loadFlags(root);
      if (flags.length === 0) {
        printLine('Nenhuma feature flag definida.');
        finish({ checkpoint: 'feature_flag_list', ok: true, status: 'passed', context_summary: 'Nenhuma flag', data: { total: 0 } });
        return;
      }

      for (const f of flags) {
        const icon = f.status === 'active' ? '✅' : f.status === 'rolled-out' ? '📦' : '⏸️';
        printLine(`${icon} ${f.name}: ${f.status} (${f.type})`);
        if (f.description) printLine(`   ${f.description}`);
      }

      finish({
        checkpoint: 'feature_flag_list',
        ok: true,
        status: 'passed',
        context_summary: `${flags.length} flag(s) encontrada(s)`,
        data: { total: flags.length, active: flags.filter(f => f.status === 'active').length },
      });
    });

  cmd
    .command('status')
    .description('Mostra status de uma feature flag')
    .argument('<name>', 'Nome da flag')
    .action((name: string) => {
      const root = process.cwd();
      const flags = loadFlags(root);
      const flag = flags.find(f => f.name === name);

      if (!flag) {
        printResult('Erro', false, `Feature flag "${name}" nao encontrada`);
        finish({ checkpoint: 'feature_flag_status', ok: false, status: 'failed', context_summary: `Flag "${name}" nao encontrada` });
        return;
      }

      printHeader(`Feature Flag: ${flag.name}`);
      printLine(`  Descricao: ${flag.description}`);
      printLine(`  Status: ${flag.status}`);
      printLine(`  Tipo: ${flag.type}`);
      if (flag.percentage) printLine(`  Rollout: ${flag.percentage}%`);
      printLine(`  Criada: ${flag.createdAt}`);
      printLine(`  Atualizada: ${flag.updatedAt}`);

      finish({
        checkpoint: 'feature_flag_status',
        ok: true,
        status: 'passed',
        context_summary: `${flag.name}: ${flag.status}`,
        data: flag as unknown as Record<string, unknown>,
      });
    });

  return cmd;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";

function slugify(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function ensureDir(dirPath: string) {
  if (!fs.existsSync(dirPath)) fs.mkdirSync(dirPath, { recursive: true });
}

function generateArtifact(filePath: string, content: string) {
  fs.writeFileSync(filePath, content.trim() + "\n", "utf8");
  console.log(`✅ Gerado: ${filePath}`);
}

export function featureCommand(): Command {
  const cmd = new Command("feature")
    .description("Feature Intelligence Engine Real - Análise com base no estado do código");

  cmd
    .command("analyze <request>")
    .description("Análise real ligada ao Source Code")
    .option("--ui", "Gera artefatos de UX/UI")
    .action((request, options) => {
      console.log(`\n🧠 Iniciando Feature Intelligence Dinâmica...`);
      console.log(`📝 Processando: "${request}"\n`);

      const featureSlug = slugify(request.split(" ").slice(0, 3).join("-") || "nova-feature");
      const featureDir = path.join(process.cwd(), ".ai", "features", featureSlug);
      ensureDir(featureDir);

      // Tenta encontrar domínios já criados no src/ para atrelar a feature a eles
      let dominiosAtrelados = "Nenhum mapeamento de domínio existente encontrado no src/. A feature nascerá isolada.";
      const modulesDir = path.join(process.cwd(), "src/modules");
      if (fs.existsSync(modulesDir)) {
          const folders = fs.readdirSync(modulesDir).filter(f => fs.statSync(path.join(modulesDir, f)).isDirectory());
          if (folders.length > 0) {
             dominiosAtrelados = "Integrações possíveis com os seguintes domínios: " + folders.join(", ");
          }
      }

      // 1. Feature Brief (Dinâmico)
      generateArtifact(
        path.join(featureDir, "feature-brief.md"),
        `# Especificação da Feature: ${request}\n\n## Mapeamento de Domínio (AST)\n${dominiosAtrelados}\n\n## O que a IA deve preencher:\n1. Defina as Entidades envolvidas.\n2. Defina as Interfaces Externas.\n`
      );

      // 2. Acceptance Criteria
      generateArtifact(
        path.join(featureDir, "acceptance-criteria.md"),
        `# Critérios de Aceite para "${request}"\n\n(A IA deve gerar os cenários baseando-se no framework principal do sistema e no \`Contract.ts\`).\n`
      );

      // 3. Test Matrix (Dinâmico para o Test-Driven Generation)
      generateArtifact(
        path.join(featureDir, "test-matrix.md"),
        `# Matriz TDD\nA IA deve primeiramente gerar os testes abaixo e atestar a falha antes de codar a Controller:\n\n- [ ] Teste de Exceção de AppError\n- [ ] Teste de Parse do Zod\n- [ ] Teste de Sucesso e Status Code`
      );

      const requiresUI = options.ui || /tela|interface|página|dashboard|view|frontend/i.test(request);
      if (requiresUI) {
        console.log(`✨ Intenção de UI detectada.`);
        generateArtifact(path.join(featureDir, "ui-checklist.md"), `# UI/UX Checklist (A ser resolvido pela IA)\n- [ ] Validar acessibilidade\n- [ ] Aplicar design system`);
      }

      console.log(`\n🚀 Análise real concluída.`);
    });

  return cmd;
}

