import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';

function getGitHookDir(projectRoot: string): string {
  try {
    const gitDir = execSync('git rev-parse --git-common-dir', {
      cwd: projectRoot,
      encoding: 'utf8',
    }).trim();
    return path.resolve(projectRoot, gitDir, 'hooks');
  } catch {
    return path.join(projectRoot, '.git', 'hooks');
  }
}

function hookContent(): string {
  return `#!/bin/sh

# AI-Devkit pre-commit hook
# Instalado por: ai-devkit hook install

if [ -n "$SKIP_AI_VERIFY" ]; then
  echo "[ai-devkit] SKIP_AI_VERIFY detectado. Pulando verificacao."
  exit 0
fi

echo "[ai-devkit] Executando quality gates antes do commit..."

if command -v ai-devkit > /dev/null 2>&1; then
  ai-devkit verify
  RESULT=$?
else
  echo "[ai-devkit] ai-devkit nao encontrado no PATH. Tentando npm run..."
  if [ -f "package.json" ]; then
    npm run ai:quality:gate
    RESULT=$?
  else
    echo "[ai-devkit] AVISO: ai-devkit nao disponivel. Pulando verificacao."
    exit 0
  fi
fi

if [ $RESULT -ne 0 ]; then
  echo ""
  echo "========================================"
  echo "  QUALITY GATE FALHOU!"
  echo "  Corrija os problemas acima ou use:"
  echo "    SKIP_AI_VERIFY=1 git commit"
  echo "========================================"
  exit 1
fi

echo "[ai-devkit] Quality gates OK."
exit 0
`;
}

export function hookCommand(): Command {
  const cmd = new Command('hook')
    .description('Gerencia hooks git do AI-Devkit');

  cmd
    .command('install')
    .description('Instala pre-commit hook que executa ai-devkit verify')
    .action(() => {
      const root = process.cwd();
      const hooksDir = getGitHookDir(root);
      const hookPath = path.join(hooksDir, 'pre-commit');

      if (!fs.existsSync(hooksDir)) {
        fs.mkdirSync(hooksDir, { recursive: true });
      }

      if (fs.existsSync(hookPath)) {
        console.error(`[ai-devkit] AVISO: ${hookPath} ja existe. Use "ai-devkit hook uninstall" primeiro.`);
        process.exitCode = 1;
        return;
      }

      fs.writeFileSync(hookPath, hookContent(), { mode: 0o755 });
      console.log(`[ai-devkit] Pre-commit hook instalado em: ${hookPath}`);
      console.log('[ai-devkit] Hook executara "ai-devkit verify" antes de cada commit.');
      console.log('[ai-devkit] Para pular: SKIP_AI_VERIFY=1 git commit');
    });

  cmd
    .command('uninstall')
    .description('Remove o pre-commit hook do AI-Devkit')
    .action(() => {
      const root = process.cwd();
      const hooksDir = getGitHookDir(root);
      const hookPath = path.join(hooksDir, 'pre-commit');

      if (!fs.existsSync(hookPath)) {
        console.log('[ai-devkit] Nenhum pre-commit hook encontrado.');
        return;
      }

      const content = fs.readFileSync(hookPath, 'utf8');
      if (!content.includes('AI-Devkit pre-commit hook')) {
        console.error('[ai-devkit] AVISO: O hook existente nao foi instalado pelo ai-devkit. Remocao manual necessaria.');
        process.exitCode = 1;
        return;
      }

      fs.unlinkSync(hookPath);
      console.log(`[ai-devkit] Pre-commit hook removido: ${hookPath}`);
    });

  return cmd;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import { findTemplateAiDir } from "../utils/template";
import { copyTemplateDirectory, CopyMode, CopyResult } from "../utils/copy";
import { upsertPackageScripts } from "../utils/package-json";
import { generateSetupReport } from "../utils/report";
import { checkPrerequisites } from "../utils/prerequisites";
import { detectStack } from "./detect";
import { runWizard } from "./wizard";

const ALLOWED_FLAVORS = ["nestjs", "express", "fastify", "fastapi", "go"] as const;
type Flavor = typeof ALLOWED_FLAVORS[number];
const ALLOWED_FLAVORS_SET: Set<string> = new Set(ALLOWED_FLAVORS);

const TEMPLATES = ["nodejs-api", "nextjs-app", "python-api"] as const;
type ProjectTemplate = typeof TEMPLATES[number];
const TEMPLATES_SET: Set<string> = new Set(TEMPLATES);

const INSTALL_MODES = ["minimal", "standard", "full"] as const;
type InstallMode = typeof INSTALL_MODES[number];

// Define quais diretórios/arquivos copiar em cada modo
const MODE_FILTERS: Record<InstallMode, { include: string[]; exclude: string[] }> = {
  minimal: {
    include: [
      "laws.yaml",
      "project-manifest.yaml",
      "context/ai-handoff.md",
      "policies/command-policy.md",
      "policies/ai-generated-code-policy.md",
      "bin/verify.js",
      "bin/quality-agent.js"
    ],
    exclude: []
  },
  standard: {
    include: [],
    exclude: [
      "generators",
      "prompts",
      "frameworks",
      "features",
      "deployment"
    ]
  },
  full: {
    include: [],
    exclude: []
  }
};

function findProjectTemplateDir(templateName: string): string {
  const candidates = [
    path.resolve(__dirname, `../../templates/project-templates/${templateName}`),
    path.resolve(__dirname, `../templates/project-templates/${templateName}`),
    path.resolve(process.cwd(), `packages/cli/templates/project-templates/${templateName}`),
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
      return candidate;
    }
  }
  throw new Error(`Template "${templateName}" not found. Checked: ${candidates.join(", ")}`);
}

function scaffoldFromTemplate(templateDir: string, targetDir: string, projectName: string, mode: CopyMode): CopyResult {
  const result: CopyResult = { copied: [], skipped: [], overwritten: [], backedUp: [], errors: [] };

  function copyRecursive(src: string, dest: string) {
    if (!fs.existsSync(src)) return;
    const stats = fs.statSync(src);
    if (stats.isDirectory()) {
      if (mode !== "dry-run" && !fs.existsSync(dest)) {
        fs.mkdirSync(dest, { recursive: true });
      }
      for (const file of fs.readdirSync(src)) {
        copyRecursive(path.join(src, file), path.join(dest, file));
      }
    } else {
      let content = fs.readFileSync(src, 'utf8');
      if (src.endsWith('package.json') || src.endsWith('pyproject.toml')) {
        content = content.replace(/placeholder/g, projectName);
      }

      if (fs.existsSync(dest)) {
        if (mode === "force") {
          fs.writeFileSync(dest, content);
          result.overwritten.push(dest);
        } else {
          result.skipped.push(dest);
        }
      } else {
        if (mode !== "dry-run") {
          fs.mkdirSync(path.dirname(dest), { recursive: true });
          fs.writeFileSync(dest, content);
        }
        result.copied.push(dest);
      }
    }
  }

  try {
    copyRecursive(templateDir, targetDir);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    result.errors.push(message);
  }

  return result;
}

function validateFlavor(flavor: string): asserts flavor is Flavor {
  if (!ALLOWED_FLAVORS_SET.has(flavor)) {
    throw new Error(`Invalid flavor "${flavor}". Allowed flavors: ${ALLOWED_FLAVORS.join(", ")}`);
  }
}

function autoDetectFlavor(targetDir: string): string {
  const stack = detectStack(targetDir);
  if (stack.frameworks.includes('nestjs')) return 'nestjs';
  if (stack.frameworks.includes('fastify')) return 'fastify';
  if (stack.frameworks.includes('express')) return 'express';
  if (stack.frameworks.includes('fastapi')) return 'fastapi';
  if (stack.languages.includes('go')) return 'go';
  return 'nestjs';
}

function shouldCopyFile(relativePath: string, mode: InstallMode): boolean {
  const filter = MODE_FILTERS[mode];

  // Normalizar caminho (remover trailing slash para diretórios)
  const normalizedPath = relativePath.replace(/\/$/, '');
  const isDirectory = relativePath.endsWith('/');

  // Se há include list (minimal)
  if (filter.include.length > 0) {
    // Para diretórios, sempre permitir travessia (filtro será aplicado nos arquivos)
    if (isDirectory) {
      return true;
    }

    // Para arquivos, verificar se está na lista de include
    return filter.include.some(pattern => {
      // Match exato
      if (normalizedPath === pattern) return true;
      return false;
    });
  }

  // Se há exclude list (standard/full)
  if (filter.exclude.length > 0) {
    return !filter.exclude.some(pattern => {
      // Match exato
      if (normalizedPath === pattern) return true;
      // Match de prefixo (arquivo dentro de diretório excluído)
      if (normalizedPath.startsWith(pattern + '/')) return true;
      return false;
    });
  }

  // full: copia tudo
  return true;
}

export function initCommand(): Command {
  return new Command("init")
  .description("Initialize a new AI-Devkit project")
  .argument("[project-name]", "Name of the new project directory", ".")
  .option("--flavor <flavor>", "Set the framework flavor (nestjs, express, fastify, fastapi, go)")
  .option("--template <name>", `Project template to scaffold (${TEMPLATES.join(", ")})`)
  .option("--wizard", "Run interactive setup wizard")
  .option("--force", "Overwrite existing AI-DevKit managed files after creating backups")
  .option("--dry-run", "Show what would be changed without writing files")
  .option("--yes", "Skip prompts")
  .option("--minimal", "Install only essential governance files (laws, manifest, handoff, policies)")
  .option("--standard", "Install standard governance structure (default, excludes generators/prompts)")
  .option("--full", "Install complete governance structure including all generators and prompts")
  .action(async (projectName, options) => {
    try {
      const targetDir = path.resolve(process.cwd(), projectName);

      if (options.wizard) {
        const isPiped = !process.stdin.isTTY;
        if (isPiped) {
          console.log('[ai-devkit] Modo wizard requer terminal interativo. Use "ai-devkit init" sem --wizard.');
          process.exit(1);
          return;
        }
        const answers = await runWizard(targetDir);
        console.log(`\n🚀 Initializing AI-Devkit in: ${targetDir}`);
        console.log(`📦 Flavor: ${answers.framework} (via wizard)`);
        options.flavor = answers.framework;
      }

      checkPrerequisites(targetDir);

      // Determinar modo de instalação
      let installMode: InstallMode = "standard";
      if (options.minimal) installMode = "minimal";
      else if (options.full) installMode = "full";
      // padrão é standard se nenhuma flag for especificada

      const flavor = options.flavor || autoDetectFlavor(targetDir);
      if (options.flavor) validateFlavor(flavor);
      const mode: CopyMode = options.dryRun ? "dry-run" : options.force ? "force" : "safe";

      console.log(`\n🚀 Initializing AI-Devkit in: ${targetDir}`);
      if (options.flavor) console.log(`📦 Flavor: ${flavor}`);
      if (options.template) console.log(`📦 Template: ${options.template}`);
      console.log(`⚙️  Mode: ${mode}`);
      console.log(`📋 Install mode: ${installMode}\n`);

      const sourceAiDir = findTemplateAiDir();
      const aiDir = path.join(targetDir, ".ai");

      if (mode !== "dry-run" && !fs.existsSync(targetDir)) {
        fs.mkdirSync(targetDir, { recursive: true });
      }

      // Scaffold project template if specified
      if (options.template) {
        if (!TEMPLATES_SET.has(options.template)) {
          throw new Error(`Invalid template "${options.template}". Allowed templates: ${TEMPLATES.join(", ")}`);
        }
        const projectNameSafe = path.basename(targetDir);
        console.log(`📂 Scaffolding template: ${options.template}`);
        const templateDir = findProjectTemplateDir(options.template);
        const scaffoldResult = scaffoldFromTemplate(templateDir, targetDir, projectNameSafe, mode);
        console.log(`   Created: ${scaffoldResult.copied.length} files`);
        if (scaffoldResult.skipped.length > 0) console.log(`   Skipped: ${scaffoldResult.skipped.length} files (use --force to overwrite)`);
        if (scaffoldResult.errors.length > 0) console.error(`   Errors: ${scaffoldResult.errors.join(", ")}`);
      }

      console.log("📡 Cloning AI-Devkit governance matrix...");
      const copyResult = copyTemplateDirectory(sourceAiDir, aiDir, mode, (relativePath) => shouldCopyFile(relativePath, installMode));

      const manifestPath = path.join(aiDir, "project-manifest.yaml");
      if (mode !== "dry-run" && !fs.existsSync(manifestPath)) {
        const manifestContent = `project:\n  name: "${path.basename(targetDir)}"\n  version: "0.1.0"\n  status: "development"\nstack:\n  framework: "${options.flavor || options.template || 'unknown'}"\narchitecture:\n  pattern: "clean-architecture"\n  style: "modular-monolith"`;
        fs.writeFileSync(manifestPath, manifestContent);
      }

      const handoffPath = path.join(aiDir, "context", "ai-handoff.md");
      if (mode !== "dry-run" && !fs.existsSync(handoffPath)) {
        fs.writeFileSync(handoffPath, `# Handoff\nProject initialized with AI-Devkit.\nStack: ${options.flavor || options.template || 'unknown'}\n`);
      }

      const pkgJsonPath = path.join(targetDir, "package.json");
      const scriptResult = upsertPackageScripts(pkgJsonPath, !!options.force, !!options.dryRun);

      generateSetupReport(targetDir, options, copyResult, scriptResult, sourceAiDir || "unknown");

      if (options.dryRun) {
        console.log("\n[DRY-RUN] Planned actions\n");
        console.log("Files to create:");
        copyResult.copied.forEach((f: string) => console.log(`- ${path.relative(process.cwd(), f)}`));
        console.log("\nFiles to skip:");
        copyResult.skipped.forEach((f: string) => console.log(`- ${path.relative(process.cwd(), f)}`));
        console.log("\nFiles that would be overwritten with --force:");
        copyResult.overwritten.forEach((f: string) => console.log(`- ${path.relative(process.cwd(), f)}`));
        console.log("\nPackage scripts to add:");
        scriptResult.added.forEach((s: string) => console.log(`- ${s}`));
        console.log("\nPackage scripts to preserve:");
        scriptResult.preserved.forEach((s: string) => console.log(`- ${s}`));
        console.log("\nBackups that would be created with --force:");
        if (copyResult.overwritten.length > 0) {
            console.log(`- .ai/backups/setup/<timestamp>/`);
        } else {
            console.log(`None`);
        }
        return;
      }

      console.log("\n✅ AI-Devkit successfully installed.");
      console.log(`\nNext steps:`);
      if (projectName !== ".") {
        console.log(`  cd ${projectName}`);
      }
      console.log(`  npm run ai:doctor\n  npm run ai:verify\n`);

    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`\n❌ Error: ${message}`);
      process.exit(1);
    }
  });
}

import { Command } from 'commander';
import { getCuratedEntries, searchEntries, getEntry, exportEntries } from '../local-ai/knowledge-base';

export function knowledgeCommand(): Command {
  const cmd = new Command('knowledge')
    .description('Knowledge base of reference architectures, patterns, and best practices');

  cmd.command('query <topic>')
    .description('Search knowledge base by topic')
    .action((topic: string) => {
      const results = searchEntries(topic);
      if (results.length === 0) {
        console.log(`Nenhum resultado para "${topic}".`);
        return;
      }

      console.log(`\n=== Knowledge Base: "${topic}" (${results.length} resultados) ===\n`);
      for (const entry of results) {
        console.log(`  [${entry.category}] ${entry.id}`);
        console.log(`  Title: ${entry.title}`);
        console.log(`  Tags: ${entry.tags.join(', ')}`);
        console.log(`  ${entry.summary.slice(0, 200)}`);
        console.log('');
      }
    });

  cmd.command('show <id>')
    .description('Show full knowledge entry')
    .action((id: string) => {
      const entry = getEntry(id);
      if (!entry) {
        console.log(`Entrada "${id}" nao encontrada.`);
        return;
      }

      console.log(`\n=== ${entry.title} ===`);
      console.log(`Category: ${entry.category}`);
      console.log(`Tags: ${entry.tags.join(', ')}`);
      console.log(`\nSummary: ${entry.summary}`);
      console.log(`\nContent:\n${entry.content}`);
      if (entry.principles && entry.principles.length > 0) {
        console.log(`\nPrinciples:`);
        entry.principles.forEach(p => console.log(`  - ${p}`));
      }
      if (entry.when_to_use && entry.when_to_use.length > 0) {
        console.log(`\nWhen to use:`);
        entry.when_to_use.forEach(w => console.log(`  - ${w}`));
      }
      if (entry.when_not_to_use && entry.when_not_to_use.length > 0) {
        console.log(`\nWhen NOT to use:`);
        entry.when_not_to_use.forEach(w => console.log(`  - ${w}`));
      }
      if (entry.references && entry.references.length > 0) {
        console.log(`\nReferences:`);
        entry.references.forEach(r => console.log(`  - ${r}`));
      }
    });

  cmd.command('list')
    .description('List all available knowledge entries')
    .option('--category <category>', 'Filter by category')
    .action((opts: Record<string, unknown>) => {
      let entries = getCuratedEntries();
      const category = opts.category as string | undefined;
      if (category) entries = entries.filter(e => e.category === category);

      const categories = [...new Set(entries.map(e => e.category))];
      console.log(`\n=== Knowledge Base (${entries.length} entradas, ${categories.length} categorias) ===\n`);

      for (const cat of categories) {
        const catEntries = entries.filter(e => e.category === cat);
        console.log(`\n  [${cat.toUpperCase()}] (${catEntries.length})`);
        for (const e of catEntries) {
          console.log(`    ${e.id} — ${e.title.slice(0, 60)}`);
        }
      }
    });

  cmd.command('export')
    .description('Export all curated entries as YAML files to .ai/knowledge/entries/')
    .action(() => {
      const cwd = process.cwd();
      exportEntries(cwd);
      console.log(`Entradas exportadas para .ai/knowledge/entries/`);
    });

  cmd.command('stats')
    .description('Show knowledge base statistics')
    .action(() => {
      const entries = getCuratedEntries();
      const categories = [...new Set(entries.map(e => e.category))];
      const totalTags = [...new Set(entries.flatMap(e => e.tags))];

      console.log(`\n=== Knowledge Base Stats ===`);
      console.log(`Total entries: ${entries.length}`);
      console.log(`Categories: ${categories.length}`);
      console.log(`Unique tags: ${totalTags.length}`);
      console.log(`\nBy category:`);
      for (const cat of categories) {
        console.log(`  ${cat}: ${entries.filter(e => e.category === cat).length}`);
      }
    });

  return cmd;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";

export interface Learning {
  id: string;
  title: string;
  description: string;
  category: "pattern" | "pitfall" | "decision" | "preference" | "convention";
  tags: string[];
  context: string;
  session_source: string;
  timestamp: string;
  confidence: number;
}

export interface KnowledgeBase {
  version: string;
  last_updated: string;
  learnings: Learning[];
}

const MEMORY_DIR = ".ai/memory";
const KNOWLEDGE_BASE_FILE = "knowledge-base.json";

function getKnowledgeBasePath(): string {
  return path.join(process.cwd(), MEMORY_DIR, KNOWLEDGE_BASE_FILE);
}

function ensureMemoryDir(): void {
  const dir = path.join(process.cwd(), MEMORY_DIR);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function loadKnowledgeBase(): KnowledgeBase {
  const kbPath = getKnowledgeBasePath();
  if (!fs.existsSync(kbPath)) {
    return {
      version: "1.0.0",
      last_updated: new Date().toISOString(),
      learnings: []
    };
  }

  try {
    return JSON.parse(fs.readFileSync(kbPath, "utf8"));
  } catch {
    return {
      version: "1.0.0",
      last_updated: new Date().toISOString(),
      learnings: []
    };
  }
}

function saveKnowledgeBase(kb: KnowledgeBase): void {
  ensureMemoryDir();
  kb.last_updated = new Date().toISOString();
  fs.writeFileSync(getKnowledgeBasePath(), JSON.stringify(kb, null, 2));
}

function generateId(): string {
  return `learn_${Date.now()}_${Math.random().toString(36).substring(7)}`;
}

export function addLearning(learning: Omit<Learning, "id" | "timestamp">): Learning {
  const kb = loadKnowledgeBase();
  const newLearning: Learning = {
    ...learning,
    id: generateId(),
    timestamp: new Date().toISOString()
  };
  kb.learnings.push(newLearning);
  saveKnowledgeBase(kb);
  return newLearning;
}

export function searchLearnings(query?: string, category?: string): Learning[] {
  const kb = loadKnowledgeBase();
  let results = kb.learnings;

  if (query) {
    const lowerQuery = query.toLowerCase();
    results = results.filter(
      l =>
        l.title.toLowerCase().includes(lowerQuery) ||
        l.description.toLowerCase().includes(lowerQuery) ||
        l.tags.some(t => t.toLowerCase().includes(lowerQuery))
    );
  }

  if (category) {
    results = results.filter(l => l.category === category);
  }

  return results;
}

export function getStats(): {
  total: number;
  byCategory: Record<string, number>;
  byTag: Record<string, number>;
  oldestLearning: string | null;
  newestLearning: string | null;
} {
  const kb = loadKnowledgeBase();

  const byCategory: Record<string, number> = {};
  const byTag: Record<string, number> = {};

  kb.learnings.forEach(l => {
    byCategory[l.category] = (byCategory[l.category] || 0) + 1;
    l.tags.forEach(tag => {
      byTag[tag] = (byTag[tag] || 0) + 1;
    });
  });

  const timestamps = kb.learnings.map(l => l.timestamp).sort();

  return {
    total: kb.learnings.length,
    byCategory,
    byTag,
    oldestLearning: timestamps[0] || null,
    newestLearning: timestamps[timestamps.length - 1] || null
  };
}

export function pruneLearnings(olderThanDays: number): number {
  const kb = loadKnowledgeBase();
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - olderThanDays);

  const originalCount = kb.learnings.length;
  kb.learnings = kb.learnings.filter(l => new Date(l.timestamp) >= cutoffDate);
  saveKnowledgeBase(kb);

  return originalCount - kb.learnings.length;
}

export function exportKnowledgeBase(): KnowledgeBase {
  return loadKnowledgeBase();
}

export function loadRelevantLearnings(taskDescription?: string): Learning[] {
  const kb = loadKnowledgeBase();

  if (!taskDescription) {
    return kb.learnings.slice(-10);
  }

  const keywords = taskDescription.toLowerCase().split(/\s+/);
  const scored = kb.learnings.map(l => {
    let score = 0;
    const text = `${l.title} ${l.description} ${l.tags.join(" ")}`.toLowerCase();

    keywords.forEach(keyword => {
      if (text.includes(keyword)) {
        score += 1;
      }
    });

    score *= l.confidence;

    return { learning: l, score };
  });

  return scored
    .filter(s => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 10)
    .map(s => s.learning);
}

