interface CliResult { stdout: string; stderr: string; exitCode: number; }

function runCli(args: string, env?: Record<string, string>): CliResult {
  const root = process.cwd();
  const result = spawnSync('node', [
    require.resolve('../index.js'), ...args.split(' '),
  ], { cwd: root, encoding: 'utf8', env: { ...process.env, ...env } });
  const stdout = typeof result.stdout === 'string' ? result.stdout.trim() : '';
  const stderr = typeof result.stderr === 'string' ? result.stderr.trim() : '';
  return {
    stdout,
    stderr,
    exitCode: result.status ?? 1,
  };
}

function handleRequest(req: JsonRpcRequest): JsonRpcResponse {
  const id = req.id ?? null;

  if (req.method === 'initialize') {
    return {
      jsonrpc: '2.0',
      id,
      result: {
        protocolVersion: '2024-11-05',
        capabilities: { tools: {} },
        serverInfo: { name: 'ai-devkit-mcp', version: '1.0.0' },
      },
    };
  }

  if (req.method === 'tools/list') {
    return { jsonrpc: '2.0', id, result: { tools: TOOLS } };
  }

  if (req.method === 'tools/call') {
    const toolName = req.params?.name as string;
    const args = req.params?.arguments as Record<string, string> || {};

    const tool = TOOLS.find(t => t.name === toolName);
    if (!tool) {
      return {
        jsonrpc: '2.0',
        id,
        error: { code: -32601, message: `Tool not found: ${toolName}` },
      };
    }

    let cliArgs = '';
    let envVars: Record<string, string> = {};
    switch (toolName) {
      case 'mcp_status': cliArgs = 'status'; envVars = { AI_LLM_MODE: '1' }; break;
      case 'mcp_verify': cliArgs = 'verify'; break;
      case 'mcp_doctor': cliArgs = 'doctor'; break;
      case 'mcp_detect': cliArgs = 'detect stack'; break;
      case 'mcp_mode_get': cliArgs = 'mode current'; break;
      case 'mcp_mode_set': cliArgs = `mode set ${args.mode}`; break;
      case 'mcp_hook_install': cliArgs = 'hook install'; break;
      case 'mcp_hook_uninstall': cliArgs = 'hook uninstall'; break;
      case 'mcp_adapter_list': cliArgs = 'adapter list'; break;
      case 'mcp_retrospective': cliArgs = `retrospective generate${args.since ? ` --since ${args.since}` : ''}`; break;
      case 'mcp_ci_generate': cliArgs = `ci generate${args.force ? ' --force' : ''}`; break;
      case 'mcp_compile': cliArgs = `compile ${(args.target as string) || 'all'}`; break;
      case 'mcp_context_start': cliArgs = 'context start'; break;
      case 'mcp_context_end': {
        const summary = args.summary ? ` --summary "${args.summary}"` : '';
        const decisions = args.decisions ? ` --decisions "${args.decisions}"` : '';
        const next = args.next ? ` --next "${args.next}"` : '';
        cliArgs = `context end${summary}${decisions}${next}`;
        break;
      }
    }

    const out = runCli(cliArgs, envVars);

    const isError = out.exitCode !== 0 || out.stderr.length > 0;
    return {
      jsonrpc: '2.0',
      id,
      result: {
        content: [{
          type: 'text',
          text: isError ? `Error: ${out.stderr || out.stdout}` : out.stdout,
        }],
        isError,
      },
    };
  }

  if (req.method === 'notifications/initialized') {
    return { jsonrpc: '2.0', id: null, result: null };
  }

  return {
    jsonrpc: '2.0',
    id,
    error: { code: -32601, message: `Method not found: ${req.method}` },
  };
}

function startMcpServer(): void {
  const root = process.cwd();
  let buffer = '';

  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk: string) => {
    buffer += chunk;
    const lines = buffer.split('\n');
    buffer = lines.pop() || '';

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const req: JsonRpcRequest = JSON.parse(trimmed);
        const res = handleRequest(req);
        if (res.id !== null || res.error) {
          process.stdout.write(JSON.stringify(res) + '\n');
        }
      } catch {
        process.stderr.write(`{"jsonrpc":"2.0","id":null,"error":{"code":-32700,"message":"Parse error"}}\n`);
      }
    }
  });

  process.stdin.on('end', () => process.exit(0));
}

export function mcpCommand(): Command {
  return new Command('mcp')
    .description('Inicia servidor MCP (Model Context Protocol) via stdio')
    .action(() => {
      startMcpServer();
    });
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printLine, printResult, finish } from "../utils/output";

const VALID_MODES = ['development', 'security', 'performance', 'migration', 'debugging', 'documentation'] as const;
export type SessionMode = typeof VALID_MODES[number];

const MODE_FILE = '.ai/session-mode.json';

interface ModeConfig {
  mode: SessionMode;
  updatedAt: string;
}

const DEFAULT_MODE: ModeConfig = {
  mode: 'development',
  updatedAt: new Date().toISOString(),
};

export function getMode(root?: string): ModeConfig {
  const base = root || process.cwd();
  const modePath = path.join(base, MODE_FILE);
  if (!fs.existsSync(modePath)) return DEFAULT_MODE;
  try {
    const data = JSON.parse(fs.readFileSync(modePath, 'utf8')) as ModeConfig;
    if (VALID_MODES.includes(data.mode)) return data;
    return DEFAULT_MODE;
  } catch {
    return DEFAULT_MODE;
  }
}

export function modeCommand(): Command {
  const cmd = new Command('mode')
    .description('Gerencia modos de sessao da IA');

  cmd
    .command('set')
    .description('Define o modo de sessao')
    .argument('<mode>', `Modo: ${VALID_MODES.join(', ')}`)
    .action((mode: string) => {
      if (!VALID_MODES.includes(mode as SessionMode)) {
        printResult(`Modo invalido: "${mode}". Validos: ${VALID_MODES.join(', ')}`, false);
        process.exitCode = 1;
        return;
      }
      const root = process.cwd();
      const modePath = path.join(root, MODE_FILE);
      const config: ModeConfig = { mode: mode as SessionMode, updatedAt: new Date().toISOString() };
      fs.mkdirSync(path.dirname(modePath), { recursive: true });
      fs.writeFileSync(modePath, JSON.stringify(config, null, 2));
      printResult(`Modo alterado para: ${mode}`, true);
    });

  cmd
    .command('current')
    .description('Exibe o modo de sessao atual')
    .action(() => {
      const { mode, updatedAt } = getMode();
      const descriptions: Record<SessionMode, string> = {
        development: 'Padrao — foco em implementacao',
        security: 'Revisor rigoroso, bloqueia vulnerabilidades',
        performance: 'Prioriza otimizacoes',
        migration: 'Foco em refatoracao, tolerancia zero para dead code',
        debugging: 'Permite logs extensivos, desativa lint',
        documentation: 'Prioriza geracao de docs, nao altera codigo',
      };
      printLine(`Modo atual: ${mode}`);
      printLine(`Descricao: ${descriptions[mode]}`);
      printLine(`Atualizado em: ${updatedAt}`);
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printHeader, printLine, printResult, finish } from "../utils/output";

// ============================================================
// TASK-GAP-11: Observability & Tracing de Chamadas de IA
// ============================================================

interface TraceEntry {
  timestamp: string;
  model: string;
  provider: string;
  latency_ms: number;
  tokens_in: number;
  tokens_out: number;
  cost_usd: number;
  command: string;
  status: 'success' | 'error' | 'timeout';
  error?: string;
}

const TRACES_DIR = '.ai/reports/observability';
const TRACES_FILE = 'traces.jsonl';
const METRICS_FILE = 'metrics.json';

function getTracesPath(root: string): string {
  return path.join(root, TRACES_DIR, TRACES_FILE);
}

function getMetricsPath(root: string): string {
  return path.join(root, TRACES_DIR, METRICS_FILE);
}

function ensureDir(root: string): void {
  fs.mkdirSync(path.join(root, TRACES_DIR), { recursive: true });
}

function readTraces(root: string): TraceEntry[] {
  const tracesPath = getTracesPath(root);
  if (!fs.existsSync(tracesPath)) return [];
  return fs.readFileSync(tracesPath, 'utf8')
    .split('\n')
    .filter(l => l.trim())
    .map(l => {
      try { return JSON.parse(l) as TraceEntry; }
      catch { return null; }
    })
    .filter((t): t is TraceEntry => t !== null);
}

function computeMetrics(traces: TraceEntry[]) {
  if (traces.length === 0) {
    return {
      total_calls: 0,
      avg_latency_ms: 0,
      p95_latency_ms: 0,
      total_tokens: 0,
      total_cost_usd: 0,
      success_rate: 0,
      by_model: {} as Record<string, { calls: number; avg_latency: number; cost: number }>,
      by_provider: {} as Record<string, { calls: number; avg_latency: number; cost: number }>,
    };
  }

  const latencies = traces.map(t => t.latency_ms).sort((a, b) => a - b);
  const p95Index = Math.ceil(latencies.length * 0.95) - 1;
  const successCount = traces.filter(t => t.status === 'success').length;

  const byModel: Record<string, { calls: number; totalLatency: number; totalCost: number }> = {};
  const byProvider: Record<string, { calls: number; totalLatency: number; totalCost: number }> = {};

  for (const t of traces) {
    if (!byModel[t.model]) byModel[t.model] = { calls: 0, totalLatency: 0, totalCost: 0 };
    byModel[t.model].calls++;
    byModel[t.model].totalLatency += t.latency_ms;
    byModel[t.model].totalCost += t.cost_usd;

    if (!byProvider[t.provider]) byProvider[t.provider] = { calls: 0, totalLatency: 0, totalCost: 0 };
    byProvider[t.provider].calls++;
    byProvider[t.provider].totalLatency += t.latency_ms;
    byProvider[t.provider].totalCost += t.cost_usd;
  }

  const byModelFormatted: Record<string, { calls: number; avg_latency: number; cost: number }> = {};
  for (const [model, data] of Object.entries(byModel)) {
    byModelFormatted[model] = {
      calls: data.calls,
      avg_latency: Math.round(data.totalLatency / data.calls),
      cost: Math.round(data.totalCost * 10000) / 10000,
    };
  }

  const byProviderFormatted: Record<string, { calls: number; avg_latency: number; cost: number }> = {};
  for (const [provider, data] of Object.entries(byProvider)) {
    byProviderFormatted[provider] = {
      calls: data.calls,
      avg_latency: Math.round(data.totalLatency / data.calls),
      cost: Math.round(data.totalCost * 10000) / 10000,
    };
  }

  return {
    total_calls: traces.length,
    avg_latency_ms: Math.round(latencies.reduce((a, b) => a + b, 0) / latencies.length),
    p95_latency_ms: latencies[p95Index] || 0,
    total_tokens: traces.reduce((s, t) => s + t.tokens_in + t.tokens_out, 0),
    total_cost_usd: Math.round(traces.reduce((s, t) => s + t.cost_usd, 0) * 10000) / 10000,
    success_rate: Math.round((successCount / traces.length) * 100),
    by_model: byModelFormatted,
    by_provider: byProviderFormatted,
  };
}

export function observabilityCommand(): Command {
  const cmd = new Command('observability')
    .description('Observability & Tracing de chamadas de IA');

  cmd
    .command('trace')
    .description('Registra uma chamada de IA no trace log')
    .requiredOption('--model <model>', 'Modelo utilizado (ex: gpt-4, claude-3, qwen2)')
    .requiredOption('--provider <provider>', 'Provedor (ex: openai, anthropic, ollama)')
    .requiredOption('--latency <ms>', 'Latencia em milissegundos')
    .requiredOption('--tokens-in <n>', 'Tokens de entrada')
    .requiredOption('--tokens-out <n>', 'Tokens de saida')
    .option('--cost <usd>', 'Custo em USD', '0')
    .option('--command <cmd>', 'Comando que originou a chamada', 'unknown')
    .option('--status <status>', 'Status (success, error, timeout)', 'success')
    .option('--error <msg>', 'Mensagem de erro se status=error')
    .action((options) => {
      const root = process.cwd();
      ensureDir(root);

      const entry: TraceEntry = {
        timestamp: new Date().toISOString(),
        model: options.model,
        provider: options.provider,
        latency_ms: parseInt(options.latency, 10),
        tokens_in: parseInt(options.tokensIn, 10),
        tokens_out: parseInt(options.tokensOut, 10),
        cost_usd: parseFloat(options.cost),
        command: options.command,
        status: options.status,
        error: options.error,
      };

      fs.appendFileSync(getTracesPath(root), JSON.stringify(entry) + '\n');

      printResult('trace', true, `${options.provider}/${options.model} (${options.latency}ms)`);
      finish({
        checkpoint: 'observability_trace',
        ok: true,
        status: 'passed',
        context_summary: `Trace registrado: ${options.provider}/${options.model}`,
        data: entry as unknown as Record<string, unknown>,
      });
    });

  cmd
    .command('metrics')
    .description('Calcula metricas agregadas dos traces')
    .option('--save', 'Salva metricas em arquivo JSON', false)
    .action((options) => {
      const root = process.cwd();
      const traces = readTraces(root);
      const metrics = computeMetrics(traces);

      printHeader('Observability Metrics');
      printLine(`Total calls: ${metrics.total_calls}`);
      printLine(`Avg latency: ${metrics.avg_latency_ms}ms`);
      printLine(`P95 latency: ${metrics.p95_latency_ms}ms`);
      printLine(`Total tokens: ${metrics.total_tokens}`);
      printLine(`Total cost: $${metrics.total_cost_usd}`);
      printLine(`Success rate: ${metrics.success_rate}%`);
      printLine('');
      printLine('By Model:');
      for (const [model, data] of Object.entries(metrics.by_model)) {
        printLine(`  ${model}: ${data.calls} calls, ${data.avg_latency}ms avg, $${data.cost}`);
      }
      printLine('');
      printLine('By Provider:');
      for (const [provider, data] of Object.entries(metrics.by_provider)) {
        printLine(`  ${provider}: ${data.calls} calls, ${data.avg_latency}ms avg, $${data.cost}`);
      }

      if (options.save) {
        const metricsPath = getMetricsPath(root);
        fs.writeFileSync(metricsPath, JSON.stringify(metrics, null, 2));
        printLine(`\nMetrics saved to ${metricsPath}`);
      }

      finish({
        checkpoint: 'observability_metrics',
        ok: true,
        status: 'passed',
        context_summary: `Metrics: ${metrics.total_calls} calls, $${metrics.total_cost_usd} total cost`,
        data: metrics as unknown as Record<string, unknown>,
      });
    });

  cmd
    .command('dashboard')
    .description('Gera dashboard JSON com metricas e ultimos traces')
    .action(() => {
      const root = process.cwd();
      const traces = readTraces(root);
      const metrics = computeMetrics(traces);
      const recentTraces = traces.slice(-20).reverse();

      const dashboard = {
        generated_at: new Date().toISOString(),
        metrics,
        recent_traces: recentTraces,
      };

      const dashboardPath = path.join(root, TRACES_DIR, 'dashboard.json');
      fs.writeFileSync(dashboardPath, JSON.stringify(dashboard, null, 2));

      printHeader('Observability Dashboard');
      printLine(`Generated: ${dashboard.generated_at}`);
      printLine(`Total calls: ${metrics.total_calls}`);
      printLine(`Total cost: $${metrics.total_cost_usd}`);
      printLine(`Dashboard saved to: ${dashboardPath}`);

      finish({
        checkpoint: 'observability_dashboard',
        ok: true,
        status: 'passed',
        context_summary: `Dashboard generated with ${metrics.total_calls} traces`,
        data: { path: dashboardPath, metrics: metrics as unknown as Record<string, unknown> },
      });
    });

  cmd
    .command('list')
    .description('Lista os ultimos traces registrados')
    .option('--limit <n>', 'Numero de traces a exibir', '10')
    .action((options) => {
      const root = process.cwd();
      const traces = readTraces(root);
      const limit = parseInt(options.limit, 10);
      const recent = traces.slice(-limit).reverse();

      printHeader(`Recent Traces (last ${recent.length})`);
      for (const t of recent) {
        const icon = t.status === 'success' ? '✅' : t.status === 'error' ? '❌' : '⏱️';
        printLine(`${icon} [${t.timestamp}] ${t.provider}/${t.model} — ${t.latency_ms}ms — $${t.cost_usd}`);
      }
      printLine(`\nTotal traces: ${traces.length}`);

      finish({
        checkpoint: 'observability_list',
        ok: true,
        status: 'passed',
        context_summary: `Listed ${recent.length} traces`,
        data: { total: traces.length, shown: recent.length },
      });
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { printHeader, printLine, printResult, finish } from "../utils/output";

const BUDGET_CONFIG_PATH = '.ai/performance/budget.yaml';
const BUDGET_HISTORY_PATH = '.ai/reports/performance/history.jsonl';

interface BudgetConfig {
  budget: {
    bundleSize?: { max: number; unit: 'kb' | 'mb' };
    lighthouseScore?: { min: number };
    apiLatency?: { max: number; unit: 'ms' | 's' };
    memoryUsage?: { max: number; unit: 'mb' | 'gb' };
    fcp?: { max: number; unit: 'ms' | 's' };
    lcp?: { max: number; unit: 'ms' | 's' };
    tti?: { max: number; unit: 'ms' | 's' };
  };
  alerts: { onExceed: 'warn' | 'error' };
}

function defaultBudgetConfig(): BudgetConfig {
  return {
    budget: {
      bundleSize: { max: 500, unit: 'kb' },
      lighthouseScore: { min: 80 },
      apiLatency: { max: 200, unit: 'ms' },
      memoryUsage: { max: 512, unit: 'mb' },
      fcp: { max: 2000, unit: 'ms' },
      lcp: { max: 4000, unit: 'ms' },
      tti: { max: 5000, unit: 'ms' },
    },
    alerts: { onExceed: 'warn' },
  };
}

function loadBudget(root: string): BudgetConfig {
  const cfgPath = path.join(root, BUDGET_CONFIG_PATH);
  if (fs.existsSync(cfgPath)) return JSON.parse(fs.readFileSync(cfgPath, 'utf-8'));
  return defaultBudgetConfig();
}

function calculateBundleSize(root: string): { value: number; unit: 'kb'; label: string } {
  try {
    const distDir = path.join(root, 'dist');
    if (!fs.existsSync(distDir)) return { value: 0, unit: 'kb', label: 'dist nao encontrado' };
    let totalBytes = 0;
    function countSize(dir: string): void {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const fp = path.join(dir, e.name);
        if (e.isDirectory()) countSize(fp);
        else totalBytes += fs.statSync(fp).size;
      }
    }
    countSize(distDir);
    return { value: Math.round(totalBytes / 1024), unit: 'kb', label: `${Math.round(totalBytes / 1024)}kb` };
  } catch {
    return { value: -1, unit: 'kb', label: 'erro ao medir' };
  }
}

function calculateLighthouseScore(): { value: number; label: string } {
  return { value: -1, label: 'N/A (executar lighthouse manualmente)' };
}

function calculateApiLatency(): { value: number; unit: 'ms'; label: string } {
  return { value: -1, unit: 'ms', label: 'N/A (servidor precisa estar rodando)' };
}

function calculateMemoryUsage(): { value: number; unit: 'mb'; label: string } {
  try {
    const usage = process.memoryUsage();
    return { value: Math.round(usage.heapUsed / 1024 / 1024), unit: 'mb', label: `${Math.round(usage.heapUsed / 1024 / 1024)}mb` };
  } catch {
    return { value: -1, unit: 'mb', label: 'erro ao medir' };
  }
}

function checkBudget(budget: BudgetConfig): { metric: string; budget: string; actual: string; passed: boolean }[] {
  const results: { metric: string; budget: string; actual: string; passed: boolean }[] = [];
  const checks = budget.budget;

  if (checks.bundleSize) {
    const actual = calculateBundleSize(process.cwd());
    results.push({
      metric: 'Bundle Size',
      budget: `${checks.bundleSize.max}${checks.bundleSize.unit}`,
      actual: actual.label,
      passed: actual.value >= 0 ? actual.value <= checks.bundleSize.max : true,
    });
  }

  if (checks.lighthouseScore) {
    const actual = calculateLighthouseScore();
    results.push({
      metric: 'Lighthouse Score',
      budget: `>= ${checks.lighthouseScore.min}`,
      actual: actual.label,
      passed: actual.value >= 0 ? actual.value >= checks.lighthouseScore.min : true,
    });
  }

  if (checks.apiLatency) {
    const actual = calculateApiLatency();
    const maxMs = checks.apiLatency.unit === 's' ? checks.apiLatency.max * 1000 : checks.apiLatency.max;
    results.push({
      metric: 'API Latency',
      budget: `<= ${checks.apiLatency.max}${checks.apiLatency.unit}`,
      actual: actual.label,
      passed: actual.value >= 0 ? actual.value <= maxMs : true,
    });
  }

  if (checks.memoryUsage) {
    const actual = calculateMemoryUsage();
    const maxMb = checks.memoryUsage.unit === 'gb' ? checks.memoryUsage.max * 1024 : checks.memoryUsage.max;
    results.push({
      metric: 'Memory Usage',
      budget: `<= ${checks.memoryUsage.max}${checks.memoryUsage.unit}`,
      actual: actual.label,
      passed: actual.value >= 0 ? actual.value <= maxMb : true,
    });
  }

  return results;
}

export function performanceCommand(): Command {
  const cmd = new Command('performance')
    .description('Performance budget e metricas');

  cmd
    .command('budget')
    .description('Gerencia configuracao de performance budget')
    .argument('<action>', 'init | check | report')
    .action((action: string) => {
      const root = process.cwd();
      const cfgDir = path.dirname(path.join(root, BUDGET_CONFIG_PATH));

      switch (action) {
        case 'init': {
          printHeader('Performance Budget Init');
          const config = defaultBudgetConfig();
          fs.mkdirSync(cfgDir, { recursive: true });
          fs.writeFileSync(path.join(root, BUDGET_CONFIG_PATH), JSON.stringify(config, null, 2));
          printResult('Configuracao criada', true, BUDGET_CONFIG_PATH);
          finish({
            checkpoint: 'performance_budget_init',
            ok: true,
            status: 'passed',
            context_summary: `Budget configurado em ${BUDGET_CONFIG_PATH}`,
            data: { metrics: Object.keys(config.budget) },
          });
          break;
        }

        case 'check': {
          printHeader('Performance Budget Check');
          const budget = loadBudget(root);
          const results = checkBudget(budget);
          let allPassed = true;

          for (const r of results) {
            printResult(r.metric, r.passed, `${r.actual} (budget: ${r.budget})`);
            if (!r.passed) allPassed = false;
          }

          if (results.length === 0) printLine('Nenhuma metrica configurada.');

          const historyDir = path.dirname(path.join(root, BUDGET_HISTORY_PATH));
          fs.mkdirSync(historyDir, { recursive: true });
          const entry = JSON.stringify({ date: new Date().toISOString(), results, allPassed }) + '\n';
          fs.appendFileSync(path.join(root, BUDGET_HISTORY_PATH), entry);

          finish({
            checkpoint: 'performance_budget_check',
            ok: allPassed,
            status: allPassed ? 'passed' : 'failed',
            context_summary: `${results.filter(r => r.passed).length}/${results.length} metricas dentro do budget`,
            data: { results, allPassed },
          });
          break;
        }

        case 'report': {
          printHeader('Performance Budget Report');
          const historyPath = path.join(root, BUDGET_HISTORY_PATH);
          if (!fs.existsSync(historyPath)) {
            printLine('Nenhum historico encontrado. Execute "performance budget check" primeiro.');
            finish({ checkpoint: 'performance_budget_report', ok: true, status: 'passed', context_summary: 'Sem historico', data: {} });
            return;
          }

          const lines = fs.readFileSync(historyPath, 'utf-8').split('\n').filter(Boolean);
          const entries = lines.map(l => JSON.parse(l));
          printLine(`Total de checks: ${entries.length}`);
          const passRate = entries.filter((e: { allPassed: boolean }) => e.allPassed).length / entries.length * 100;
          printLine(`Taxa de aprovacao: ${Math.round(passRate)}%`);
          printLine('');
          printLine(`Ultimo check: ${entries[entries.length - 1]?.date || 'N/A'}`);

          finish({
            checkpoint: 'performance_budget_report',
            ok: true,
            status: 'passed',
            context_summary: `${entries.length} checks, ${Math.round(passRate)}% aprovacao`,
            data: { totalChecks: entries.length, passRate: Math.round(passRate) },
          });
          break;
        }

        default: {
          printResult('Erro', false, `Acao desconhecida: "${action}". Use init, check ou report`);
          finish({ checkpoint: 'performance_budget', ok: false, status: 'failed', context_summary: `Acao desconhecida: ${action}` });
        }
      }
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { printLine, printResult, finish } from "../utils/output";
import { loadPlugins, findPlugin, LoadedPlugin } from '../plugins/loader';
import { validateManifest, PluginCapability } from '../plugins/manifest';
import { runPluginHook, HookName } from '../plugins/hooks';

const VALID_CAPABILITIES: PluginCapability[] = ['agents', 'skills', 'rules', 'commands', 'templates'];

function pluginListAction(): void {
  const root = process.cwd();
  const plugins = loadPlugins(root);

  if (plugins.length === 0) {
    printLine('Nenhum plugin encontrado.');
    return;
  }

  printLine(`Plugins instalados (${plugins.length}):\n`);
  for (const p of plugins) {
    const caps = p.manifest.capabilities.join(', ');
    printLine(`  ${p.manifest.name} v${p.manifest.version}`);
    printLine(`    Author: ${p.manifest.author}`);
    printLine(`    Capabilities: ${caps}`);
    if (p.manifest.description) {
      printLine(`    Description: ${p.manifest.description}`);
    }
    printLine('');
  }
}

function pluginInstallAction(name: string, options: { path?: string }): void {
  const root = process.cwd();
  const pluginsDir = path.join(root, '.ai/plugins');

  if (findPlugin(root, name)) {
    printResult(`Plugin "${name}" ja esta instalado.`, false);
    return;
  }

  if (options.path) {
    const src = path.resolve(options.path);
    if (!fs.existsSync(src)) {
      printResult(`Caminho nao encontrado: ${src}`, false);
      return;
    }
    if (!fs.existsSync(path.join(src, 'plugin.yaml')) && !fs.existsSync(path.join(src, 'plugin.yml')) && !fs.existsSync(path.join(src, 'plugin.json'))) {
      printResult(`Diretorio nao contem plugin.yaml/plugin.yml/plugin.json valido.`, false);
      return;
    }
    const dest = path.join(pluginsDir, name);
    fs.mkdirSync(pluginsDir, { recursive: true });
    copyDirSync(src, dest);
    printResult(`Plugin "${name}" instalado de ${options.path}`, true);
    return;
  }

  printResult(`Plugin "${name}" nao encontrado. Use --path para especificar diretorio local.`, false);
}

function pluginUninstallAction(name: string): void {
  const root = process.cwd();
  const installed = loadPlugins(root);
  const plugin = installed.find(p => p.manifest.name === name);

  if (!plugin) {
    printResult(`Plugin "${name}" nao encontrado.`, false);
    return;
  }

  fs.rmSync(plugin.dir, { recursive: true, force: true });
  printResult(`Plugin "${name}" removido.`, true);
}

function pluginCreateAction(name: string): void {
  const root = process.cwd();
  const pluginsDir = path.join(root, '.ai/plugins', name);

  if (fs.existsSync(pluginsDir)) {
    printResult(`Diretorio .ai/plugins/${name} ja existe.`, false);
    return;
  }

  fs.mkdirSync(pluginsDir, { recursive: true });

  const manifest: Record<string, unknown> = {
    name,
    version: '1.0.0',
    author: 'unknown',
    description: `Plugin ${name}`,
    capabilities: ['rules'],
  };

  fs.writeFileSync(path.join(pluginsDir, 'plugin.yaml'), YAML.stringify(manifest));
  fs.writeFileSync(path.join(pluginsDir, 'index.js'), `// Plugin ${name} — gerado automaticamente\n`);

  printResult(`Plugin "${name}" criado em .ai/plugins/${name}`, true);
  printLine(`  Edite .ai/plugins/${name}/plugin.yaml para configurar`);
}

function pluginValidateAction(name?: string): void {
  const root = process.cwd();
  const plugins = name ? [findPlugin(root, name)].filter(Boolean) as LoadedPlugin[] : loadPlugins(root);

  if (plugins.length === 0) {
    printLine('Nenhum plugin para validar.');
    return;
  }

  let allValid = true;
  for (const p of plugins) {
    const manifestPath = path.join(p.dir, 'plugin.yaml');
    if (!fs.existsSync(manifestPath)) {
      const alt = path.join(p.dir, 'plugin.json');
      if (!fs.existsSync(alt)) {
        printResult(`${p.manifest.name}: manifest nao encontrado`, false);
        allValid = false;
        continue;
      }
    }

    const raw = fs.readFileSync(manifestPath, 'utf8');
    const data = YAML.parse(raw);
    const { valid, errors } = validateManifest(data || {});

    if (valid) {
      printLine(`${p.manifest.name}: VALIDO`);
    } else {
      printResult(`${p.manifest.name}: INVALIDO — ${errors.join('; ')}`, false);
      allValid = false;
    }
  }

  if (allValid) printResult('Todos os plugins sao validos.', true);
}

export function pluginCommand(): Command {
  const cmd = new Command('plugin')
    .description('Gerencia plugins do ai-devkit');

  cmd
    .command('list')
    .description('Lista plugins instalados')
    .action(pluginListAction);

  cmd
    .command('install')
    .description('Instala plugin de diretorio local')
    .argument('<name>', 'Nome do plugin')
    .option('--path <path>', 'Caminho do diretorio do plugin')
    .action(pluginInstallAction);

  cmd
    .command('uninstall')
    .description('Remove plugin')
    .argument('<name>', 'Nome do plugin')
    .action(pluginUninstallAction);

  cmd
    .command('create')
    .description('Cria scaffold de novo plugin')
    .argument('<name>', 'Nome do plugin')
    .action(pluginCreateAction);

  cmd
    .command('validate')
    .description('Valida manifest de plugins')
    .argument('[name]', 'Nome do plugin (opcional — valida todos se omitido)')
    .action(pluginValidateAction);

  return cmd;
}

function copyDirSync(src: string, dest: string): void {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDirSync(s, d);
    } else {
      fs.copyFileSync(s, d);
    }
  }
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printHeader, printLine, printResult, finish } from "../utils/output";

// ============================================================
// TASK-GAP-12: Prompt Management & Versioning
// ============================================================

const PROMPTS_DIR = '.ai/prompts/versions';

interface PromptVersion {
  version: string;
  name: string;
  content: string;
  created_at: string;
  hash: string;
  description?: string;
}

function getVersionsDir(root: string): string {
  return path.join(root, PROMPTS_DIR);
}

function getVersionPath(root: string, name: string, version: string): string {
  return path.join(getVersionsDir(root), name, `${version}.md`);
}

function getIndexPath(root: string, name: string): string {
  return path.join(getVersionsDir(root), name, 'index.json');
}

function ensureDir(p: string): void {
  fs.mkdirSync(p, { recursive: true });
}

function computeHash(content: string): string {
  let hash = 0;
  for (let i = 0; i < content.length; i++) {
    const char = content.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16).padStart(8, '0');
}

function readVersions(root: string, name: string): PromptVersion[] {
  const indexPath = getIndexPath(root, name);
  if (!fs.existsSync(indexPath)) return [];
  try {
    return JSON.parse(fs.readFileSync(indexPath, 'utf8'));
  } catch {
    return [];
  }
}

function writeVersions(root: string, name: string, versions: PromptVersion[]): void {
  const indexPath = getIndexPath(root, name);
  ensureDir(path.dirname(indexPath));
  fs.writeFileSync(indexPath, JSON.stringify(versions, null, 2));
}

export function promptCommand(): Command {
  const cmd = new Command('prompt')
    .description('Prompt Management & Versioning');

  cmd
    .command('save <name>')
    .description('Salva uma nova versao de prompt')
    .requiredOption('--content <content>', 'Conteudo do prompt')
    .option('--version <version>', 'Versao semantica (ex: 1.0.0)', '1.0.0')
    .option('--description <desc>', 'Descricao da versao')
    .option('--file <path>', 'Caminho para arquivo com conteudo do prompt')
    .action((name: string, options) => {
      const root = process.cwd();
      const content = options.file
        ? fs.readFileSync(path.resolve(root, options.file), 'utf8')
        : options.content;

      if (!content) {
        printResult('save', false, 'Conteudo do prompt nao fornecido');
        finish({
          checkpoint: 'prompt_save',
          ok: false,
          status: 'failed',
          context_summary: 'No content provided',
        });
        return;
      }

      const version: PromptVersion = {
        version: options.version,
        name,
        content,
        created_at: new Date().toISOString(),
        hash: computeHash(content),
        description: options.description,
      };

      const versionPath = getVersionPath(root, name, options.version);
      ensureDir(path.dirname(versionPath));
      fs.writeFileSync(versionPath, content);

      const versions = readVersions(root, name);
      versions.push(version);
      writeVersions(root, name, versions);

      printResult('save', true, `${name}@${options.version} (${content.length} chars)`);
      finish({
        checkpoint: 'prompt_save',
        ok: true,
        status: 'passed',
        context_summary: `Saved ${name}@${options.version}`,
        data: { name, version: options.version, hash: version.hash, chars: content.length },
      });
    });

  cmd
    .command('list [name]')
    .description('Lista prompts ou versoes de um prompt')
    .action((name?: string) => {
      const root = process.cwd();
      const versionsDir = getVersionsDir(root);

      if (!fs.existsSync(versionsDir)) {
        printLine('No prompts found');
        finish({
          checkpoint: 'prompt_list',
          ok: true,
          status: 'passed',
          context_summary: 'No prompts found',
        });
        return;
      }

      if (name) {
        const versions = readVersions(root, name);
        printHeader(`Prompt: ${name}`);
        for (const v of versions) {
          printLine(`  ${v.version} — ${v.created_at} (${v.content.length} chars) ${v.description ? `— ${v.description}` : ''}`);
        }
        printLine(`\nTotal versions: ${versions.length}`);
      } else {
        const dirs = fs.readdirSync(versionsDir, { withFileTypes: true })
          .filter(d => d.isDirectory())
          .map(d => d.name);

        printHeader('Prompts');
        for (const dir of dirs) {
          const versions = readVersions(root, dir);
          const latest = versions[versions.length - 1];
          printLine(`  ${dir} — ${versions.length} versions ${latest ? `(latest: ${latest.version})` : ''}`);
        }
        printLine(`\nTotal prompts: ${dirs.length}`);
      }

      finish({
        checkpoint: 'prompt_list',
        ok: true,
        status: 'passed',
        context_summary: `Listed prompts`,
      });
    });

  cmd
    .command('show <name>')
    .description('Exibe o conteudo de uma versao de prompt')
    .option('--version <version>', 'Versao a exibir', 'latest')
    .action((name: string, options) => {
      const root = process.cwd();
      const versions = readVersions(root, name);

      if (versions.length === 0) {
        printResult('show', false, `Prompt "${name}" nao encontrado`);
        finish({
          checkpoint: 'prompt_show',
          ok: false,
          status: 'failed',
          context_summary: `Prompt "${name}" not found`,
        });
        return;
      }

      const version = options.version === 'latest'
        ? versions[versions.length - 1]
        : versions.find(v => v.version === options.version);

      if (!version) {
        printResult('show', false, `Versao "${options.version}" nao encontrada`);
        finish({
          checkpoint: 'prompt_show',
          ok: false,
          status: 'failed',
          context_summary: `Version "${options.version}" not found`,
        });
        return;
      }

      printHeader(`${name}@${version.version}`);
      printLine(`Description: ${version.description || 'N/A'}`);
      printLine(`Created: ${version.created_at}`);
      printLine(`Hash: ${version.hash}`);
      printLine(`Chars: ${version.content.length}`);
      printLine('');
      printLine(version.content);

      finish({
        checkpoint: 'prompt_show',
        ok: true,
        status: 'passed',
        context_summary: `Showed ${name}@${version.version}`,
        data: { name, version: version.version, hash: version.hash },
      });
    });

  cmd
    .command('diff <name>')
    .description('Mostra diff entre duas versoes de prompt')
    .requiredOption('--from <version>', 'Versao base')
    .requiredOption('--to <version>', 'Versao alvo')
    .action((name: string, options) => {
      const root = process.cwd();
      const versions = readVersions(root, name);

      const fromVersion = versions.find(v => v.version === options.from);
      const toVersion = versions.find(v => v.version === options.to);

      if (!fromVersion || !toVersion) {
        printResult('diff', false, 'Uma ou ambas as versoes nao encontradas');
        finish({
          checkpoint: 'prompt_diff',
          ok: false,
          status: 'failed',
          context_summary: 'Versions not found',
        });
        return;
      }

      const fromLines = fromVersion.content.split('\n');
      const toLines = toVersion.content.split('\n');

      printHeader(`Diff: ${name} ${options.from} → ${options.to}`);
      printLine(`From: ${fromVersion.created_at} (${fromVersion.content.length} chars)`);
      printLine(`To: ${toVersion.created_at} (${toVersion.content.length} chars)`);
      printLine('');

      let changes = 0;
      const maxLines = Math.max(fromLines.length, toLines.length);
      for (let i = 0; i < maxLines; i++) {
        if (fromLines[i] !== toLines[i]) {
          if (i < fromLines.length) {
            printLine(`- ${fromLines[i]}`);
            changes++;
          }
          if (i < toLines.length) {
            printLine(`+ ${toLines[i]}`);
            changes++;
          }
        }
      }

      if (changes === 0) {
        printLine('No differences found');
      } else {
        printLine(`\n${changes} line changes`);
      }

      finish({
        checkpoint: 'prompt_diff',
        ok: true,
        status: 'passed',
        context_summary: `Diff ${name}: ${changes} changes`,
        data: { name, from: options.from, to: options.to, changes },
      });
    });

  cmd
    .command('rollback <name>')
    .description('Restaura uma versao anterior do prompt')
    .requiredOption('--version <version>', 'Versao para restaurar')
    .action((name: string, options) => {
      const root = process.cwd();
      const versions = readVersions(root, name);

      const targetVersion = versions.find(v => v.version === options.version);
      if (!targetVersion) {
        printResult('rollback', false, `Versao "${options.version}" nao encontrada`);
        finish({
          checkpoint: 'prompt_rollback',
          ok: false,
          status: 'failed',
          context_summary: 'Version not found',
        });
        return;
      }

      // Create a new version with rollback content
      const newVersion: PromptVersion = {
        version: `${options.version}-rollback-${Date.now()}`,
        name,
        content: targetVersion.content,
        created_at: new Date().toISOString(),
        hash: computeHash(targetVersion.content),
        description: `Rollback to ${options.version}`,
      };

      const versionPath = getVersionPath(root, name, newVersion.version);
      ensureDir(path.dirname(versionPath));
      fs.writeFileSync(versionPath, newVersion.content);

      versions.push(newVersion);
      writeVersions(root, name, versions);

      printResult('rollback', true, `${name} rolled back to ${options.version}`);
      finish({
        checkpoint: 'prompt_rollback',
        ok: true,
        status: 'passed',
        context_summary: `Rolled back ${name} to ${options.version}`,
        data: { name, version: options.version, newVersion: newVersion.version },
      });
    });

  return cmd;
}

import { Command } from "commander";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";

export function proveCommand(): Command {
  const cmd = new Command("prove").description("Prova funcionamento ponta a ponta do ai-devkit (E2E Test)");
  cmd.action(() => {
      let appendEntry: (cmd: string, status: number, output: string) => void = () => {};
      try {
        appendEntry = require(path.join(process.cwd(), '.ai/bin/ledger.js')).appendEntry;
      } catch {
        // ledger.js optional — proceed with noop attestation
      }
      const root = process.cwd();
      const logDir = path.join(root, ".ai/audit/test-runs");
      if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
      const logFile = path.join(logDir, `prove-${Date.now()}.log`);

      let logContent = "=== AI-DEVKIT PROVE ===\n\n";
      const log = (msg: string) => {
        console.log(msg);
        logContent += msg + "\n";
      };

      const run = (step: string, cmdStr: string, args: string[], cwd: string = root) => {
        log(`\n[🏃] ${step}`);
        const res = spawnSync(cmdStr, args, { cwd, encoding: "utf8", shell: os.platform() === 'win32' });
        logContent += res.stdout + "\n" + res.stderr + "\n";
        if (res.status !== 0) {
          log(`❌ Falha: ${step}`);
          fs.writeFileSync(logFile, logContent);
          appendEntry('prove', 1, logContent);
          process.exit(1);
        }
        log(`✅ Sucesso: ${step}`);
      };

      const cliDir = path.join(__dirname, "../../");
      const cliBin = path.join(__dirname, "../index.js");
      const tmpDir = path.join(os.tmpdir(), `ai-devkit-prove-${Date.now()}`);

      run("1. Compilar CLI", "npm", ["run", "build"], cliDir);
      run("2. CLI --help", "node", [cliBin, "--help"]);

      fs.mkdirSync(tmpDir, { recursive: true });
      run("3. Init Structure", "node", [cliBin, "init", tmpDir, "--flavor", "nestjs", "--yes"]);

      log("\n[🏃] 4. Status");
      const resStatus = spawnSync("node", [cliBin, "status"], { cwd: tmpDir, encoding: "utf8" });
      logContent += resStatus.stdout + "\n" + resStatus.stderr + "\n";
      if (!resStatus.stdout.includes("Project Health")) {
         log("❌ Falha crítica: Status não gerou saída de saúde.");
         fs.writeFileSync(logFile, logContent);
         appendEntry("prove", 1, logContent);
         process.exit(1);
      }
      log("✅ Sucesso: 4. Status executou corretamente.");

      log("\n[🏃] 5. Verify");
      const resVerify = spawnSync("node", [cliBin, "verify"], { cwd: tmpDir, encoding: "utf8" });
      logContent += resVerify.stdout + "\n" + resVerify.stderr + "\n";
      if (!resVerify.stdout.includes("Todos os quality gates passaram")) {
         log("❌ Falha crítica: Verify não iniciou.");
         fs.writeFileSync(logFile, logContent);
          appendEntry('prove', 1, logContent);
          process.exit(1);
      }
      log("✅ Sucesso: 5. Verify executou corretamente.");

      run("6. Doctor", "node", [cliBin, "doctor"], tmpDir);
      run("7. Feature Scaffold", "node", [cliBin, "feature", "analyze", "login-module"], tmpDir);

      const featureFile = path.join(tmpDir, ".ai/features/login-module/feature-brief.md");
      if (!fs.existsSync(featureFile)) {
         log(`❌ Falha: Arquivo de feature não foi criado.`);
         process.exit(1);
      }

      run("8. Context Pack", "node", [cliBin, "context", "pack", "login-context"], tmpDir);
      if (!fs.existsSync(path.join(tmpDir, ".ai/context-packs/login-context.md"))) {
         log(`❌ Falha: Context pack não gerado.`);
         process.exit(1);
      }

      run("9. Generators Execute", "node", [path.join(tmpDir, ".ai/bin/skeleton.js")], tmpDir);

      log("\n[🏃] 10. Arquivos críticos não estão vazios");
      const criticalFiles = [".ai/laws.yaml", ".ai/project-manifest.yaml", ".ai/context/ai-handoff.md"];
      for (const f of criticalFiles) {
        const fp = path.join(tmpDir, f);
        if (fs.existsSync(fp)) {
           if (fs.statSync(fp).size < 5) {
             log(`❌ Arquivo vazio: ${f}`);
             process.exit(1);
           }
        }
      }
      log("✅ Sucesso: 10. Arquivos críticos validados.");

      log("\n[🏃] 11. Varredura por stubs abandonados");
      const stubResult = spawnSync("node", [path.join(tmpDir, ".ai/bin/check-placeholder-policy.js")], { cwd: tmpDir, encoding: "utf8" });
      logContent += stubResult.stdout + "\n" + stubResult.stderr + "\n";
      if (stubResult.status !== 0) {
         log("❌ Falha crítica: Stub encontrado na varredura.");
         fs.writeFileSync(logFile, logContent);
          appendEntry('prove', 1, logContent);
          process.exit(1);
      }
      log("✅ Sucesso: 11. Nenhum stub real encontrado.");

      fs.writeFileSync(logFile, logContent);
      log(`\n🎉 PROVE EXECUTADO COM SUCESSO!`);

      log(`📄 Logs salvos em: ${logFile}`);

  });
  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { generateReleaseNotes, formatReleaseNotes } from '../release/notes';
import { prepareRelease } from '../release/preparer';
import { publishRelease } from '../release/publisher';
import { printHeader, printLine, printResult, finish } from "../utils/output";

function detectPackageManager(root: string): string {
  if (fs.existsSync(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
  if (fs.existsSync(path.join(root, 'yarn.lock'))) return 'yarn';
  return 'npm';
}

function dockerfileContent(): string {
  return `# Multi-stage Dockerfile gerado por ai-devkit
FROM node:20-alpine AS builder
WORKDIR /app
COPY package*.json ./
RUN npm ci
COPY . .
RUN npm run build

FROM node:20-alpine AS production
WORKDIR /app
COPY --from=builder /app/dist ./dist
COPY --from=builder /app/node_modules ./node_modules
COPY --from=builder /app/package.json ./
EXPOSE 3000
CMD ["node", "dist/index.js"]
`;
}

function k8sDeploymentContent(name: string): string {
