export function releaseCommand(): Command {
  const cmd = new Command('release')
    .description('Automacao de release, CI/CD e publicacao');

  cmd
    .command('prepare')
    .description('Prepara uma nova release (bump version, changelog, tag)')
    .requiredOption('-V, --ver <semver>', 'Versao semver (ex: 1.2.3)')
    .option('--dry-run', 'Simula sem modificar arquivos')
    .action((options: { ver: string; dryRun?: boolean }) => {
      const semverRegex = /^\d+\.\d+\.\d+$/;
      if (!semverRegex.test(options.ver)) {
        printResult('Erro', false, `Versao invalida: "${options.ver}". Use semver (ex: 1.2.3)`);
        finish({ checkpoint: 'release_prepare', ok: false, status: 'failed', context_summary: `Versao invalida: ${options.ver}` });
        return;
      }

      printHeader(`Preparando release v${options.ver}`);
      const result = prepareRelease(options.ver, options.dryRun);

      if (options.dryRun) {
        printLine(`[DRY-RUN] Versao: ${result.version}`);
        printLine(`[DRY-RUN] Tag: ${result.tag}`);
        printLine(`[DRY-RUN] Anterior: v${result.previousVersion}`);
        printLine(`[DRY-RUN] Commits desde ultima tag: ${result.commitsSinceLast}`);
      } else {
        printResult('Versao', true, result.version);
        printResult('Tag', true, result.tag);
        printResult('Changelog', true, result.changelogPath);
        printLine(`Commits desde v${result.previousVersion}: ${result.commitsSinceLast}`);
      }

      finish({
        checkpoint: 'release_prepare',
        ok: true,
        status: 'passed',
        context_summary: options.dryRun
          ? `[DRY-RUN] Release v${result.version} pronta`
          : `Release v${result.version} preparada — tag ${result.tag}`,
        data: { version: result.version, tag: result.tag, previousVersion: result.previousVersion, commitsSinceLast: result.commitsSinceLast, dryRun: !!options.dryRun },
      });
    });

  cmd
    .command('publish')
    .description('Publica release nos registros configurados')
    .option('--dry-run', 'Simula publicacao')
    .action((options: { dryRun?: boolean }) => {
      let version = '0.0.0';
      try {
        const pkg = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'package.json'), 'utf-8'));
        version = pkg.version;
      } catch { /* use default */ }

      printHeader(`Publicando v${version}`);
      const result = publishRelease(version, options.dryRun);

      if (result.errors.length > 0) {
        for (const err of result.errors) printResult('Erro', false, err);
      }

      if (result.artifacts.length > 0) {
        for (const art of result.artifacts) printResult('Publicado', true, art);
      }

      finish({
        checkpoint: 'release_publish',
        ok: result.published,
        status: result.published ? 'passed' : 'failed',
        context_summary: result.published
          ? `${result.artifacts.length} artefato(s) publicado(s)`
          : `Falha na publicacao: ${result.errors.join('; ')}`,
        data: { version, published: result.published, artifacts: result.artifacts, errors: result.errors, dryRun: !!options.dryRun },
      });
    });

  cmd
    .command('notes')
    .description('Gera release notes automaticas entre tags')
    .option('-f, --from <tag>', 'Tag inicial', 'HEAD~10')
    .option('-t, --to <tag>', 'Tag final', 'HEAD')
    .option('-o, --out <file>', 'Arquivo de saida')
    .action((options: { from: string; to: string; out?: string }) => {
      printHeader(`Release Notes: ${options.from} → ${options.to}`);
      const notes = generateReleaseNotes(options.from, options.to);
      const formatted = formatReleaseNotes(notes);

      printLine(formatted);

      if (options.out) {
        const outPath = path.resolve(options.out);
        fs.writeFileSync(outPath, formatted);
        printResult('Salvo', true, options.out);
      }

      finish({
        checkpoint: 'release_notes',
        ok: true,
        status: 'passed',
        context_summary: `Features: ${notes.features.length}, Fixes: ${notes.fixes.length}, Breaking: ${notes.breakingChanges.length}`,
        data: { from: options.from, to: options.to, features: notes.features.length, fixes: notes.fixes.length, breakingChanges: notes.breakingChanges.length },
      });
    });

  cmd
    .command('changelog')
    .description('Gera changelog a partir de commits convencionais')
    .option('-o, --out <file>', 'Arquivo de saida (default: stdout)', '')
    .action((options: { out: string }) => {
      printHeader('Gerando Changelog');
      let log = '';
      try {
        log = execSync('git log --oneline --format="%s"', { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
      } catch { /* no git repo */ }

      const commits = log.split('\n').filter(Boolean);
      const features: string[] = [];
      const fixes: string[] = [];
      const breaking: string[] = [];
      const other: string[] = [];

      for (const commit of commits) {
        if (/^feat/i.test(commit) || /^feature/i.test(commit)) features.push(commit);
        else if (/^fix/i.test(commit)) fixes.push(commit);
        else if (/^breaking/i.test(commit) || /!:/i.test(commit)) breaking.push(commit);
        else other.push(commit);
      }

      const lines: string[] = [
        '# Changelog',
        `Gerado em: ${new Date().toISOString().split('T')[0]}`,
        '',
      ];

      if (breaking.length > 0) { lines.push('## Breaking Changes'); for (const b of breaking) lines.push(`- ${b}`); lines.push(''); }
      if (features.length > 0) { lines.push('## Features'); for (const f of features) lines.push(`- ${f}`); lines.push(''); }
      if (fixes.length > 0) { lines.push('## Bug Fixes'); for (const f of fixes) lines.push(`- ${f}`); lines.push(''); }
      if (other.length > 0) { lines.push('## Other'); for (const o of other) lines.push(`- ${o}`); lines.push(''); }

      const changelogContent = lines.join('\n');

      if (options.out) {
        fs.writeFileSync(path.resolve(options.out), changelogContent);
        printResult('Changelog salvo', true, options.out);
      } else {
        printLine(changelogContent);
      }

      finish({
        checkpoint: 'release_changelog',
        ok: true,
        status: 'passed',
        context_summary: `${features.length} features, ${fixes.length} fixes, ${breaking.length} breaking`,
        data: { features: features.length, fixes: fixes.length, breaking: breaking.length, other: other.length },
      });
    });

  return cmd;
}

export function pipelineCommand(): Command {
  const cmd = new Command('pipeline')
    .description('Geracao e execucao de pipelines CI/CD');

  cmd
    .command('generate')
    .description('Gera pipelines CI/CD')
    .option('--github', 'Gera GitHub Actions')
    .option('--gitlab', 'Gera GitLab CI')
    .option('--docker', 'Gera Dockerfile multi-stage')
    .option('--k8s', 'Gera manifests Kubernetes')
    .option('--force', 'Sobrescreve arquivos existentes')
    .option('--dry-run', 'Mostra o que seria gerado sem escrever')
    .action((options: { github?: boolean; gitlab?: boolean; docker?: boolean; k8s?: boolean; force?: boolean; dryRun?: boolean }) => {
      const root = process.cwd();
      const all = !options.github && !options.gitlab && !options.docker && !options.k8s;
      const generated: string[] = [];
      const skipped: string[] = [];

      printHeader('Pipeline Generator');

      if (all || options.github) {
        const ghDir = path.join(root, '.github', 'workflows');
        const ghFile = path.join(ghDir, 'ci-pipeline.yml');
        if (!options.dryRun) {
          if (fs.existsSync(ghFile) && !options.force) {
            skipped.push('.github/workflows/ci-pipeline.yml');
          } else {
            const pkgManager = detectPackageManager(root);
            const installCmd = pkgManager === 'pnpm'
              ? 'npm install -g pnpm && pnpm install --frozen-lockfile'
              : pkgManager === 'yarn' ? 'yarn install --frozen-lockfile' : 'npm ci';
            const content = `name: CI Pipeline

on:
  push:
    branches: [main, master]
  pull_request:
    branches: [main, master]

jobs:
  ci:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: '${pkgManager}'
      - run: ${installCmd}
      - run: npm run build --if-present
      - run: npm test --if-present
`;
            fs.mkdirSync(ghDir, { recursive: true });
            fs.writeFileSync(ghFile, content);
            generated.push('.github/workflows/ci-pipeline.yml');
          }
        } else {
          generated.push('.github/workflows/ci-pipeline.yml (dry-run)');
        }
      }

      if (all || options.gitlab) {
        const glFile = path.join(root, '.gitlab-ci.yml');
        if (!options.dryRun) {
          if (fs.existsSync(glFile) && !options.force) {
            skipped.push('.gitlab-ci.yml');
          } else {
            const content = `stages:
  - build
  - test
  - deploy

variables:
  NODE_VERSION: "20"

build:
  stage: build
  image: node:\${NODE_VERSION}
  script:
    - npm ci
    - npm run build --if-present
  cache:
    key: \${CI_COMMIT_REF_SLUG}
    paths:
      - node_modules/

test:
  stage: test
  image: node:\${NODE_VERSION}
  script:
    - npm test --if-present
  cache:
    key: \${CI_COMMIT_REF_SLUG}
    paths:
      - node_modules/
`;
            fs.writeFileSync(glFile, content);
            generated.push('.gitlab-ci.yml');
          }
        } else {
          generated.push('.gitlab-ci.yml (dry-run)');
        }
      }

      if (all || options.docker) {
        const dockerFile = path.join(root, 'Dockerfile');
        if (!options.dryRun) {
          if (fs.existsSync(dockerFile) && !options.force) {
            skipped.push('Dockerfile');
          } else {
            fs.writeFileSync(dockerFile, dockerfileContent());
            generated.push('Dockerfile');
          }
        } else {
          generated.push('Dockerfile (dry-run)');
        }
      }

      if (all || options.k8s) {
        const k8sDir = path.join(root, 'k8s');
        const projectName = path.basename(root);
        if (!options.dryRun) {
          const k8sFile = path.join(k8sDir, 'deployment.yaml');
          if (fs.existsSync(k8sFile) && !options.force) {
            skipped.push('k8s/deployment.yaml');
          } else {
            fs.mkdirSync(k8sDir, { recursive: true });
            fs.writeFileSync(k8sFile, k8sDeploymentContent(projectName));
            generated.push('k8s/deployment.yaml');
          }
        } else {
          generated.push('k8s/deployment.yaml (dry-run)');
        }
      }

      for (const g of generated) printResult('Gerado', true, g);
      for (const s of skipped) printResult('Pulado', false, `${s} (use --force)`);

      const ok = generated.length > 0;
      finish({
        checkpoint: 'pipeline_generate',
        ok,
        status: ok ? 'passed' : 'failed',
        context_summary: ok
          ? `Gerado(s): ${generated.join(', ')}${skipped.length > 0 ? `. Pulado(s): ${skipped.join(', ')}` : ''}`
          : 'Nenhum arquivo gerado.',
        data: { generated, skipped },
      });
    });

  cmd
    .command('run')
    .description('Executa pipeline localmente (dry-run)')
    .argument('<workflow>', 'Nome do workflow')
    .action((workflow: string) => {
      printHeader(`Pipeline Run: ${workflow}`);
      printLine(`[DRY-RUN] Pipeline "${workflow}" executaria:`);
      printLine('  1. npm ci');
      printLine('  2. npm run build --if-present');
      printLine('  3. npm test --if-present');
      if (fs.existsSync(path.join(process.cwd(), 'Dockerfile'))) printLine('  4. docker build -t app .');
      printLine('');

      const pkgManager = detectPackageManager(process.cwd());
      const steps: string[] = [];
      let allPassed = true;

      try {
        const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';
        steps.push('install');
        execSync(`${npmBin} ci 2>&1`, { cwd: process.cwd(), stdio: 'pipe', timeout: 120000 });
        printResult('npm ci', true);
      } catch {
        printResult('npm ci', false);
        allPassed = false;
      }

      try {
        const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';
        steps.push('build');
        execSync(`${npmBin} run build --if-present 2>&1`, { cwd: process.cwd(), stdio: 'pipe', timeout: 120000 });
        printResult('Build', true);
      } catch {
        printResult('Build', false);
        allPassed = false;
      }

      finish({
        checkpoint: 'pipeline_run',
        ok: allPassed,
        status: allPassed ? 'passed' : 'failed',
        context_summary: allPassed ? `Pipeline "${workflow}" executou com sucesso` : `Pipeline "${workflow}" falhou`,
        data: { workflow, steps, allPassed },
      });
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { printHeader, printLine, printResult, finish } from "../utils/output";

const REPORTS_DIR = '.ai/reports';
const RETRO_DIR = '.ai/reports/retrospective';

interface RetroData {
  generatedAt: string;
  period: string;
  qualityGatesRun: number;
  qualityGatesPassed: number;
  violationsDetected: number;
  violationsFixed: number;
  avgFixTime: string;
  totalCommits: number;
  findings: string[];
  improvements: string[];
  previousReport?: string;
  trends?: {
    qualityGatesPassed: number[];
    violationsDetected: number[];
  };
}

function runGit(cwd: string, args: string): string {
  try {
    return execSync(`git ${args}`, { cwd, encoding: 'utf8', stdio: 'pipe' }).trim();
  } catch {
    return '';
  }
}

function countQualityGateRuns(root: string): { total: number; passed: number } {
  const ledgerPath = path.join(root, '.ai/reports/latest-sync-report.json');
  if (!fs.existsSync(ledgerPath)) return { total: 0, passed: 0 };
  try {
    const ledger = JSON.parse(fs.readFileSync(ledgerPath, 'utf8'));
    const entries = Array.isArray(ledger) ? ledger : ledger.entries || [];
    const verifyEntries = entries.filter((e: any) => e.command === 'verify' || e.checkpoint === 'verify');
    return {
      total: verifyEntries.length,
      passed: verifyEntries.filter((e: any) => e.status === 'passed' || e.ok === true).length,
    };
  } catch {
    return { total: 0, passed: 0 };
  }
}

function countPlaceholderViolations(root: string): number {
  const reportPath = path.join(root, '.ai/reports/placeholder-policy-report.json');
  if (!fs.existsSync(reportPath)) return 0;
  try {
    const report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));
    return report.findings?.length || 0;
  } catch {
    return 0;
  }
}

function getExistingRetros(root: string): string[] {
  const dir = path.join(root, RETRO_DIR);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter(f => f.endsWith('.md'))
    .sort()
    .reverse();
}

function loadRetro(root: string, file: string): RetroData | null {
  try {
    const content = fs.readFileSync(path.join(root, RETRO_DIR, file), 'utf8');
    const match = content.match(/^## Dados Brutos\s*\n\s*(\{.+?\})/ms);
    if (match) return JSON.parse(match[1]);
  } catch { /* ignore */ }
  return null;
}

function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
  return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`;
}

export function retrospectiveCommand(): Command {
  const cmd = new Command('retrospective')
    .description('Gera relatorio de retrospectiva pos-release');

  cmd
    .command('generate')
    .description('Gera relatorio de retrospectiva')
    .option('--since <tag>', 'Analisa periodo desde uma tag git')
    .option('--auto', 'Executa automaticamente apos git tag')
    .action((options) => {
      const root = process.cwd();
      const now = new Date().toISOString();
      const retrosDir = path.join(root, RETRO_DIR);
      fs.mkdirSync(retrosDir, { recursive: true });

      let period = 'all';
      let commits: string[] = [];
      let totalCommits = 0;

      if (options.since) {
        period = `since ${options.since}`;
        const log = runGit(root, `log ${options.since}..HEAD --oneline`);
        commits = log ? log.split('\n') : [];
        totalCommits = commits.length;
      } else {
        const lastTag = runGit(root, 'describe --tags --abbrev=0 2>/dev/null');
        if (lastTag) {
          period = `since ${lastTag}`;
          const log = runGit(root, `log ${lastTag}..HEAD --oneline`);
          commits = log ? log.split('\n') : [];
          totalCommits = commits.length;
        } else {
          const log = runGit(root, 'log --oneline -50');
          commits = log ? log.split('\n') : [];
          totalCommits = commits.length;
        }
      }

      const gates = countQualityGateRuns(root);
      const violations = countPlaceholderViolations(root);

      const recentRetros = getExistingRetros(root);
      const lastRetro = recentRetros.length > 0 ? loadRetro(root, recentRetros[0]) : null;

      let avgFixTime = 'N/A';
      if (totalCommits > 0) {
        const firstCommit = runGit(root, `log --reverse --format=%ct ${period === 'all' ? '' : period}`);
        const dates = firstCommit.split('\n').filter(Boolean).map(Number);
        if (dates.length >= 2) {
          const totalSeconds = dates[dates.length - 1] - dates[0];
          avgFixTime = formatDuration(Math.round(totalSeconds / dates.length));
        }
      }

      const trends: { qualityGatesPassed: number[]; violationsDetected: number[] } = {
        qualityGatesPassed: [gates.passed],
        violationsDetected: [violations],
      };
      if (lastRetro && lastRetro.trends) {
        trends.qualityGatesPassed = [...lastRetro.trends.qualityGatesPassed, gates.passed];
        trends.violationsDetected = [...lastRetro.trends.violationsDetected, violations];
      }

      const data: RetroData = {
        generatedAt: now,
        period,
        qualityGatesRun: gates.total,
        qualityGatesPassed: gates.passed,
        violationsDetected: violations,
        violationsFixed: 0,
        avgFixTime,
        totalCommits,
        findings: [],
        improvements: [],
        previousReport: recentRetros[0] || undefined,
        trends,
      };

      if (gates.total > 0) {
        const passRate = Math.round((gates.passed / gates.total) * 100);
        if (passRate >= 90) {
          data.findings.push('Alta taxa de aprovacao nos quality gates');
        } else {
          data.findings.push(`${100 - passRate}% dos quality gates falharam — revisar processo de verificacao`);
        }
      }

      if (violations > 0) {
        data.findings.push(`${violations} violacoes de placeholder detectadas`);
        data.improvements.push('Reduzir placeholders antes do commit (usar ai-devkit hook install)');
      }

      if (totalCommits === 0) {
        data.findings.push('Nenhum commit no periodo analisado');
      } else {
        data.findings.push(`${totalCommits} commits no periodo`);
      }

      const filename = `retro-${now.slice(0, 10)}.md`;
      const filePath = path.join(retrosDir, filename);

      const report = `# Relatorio de Retrospectiva

**Gerado em:** ${now}
**Periodo:** ${period}

## Resumo

| Metrica | Valor |
|---------|-------|
| Commits | ${totalCommits} |
| Quality gates executados | ${gates.total} |
| Quality gates aprovados | ${gates.passed} |
| Violacoes detectadas | ${violations} |
| Tempo medio por commit | ${avgFixTime} |

## O que funcionou
${data.findings.filter(f => !f.includes('falharam') && !f.includes('violaco') && !f.includes('Nenhum')).map(f => `- ${f}`).join('\n') || '- N/A'}

## O que falhou
${data.findings.filter(f => f.includes('falharam') || f.includes('violaco')).map(f => `- ${f}`).join('\n') || '- Nenhuma falha registrada'}

## Melhorias sugeridas
${data.improvements.map(i => `- ${i}`).join('\n') || '- Nenhuma sugestao no momento'}

## Tendencias
| Retrospectiva | Gates Aprovados | Violacoes |
|${trends.qualityGatesPassed.map((_, i) => `| Retro ${i + 1} | ${trends.qualityGatesPassed[i]} | ${trends.violationsDetected[i]}`).join(' |\n|')} |

## Dados Brutos
${JSON.stringify(data, null, 2)}
`;
      fs.writeFileSync(filePath, report);
      console.log(`[ai-devkit] Relatorio gerado: ${filePath}`);
    });

  cmd
    .command('list')
    .description('Lista relatorios de retrospectiva existentes')
    .action(() => {
      const root = process.cwd();
      const retros = getExistingRetros(root);
      if (retros.length === 0) {
        printLine('Nenhum relatorio de retrospectiva encontrado.');
        return;
      }
      printHeader('Retrospectivas');
      retros.forEach((r, i) => {
        const data = loadRetro(root, r);
        const summary = data ? ` (${data.qualityGatesPassed}/${data.qualityGatesRun} gates OK, ${data.totalCommits} commits)` : '';
        printLine(`${i + 1}. ${r}${summary}`);
      });
    });

  return cmd;
}

import { Command } from 'commander';
import { runReview } from '../utils/review/index';

export function reviewCommand(): Command {
  const cmd = new Command('review')
    .description('Execute adversarial reviews (anti-slop, regression, security, performance)')
    .option('--json', 'Output JSON')
    .option('--diff <file>', 'Review only diff against main (file-based)');

  function runner(checks: string[]) {
    return (opts: Record<string, unknown>) => {
      const cwd = process.cwd();
      const result = runReview(checks, cwd, !!opts.json);
      if (result.summary.critical > 0) process.exit(1);
    };
  }

  cmd.command('anti-slop').description('Detect boilerplate, dead code, duplication').action(runner(['anti-slop']));
  cmd.command('regression').description('Check for contract-breaking changes').action(runner(['regression']));
  cmd.command('security').description('Scan for exposed secrets, excessive permissions').action(runner(['security']));
  cmd.command('performance').description('Detect N+1 queries, inefficient loops').action(runner(['performance']));
  cmd.command('all').description('Run all 4 reviews in parallel').action(runner(['anti-slop', 'regression', 'security', 'performance']));

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { printLine, printResult } from "../utils/output";
import { listAvailablePacks, findPack, listInstalledPacks, installPack, uninstallPack, searchPacks } from '../rules/pack';

const ROOT = process.cwd();
const PACKS_DIR = '.ai/rule-packs';

function rulesListAction(options: { all?: boolean }): void {
  if (options.all) {
    const available = listAvailablePacks();
    if (available.length === 0) {
      printLine('Nenhum pacote disponivel.');
      return;
    }
    printLine(`Pacotes disponiveis (${available.length}):\n`);
    for (const p of available) {
      const tags = p.tags.join(', ');
      printLine(`  ${p.name} v${p.version}`);
      printLine(`    ${p.description || 'Sem descricao'}`);
      printLine(`    Tags: ${tags}`);
      printLine(`    Regras: ${p.rules.length}`);
      printLine('');
    }
    return;
  }

  const installed = listInstalledPacks(ROOT);
  if (installed.length === 0) {
    printLine('Nenhum pacote de regras instalado.');
    printLine('Use "rules list --all" para ver pacotes disponiveis.');
    return;
  }

  printLine(`Pacotes instalados (${installed.length}):\n`);
  for (const p of installed) {
    printLine(`  ${p.manifest.name} v${p.manifest.version}`);
    printLine(`    Regras: ${p.manifest.rules.length}`);
    printLine(`    Diretorio: ${path.relative(ROOT, p.dir)}`);
    printLine('');
  }
}

function rulesInstallAction(name: string): void {
  const pack = findPack(name);
  if (!pack) {
    printResult(`Pacote "${name}" nao encontrado. Use "rules list --all" para ver disponiveis.`, false);
    return;
  }

  const ok = installPack(ROOT, name);
  if (ok) {
    printResult(`Pacote "${name}" instalado em ${PACKS_DIR}/${name}/`, true);
    printLine(`  Regras instaladas: ${pack.rules.length}`);
    printLine(`  Edite os arquivos em ${PACKS_DIR}/${name}/rules.md para personalizar.`);
  } else {
    printResult(`Falha ao instalar pacote "${name}".`, false);
  }
}

function rulesUninstallAction(name: string): void {
  const ok = uninstallPack(ROOT, name);
  if (ok) {
    printResult(`Pacote "${name}" removido.`, true);
  } else {
    printResult(`Pacote "${name}" nao encontrado.`, false);
  }
}

function rulesSearchAction(query: string): void {
  const results = searchPacks(query);
  if (results.length === 0) {
    printLine(`Nenhum pacote encontrado para "${query}".`);
    return;
  }

  printLine(`Resultados para "${query}" (${results.length}):\n`);
  for (const p of results) {
    printLine(`  ${p.name} v${p.version}`);
    printLine(`    ${p.description || 'Sem descricao'}`);
    printLine(`    Tags: ${p.tags.join(', ')}`);
    printLine('');
  }
}

function rulesCreateAction(name: string): void {
  const packsDir = path.join(ROOT, PACKS_DIR);
  const packDir = path.join(packsDir, name);

  if (fs.existsSync(packDir)) {
    printResult(`Pacote "${name}" ja existe em ${PACKS_DIR}/${name}/.`, false);
    return;
  }

  fs.mkdirSync(packDir, { recursive: true });

  const manifest = {
    name,
    version: '1.0.0',
    description: `Rule pack ${name}`,
    tags: ['custom'],
    rules: [
      { id: 'CUSTOM-001', title: 'Minha Regra', description: 'Descricao da regra', severity: 'medium', target: 'laws.yaml' }
    ]
  };

  fs.writeFileSync(path.join(packDir, 'rule-pack.yaml'), YAML.stringify(manifest));
  fs.writeFileSync(path.join(packDir, 'rules.md'), `# Rule Pack: ${name}\n\n## laws.yaml\n- [CUSTOM-001] Minha Regra: Descricao da regra\n`);

  printResult(`Pacote "${name}" criado em ${PACKS_DIR}/${name}/`, true);
  printLine(`  Edite rule-pack.yaml para configurar`);
  printLine(`  Edite rules.md para adicionar o texto das regras`);
}

function rulesValidateAction(name?: string): void {
  const manifest = name ? findPack(name) : null;
  if (name && !manifest) {
    printResult(`Pacote "${name}" nao encontrado.`, false);
    return;
  }

  const packs = manifest
    ? [{ manifest, dir: '' }]
    : listInstalledPacks(ROOT);

  if (packs.length === 0) {
    printLine('Nenhum pacote para validar.');
    return;
  }

  for (const p of packs) {
    if (!p.manifest) continue;
    const m = p.manifest;
    const errors: string[] = [];

    if (!m.name) errors.push('name obrigatorio');
    if (!m.version) errors.push('version obrigatorio');
    if (!Array.isArray(m.rules)) errors.push('rules deve ser um array');
    else {
      for (let i = 0; i < m.rules.length; i++) {
        const r = m.rules[i];
        if (!r.id) errors.push(`rules[${i}]: id obrigatorio`);
        if (!r.title) errors.push(`rules[${i}]: title obrigatorio`);
      }
    }

    if (errors.length === 0) {
      printLine(`${m.name} v${m.version}: VALIDO (${m.rules.length} regras)`);
    } else {
      printResult(`${m.name}: INVALIDO — ${errors.join('; ')}`, false);
    }
  }
}

function rulesPublishAction(name: string): void {
  const pack = findPack(name);
  if (!pack) {
    printResult(`Pacote "${name}" nao encontrado no registro local.`, false);
    return;
  }

  printLine(`Preparando publicacao de "${name}" v${pack.version}...`);
  printLine(`  Regras: ${pack.rules.length}`);
  printLine(`  Tags: ${pack.tags.join(', ')}`);
  printLine(`  Nota: Publicacao remota via GitHub Releases sera implementada em versao futura.`);
  printLine(`  O manifesto do pacote foi validado e esta pronto para publicacao.`);
  printResult(`Pacote "${name}" preparado para publicacao. (dry-run)`, true);
}

export function rulesCommand(): Command {
  const cmd = new Command('rules')
    .description('Rule Marketplace — gerencia pacotes de regras');

  cmd
    .command('list')
    .description('Lista pacotes de regras instalados')
    .option('--all', 'Lista todos os pacotes disponiveis')
    .action(rulesListAction);

  cmd
    .command('install')
    .description('Instala pacote de regras')
    .argument('<name>', 'Nome do pacote')
    .action(rulesInstallAction);

  cmd
    .command('uninstall')
    .description('Remove pacote de regras')
    .argument('<name>', 'Nome do pacote')
    .action(rulesUninstallAction);

  cmd
    .command('search')
    .description('Busca pacotes por nome, descricao ou tag')
    .argument('<query>', 'Termo de busca')
    .action(rulesSearchAction);

  cmd
    .command('create')
    .description('Cria scaffold de novo rule pack')
    .argument('<name>', 'Nome do pacote')
    .action(rulesCreateAction);

  cmd
    .command('validate')
    .description('Valida integridade do pacote')
    .argument('[name]', 'Nome do pacote (opcional)')
    .action(rulesValidateAction);

  cmd
    .command('publish')
    .description('Prepara publicacao do pacote (dry-run)')
    .argument('<name>', 'Nome do pacote')
    .action(rulesPublishAction);

  return cmd;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import chokidar from "chokidar";
import yaml from "js-yaml";

export interface RuntimeHookConfig {
  enabled: boolean;
  watch_paths: string[];
  ignore_paths: string[];
  scanners: string[];
  action: "log" | "block";
  report_dir: string;
}

const HOOKS_DIR = ".ai/hooks";
const CONFIG_FILE = "runtime.yaml";
const REPORTS_DIR = ".ai/reports/runtime-hooks";

function getConfigPath(): string {
  return path.join(process.cwd(), HOOKS_DIR, CONFIG_FILE);
}

function ensureHooksDir(): void {
  const dir = path.join(process.cwd(), HOOKS_DIR);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function ensureReportsDir(): void {
  const dir = path.join(process.cwd(), REPORTS_DIR);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function getDefaultConfig(): RuntimeHookConfig {
  return {
    enabled: true,
    watch_paths: ["src/**/*", "packages/**/*"],
    ignore_paths: ["node_modules/**", "dist/**", "build/**", ".git/**"],
    scanners: ["check-placeholder-policy.js", "check-package-scripts.js"],
    action: "log",
    report_dir: REPORTS_DIR
  };
}

function loadConfig(): RuntimeHookConfig {
  const configPath = getConfigPath();
  if (!fs.existsSync(configPath)) {
    return getDefaultConfig();
  }

  try {
    const content = fs.readFileSync(configPath, "utf8");
    return yaml.load(content) as RuntimeHookConfig;
  } catch {
    return getDefaultConfig();
  }
}

function saveConfig(config: RuntimeHookConfig): void {
  ensureHooksDir();
  fs.writeFileSync(getConfigPath(), yaml.dump(config, { indent: 2 }));
}

interface ViolationEvent {
  timestamp: string;
  file: string;
  event: string;
  scanner: string;
  violation: string;
  blocked: boolean;
}

function logViolation(event: ViolationEvent): void {
  ensureReportsDir();
  const logFile = path.join(process.cwd(), REPORTS_DIR, "violations.jsonl");
  fs.appendFileSync(logFile, JSON.stringify(event) + "\n");
}

function runScanner(scanner: string, filePath: string): { passed: boolean; output: string } {
  const scannerPath = path.join(process.cwd(), ".ai/bin", scanner);

  if (!fs.existsSync(scannerPath)) {
    return { passed: true, output: `Scanner ${scanner} not found` };
  }

  const result = spawnSync("node", [scannerPath], {
    cwd: process.cwd(),
    encoding: "utf8",
    env: { ...process.env, AI_DEVKIT_STRICT_AUDIT: "1" }
  });

  return {
    passed: result.status === 0,
    output: result.stdout + result.stderr
  };
}

function handleFileChange(filePath: string, event: string, config: RuntimeHookConfig): void {
  console.log(`\n📝 File ${event}: ${filePath}`);

  const violations: ViolationEvent[] = [];

  config.scanners.forEach(scanner => {
    const result = runScanner(scanner, filePath);

    if (!result.passed) {
      const violation: ViolationEvent = {
        timestamp: new Date().toISOString(),
        file: filePath,
        event,
        scanner,
        violation: result.output.substring(0, 200),
        blocked: config.action === "block"
      };

      violations.push(violation);
      logViolation(violation);

      console.log(`  ❌ Violation detected by ${scanner}`);
      console.log(`     ${violation.violation.split("\n")[0]}`);
    } else {
      console.log(`  ✅ ${scanner} passed`);
    }
  });

  if (violations.length > 0 && config.action === "block") {
    console.log(`\n🚫 File change BLOCKED due to ${violations.length} violation(s)`);
  } else if (violations.length > 0) {
    console.log(`\n⚠️  ${violations.length} violation(s) logged (dry-run mode)`);
  } else {
    console.log(`  ✅ All scanners passed`);
  }
}

export function hooksCommand(): Command {
  const hooks = new Command("hooks")
    .description("Gerencia runtime hooks para interceptação de filesystem");

  hooks
    .command("init")
    .description("Inicializa configuração de runtime hooks")
    .action(() => {
      const config = getDefaultConfig();
      saveConfig(config);
      console.log("✅ Runtime hooks config initialized at .ai/hooks/runtime.yaml");
    });

  hooks
    .command("watch")
    .description("Inicia watcher de filesystem")
    .option("--dry-run", "Apenas loga violações sem bloquear")
    .action((options) => {
      const config = loadConfig();

      if (options.dryRun) {
        config.action = "log";
      }

      console.log("\n👁️  Starting runtime file watcher...\n");
      console.log(`Watch paths: ${config.watch_paths.join(", ")}`);
      console.log(`Ignore paths: ${config.ignore_paths.join(", ")}`);
      console.log(`Scanners: ${config.scanners.join(", ")}`);
      console.log(`Action: ${config.action}\n`);

      const watcher = chokidar.watch(config.watch_paths, {
        ignored: config.ignore_paths,
        persistent: true,
        ignoreInitial: true
      });

      watcher
        .on("add", (path) => handleFileChange(path, "add", config))
        .on("change", (path) => handleFileChange(path, "change", config))
        .on("unlink", (path) => handleFileChange(path, "unlink", config));

      console.log("✅ Watcher started. Press Ctrl+C to stop.\n");

      process.on("SIGINT", () => {
        console.log("\n\n🛑 Stopping watcher...");
        watcher.close();
        process.exit(0);
      });
    });

  hooks
    .command("status")
    .description("Exibe status do runtime hooks")
    .action(() => {
      const config = loadConfig();

      console.log("\n📊 Runtime Hooks Status:\n");
      console.log(`Enabled: ${config.enabled ? "Yes" : "No"}`);
      console.log(`Action: ${config.action}`);
      console.log(`Watch paths: ${config.watch_paths.length}`);
      console.log(`Ignore paths: ${config.ignore_paths.length}`);
      console.log(`Scanners: ${config.scanners.length}`);
      console.log(`Report dir: ${config.report_dir}`);

      const logFile = path.join(process.cwd(), REPORTS_DIR, "violations.jsonl");
      if (fs.existsSync(logFile)) {
        const content = fs.readFileSync(logFile, "utf8").trim();
        const lines = content.split("\n").filter(l => l);
        console.log(`\nTotal violations logged: ${lines.length}`);
      } else {
        console.log(`\nNo violations logged yet.`);
      }
    });

  hooks
    .command("logs")
    .description("Exibe logs de violações recentes")
    .option("-n, --limit <number>", "Número de entradas", "10")
    .action((options) => {
      const logFile = path.join(process.cwd(), REPORTS_DIR, "violations.jsonl");

      if (!fs.existsSync(logFile)) {
        console.log("No violations logged yet.");
        return;
      }

      const content = fs.readFileSync(logFile, "utf8").trim();
      const lines = content.split("\n").filter(l => l);
      const limit = parseInt(options.limit);
      const recent = lines.slice(-limit);

      console.log(`\n📋 Recent violations (${recent.length}):\n`);

      recent.forEach((line, index) => {
        const event: ViolationEvent = JSON.parse(line);
        console.log(`${index + 1}. [${event.timestamp}] ${event.file}`);
        console.log(`   Event: ${event.event}`);
        console.log(`   Scanner: ${event.scanner}`);
        console.log(`   Blocked: ${event.blocked ? "Yes" : "No"}`);
        console.log(`   Violation: ${event.violation.split("\n")[0]}`);
        console.log();
      });
    });

  return hooks;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";

export interface ScorecardCategory {
  name: string;
  weight: number;
  score: number;
  maxScore: number;
  items: ScorecardItem[];
}

export interface ScorecardItem {
  id: string;
  description: string;
  passed: boolean;
  weight: number;
}

export interface ScorecardResult {
  timestamp: string;
  overallScore: number;
  maturityLevel: "A" | "B" | "C" | "D";
  categories: ScorecardCategory[];
  recommendations: string[];
}

function exists(file: string): boolean {
  return fs.existsSync(path.join(process.cwd(), file));
}

function calculateCategoryScore(items: ScorecardItem[]): number {
  const totalWeight = items.reduce((sum, item) => sum + item.weight, 0);
  const earnedWeight = items
    .filter(item => item.passed)
    .reduce((sum, item) => sum + item.weight, 0);
  return totalWeight > 0 ? (earnedWeight / totalWeight) * 100 : 0;
}

function getMaturityLevel(score: number): "A" | "B" | "C" | "D" {
  if (score >= 90) return "A";
  if (score >= 70) return "B";
  if (score >= 50) return "C";
  return "D";
}

function evaluateSecurityCategory(): ScorecardCategory {
  const items: ScorecardItem[] = [
    {
      id: "SEC-001",
      description: "Política de segurança de agentes existe",
      passed: exists(".ai/security/agent-safety-policy.md"),
      weight: 3
    },
    {
      id: "SEC-002",
      description: "Política de valores sensíveis (ph-value-policy)",
      passed: exists(".ai/policies/ph-value-policy.yaml") || exists(".ai/security/ph-value-policy.yaml"),
      weight: 3
    },
    {
      id: "SEC-003",
      description: "Política de segurança de rede",
      passed: exists(".ai/security/network-security-policy.md") || exists(".ai/policies/network-security-policy.yaml"),
      weight: 2
    },
