function generateRecommendations(categories: ScorecardCategory[]): string[] {
  const recommendations: string[] = [];

  categories.forEach(category => {
    category.items.forEach(item => {
      if (!item.passed) {
        recommendations.push(`[${category.name}] ${item.description}`);
      }
    });
  });

  return recommendations.slice(0, 10);
}

function calculateOverallScore(categories: ScorecardCategory[]): number {
  const totalWeight = categories.reduce((sum, cat) => sum + cat.weight, 0);
  const weightedScore = categories.reduce(
    (sum, cat) => sum + (cat.score * cat.weight) / 100,
    0
  );
  return totalWeight > 0 ? (weightedScore / totalWeight) * 100 : 0;
}

export function computeScorecard(): ScorecardResult {
  const categories = [
    evaluateSecurityCategory(),
    evaluateQualityCategory(),
    evaluateArchitectureCategory(),
    evaluateDocumentationCategory()
  ];

  const overallScore = calculateOverallScore(categories);
  const maturityLevel = getMaturityLevel(overallScore);
  const recommendations = generateRecommendations(categories);

  return {
    timestamp: new Date().toISOString(),
    overallScore: Math.round(overallScore),
    maturityLevel,
    categories,
    recommendations
  };
}

function saveScorecardHistory(result: ScorecardResult): void {
  const historyDir = path.join(process.cwd(), ".ai/reports/scorecard");
  const historyFile = path.join(historyDir, "history.json");

  if (!fs.existsSync(historyDir)) {
    fs.mkdirSync(historyDir, { recursive: true });
  }

  let history: ScorecardResult[] = [];
  if (fs.existsSync(historyFile)) {
    try {
      history = JSON.parse(fs.readFileSync(historyFile, "utf8"));
    } catch {
      history = [];
    }
  }

  history.push(result);
  fs.writeFileSync(historyFile, JSON.stringify(history, null, 2));
}

