import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printLine, printResult } from "../utils/output";
import {
  createBaseline, loadBaseline, getCurrentRules, detectDowngrades
} from '../security/baseline';
import {
  evaluateFindings, logDowngradeAttempt, loadDowngradeLogs
} from '../security/detector';
import { checkBarriers, addRule, loadRules } from '../utils/security/barrier';

const ROOT = process.cwd();

function securityCheckAction(options: { force?: boolean; reason?: string }): void {
  const baseline = loadBaseline(ROOT);
  if (baseline.length === 0) {
    printLine('Nenhum baseline encontrado. Execute "security baseline" primeiro.');
    return;
  }

  const current = getCurrentRules(ROOT);
  const findings = detectDowngrades(baseline, current);
  const result = evaluateFindings(findings, !!options.force, options.reason);

  for (const f of findings) {
    const sev = f.severity === 'critical' ? '[CRITICAL]' : f.severity === 'high' ? '[HIGH]' : '[MEDIUM]';
    printLine(`  ${sev} ${f.file}: "${f.rule.slice(0, 80)}" (${f.action})`);
    logDowngradeAttempt(ROOT, f, options.reason);
  }

  printLine('');
  printLine(result.message);
  if (result.blocked) {
    process.exitCode = 1;
  }
}

function securityDiffAction(): void {
  const baseline = loadBaseline(ROOT);
  const current = getCurrentRules(ROOT);
  const findings = detectDowngrades(baseline, current);

  if (findings.length === 0) {
    printResult('Nenhuma diferenca detectada entre baseline e estado atual.', true);
    return;
  }

  printLine(`Diferencas de seguranca encontradas (${findings.length}):\n`);
  for (const f of findings) {
    const sev = f.severity === 'critical' ? '[CRITICAL]' : f.severity === 'high' ? '[HIGH]' : '[MEDIUM]';
    printLine(`  ${sev} ${f.file}`);
    printLine(`    Regra: "${f.rule.slice(0, 80)}"`);
    printLine(`    Acao: removida`);
    printLine('');
  }
}

function securityBaselineAction(): void {
  const entries = createBaseline(ROOT);
  const totalRules = entries.reduce((sum, e) => sum + e.rules.length, 0);
  printResult(`Baseline criada com ${entries.length} arquivo(s) e ${totalRules} regra(s).`, true);
  printLine(`  Arquivo: .ai/security/baseline.json`);

  for (const entry of entries) {
    const critical = entry.rules.filter(r => r.severity === 'critical').length;
    const high = entry.rules.filter(r => r.severity === 'high').length;
    printLine(`  ${entry.file}: ${entry.rules.length} regras (${critical} critical, ${high} high)`);
  }
}

function securityLogsAction(): void {
  const logs = loadDowngradeLogs(ROOT);
  if (logs.length === 0) {
    printLine('Nenhuma tentativa de downgrade registrada.');
    return;
  }

  printLine(`Tentativas de downgrade (${logs.length}):\n`);
  for (const entry of logs) {
    const e = entry as Record<string, unknown>;
    printLine(`  [${e.severity}] ${e.file}`);
    printLine(`    Regra: ${(e.rule as string || '').slice(0, 80)}`);
    printLine(`    Data: ${e.timestamp}`);
    printLine(`    Motivo: ${e.reason}`);
    printLine('');
  }
}

export function securityCommand(): Command {
  const cmd = new Command('security')
    .description('Seguranca — baseline, downgrade detection e bloqueio');

  cmd
    .command('check')
    .description('Verifica se regras de seguranca foram removidas')
    .option('--force', 'Bypassa bloqueio de regras criticas')
    .option('--reason <reason>', 'Motivo do bypass (obrigatorio com --force para regras critical)')
    .action(securityCheckAction);

  cmd
    .command('diff')
    .description('Mostra diferencas de regras de seguranca entre baseline e atual')
    .action(securityDiffAction);

  cmd
    .command('baseline')
    .description('Cria snapshot das regras de seguranca atuais')
    .action(securityBaselineAction);

  cmd
    .command('logs')
    .description('Exibe historico de tentativas de downgrade')
    .action(securityLogsAction);

  const barrier = cmd.command('barrier')
    .description('Barreiras de seguranca — protege arquivos de auth, secrets e schema');

  barrier.command('check')
    .description('Verifica se arquivos protegidos foram modificados')
    .option('--bypass <reason>', 'Justificativa para bypass')
    .action((opts: Record<string, unknown>) => {
      const cwd = process.cwd();
      const allFiles: string[] = [];
      function walk(dir: string) {
        try {
          for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
            const full = path.join(dir, e.name);
            if (e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules') walk(full);
            else if (e.isFile()) allFiles.push(path.relative(cwd, full));
          }
        } catch { }
      }
      walk(cwd);
      const result = checkBarriers(cwd, allFiles, opts.bypass as string);
      const rules = loadRules(cwd);

      console.log(`\n=== Barreiras de Seguranca ===`);
      console.log(`Regras: ${rules.length}`);
      console.log(`Arquivos escaneados: ${allFiles.length}`);
      console.log(`Arquivos bloqueados: ${result.blocked.length}`);
      console.log(`Avisos: ${result.warnings.length}`);
      if (result.bypass) console.log(`Bypass: ${result.bypass}`);

      if (result.blocked.length > 0) {
        console.log(`\nArquivos bloqueados:`);
        result.blocked.forEach(f => console.log(`  🔒 ${f}`));
      }
      if (result.warnings.length > 0) {
        console.log(`\nArquivos com aviso:`);
        result.warnings.forEach(f => console.log(`  ⚠️ ${f}`));
      }

      for (const r of rules) {
        const icon = r.severity === 'block' ? '🔒' : '⚠️';
        console.log(`  ${icon} ${r.pattern} — ${r.description}`);
      }

      if (result.blocked.length > 0 && !result.bypass) process.exit(1);
    });

  barrier.command('list')
    .description('Lista arquivos protegidos e regras')
    .action(() => {
      const cwd = process.cwd();
      const rules = loadRules(cwd);
      console.log(`\n=== Regras de Barreira (${rules.length}) ===\n`);
      for (const r of rules) {
        console.log(`  [${r.severity.toUpperCase()}] ${r.pattern}`);
        console.log(`    ${r.description}`);
      }
    });

  barrier.command('add <pattern>')
    .description('Adiciona novo padrao de protecao')
    .option('--severity <severity>', 'block ou warn', 'block')
    .option('--desc <description>', 'Descricao da regra', 'Protegido por barreira')
    .action((pattern: string, opts: Record<string, unknown>) => {
      addRule(process.cwd(), pattern, opts.severity as 'block' | 'warn', opts.desc as string);
      console.log(`Regra adicionada: [${opts.severity}] ${pattern} — ${opts.desc}`);
    });

  return cmd;
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import { printHeader, printLine, printResult, finish } from "../utils/output";

// ============================================================
// TASK-GAP-15: Snapshot de Estado Instantâneo
// ============================================================

interface SnapshotData {
  generated_at: string;
  project: {
    name: string;
    version: string;
    stack: string[];
    frameworks: string[];
  };
  health: {
    status: 'healthy' | 'degraded' | 'unhealthy';
    score: number;
    checks: number;
    passed: number;
    failed: number;
  };
  governance: {
    laws_exists: boolean;
    policies_count: number;
    agents_count: number;
    rules_count: number;
    compiled_targets: string[];
  };
  artifacts: {
    has_claude: boolean;
    has_cursor: boolean;
    has_copilot: boolean;
    has_windsurf: boolean;
    has_cline: boolean;
    has_gemini: boolean;
    has_continue: boolean;
    has_zed: boolean;
    has_amazon_q: boolean;
    has_codex: boolean;
  };
  drift: {
    status: 'synced' | 'drifted' | 'unknown';
    last_check: string | null;
  };
  last_session: {
    timestamp: string | null;
    mode: string | null;
    summary: string | null;
  };
  tasks: {
    total: number;
    completed: number;
    pending: number;
    in_progress: number;
  };
  memory: {
    decisions_count: number;
    knowledge_entries: number;
    traces_count: number;
  };
}

function fileExists(root: string, ...paths: string[]): boolean {
  return fs.existsSync(path.join(root, ...paths));
}

function readJsonSafe(root: string, ...paths: string[]): Record<string, unknown> {
  const fullPath = path.join(root, ...paths);
  if (!fs.existsSync(fullPath)) return {};
  try { return JSON.parse(fs.readFileSync(fullPath, 'utf8')); }
  catch { return {}; }
}

function countFiles(dir: string, pattern?: RegExp): number {
  if (!fs.existsSync(dir)) return 0;
  try {
    const files = fs.readdirSync(dir, { recursive: true });
    if (pattern) return files.filter(f => pattern.test(String(f))).length;
    return files.length;
  } catch {
    return 0;
  }
}

function countLines(file: string): number {
  if (!fs.existsSync(file)) return 0;
  try {
    return fs.readFileSync(file, 'utf8').split('\n').filter(l => l.trim()).length;
  } catch {
    return 0;
  }
}

function detectStack(root: string): { languages: string[]; frameworks: string[] } {
  const languages: string[] = [];
  const frameworks: string[] = [];

  if (fileExists(root, 'package.json')) {
    languages.push('nodejs');
    try {
      const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
      const deps = { ...pkg.dependencies, ...pkg.devDependencies };
      if (deps.next) frameworks.push('nextjs');
      if (deps['@nestjs/core']) frameworks.push('nestjs');
      if (deps.express) frameworks.push('express');
      if (deps.fastify) frameworks.push('fastify');
      if (deps.react) frameworks.push('react');
    } catch {}
  }
  if (fileExists(root, 'pyproject.toml') || fileExists(root, 'requirements.txt')) {
    languages.push('python');
    if (fileExists(root, 'pyproject.toml')) {
      try {
        const content = fs.readFileSync(path.join(root, 'pyproject.toml'), 'utf8');
        if (content.includes('fastapi')) frameworks.push('fastapi');
        if (content.includes('django')) frameworks.push('django');
        if (content.includes('flask')) frameworks.push('flask');
      } catch {}
    }
  }
  if (fileExists(root, 'go.mod')) languages.push('go');
  if (fileExists(root, 'Cargo.toml')) languages.push('rust');

  return { languages, frameworks };
}

function getHealthScore(root: string): { score: number; checks: number; passed: number; failed: number } {
  let checks = 0;
  let passed = 0;

  // Check 1: package.json exists
  checks++; if (fileExists(root, 'package.json')) passed++;
  // Check 2: tsconfig.json exists
  checks++; if (fileExists(root, 'tsconfig.json')) passed++;
  // Check 3: .ai directory exists
  checks++; if (fileExists(root, '.ai')) passed++;
  // Check 4: laws.yaml exists
  checks++; if (fileExists(root, '.ai', 'laws.yaml')) passed++;
  // Check 5: README.md exists
  checks++; if (fileExists(root, 'README.md')) passed++;
  // Check 6: .gitignore exists
  checks++; if (fileExists(root, '.gitignore')) passed++;
  // Check 7: src directory exists
  checks++; if (fileExists(root, 'src')) passed++;
  // Check 8: node_modules exists (deps installed)
  checks++; if (fileExists(root, 'node_modules')) passed++;

  const score = checks > 0 ? Math.round((passed / checks) * 100) : 0;
  return { score, checks, passed, failed: checks - passed };
}

export function snapshotCommand(): Command {
  const cmd = new Command('snapshot')
    .description('Gera snapshot instantaneo do estado do projeto (TASK-GAP-15)');

  cmd
    .command('generate')
    .description('Gera snapshot JSON completo do projeto em <1s')
    .option('--save', 'Salva snapshot em .ai/reports/snapshot.json', false)
    .option('--pretty', 'Exibe saida formatada', true)
    .action((options) => {
      const root = process.cwd();
      const startTime = Date.now();

      const stack = detectStack(root);
      const health = getHealthScore(root);

      const snapshot: SnapshotData = {
        generated_at: new Date().toISOString(),
        project: {
          name: path.basename(root),
          version: (() => {
            try {
              const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
              return pkg.version || '0.0.0';
            } catch { return '0.0.0'; }
          })(),
          stack: stack.languages,
          frameworks: stack.frameworks,
        },
        health: {
          status: health.score >= 80 ? 'healthy' : health.score >= 50 ? 'degraded' : 'unhealthy',
          score: health.score,
          checks: health.checks,
          passed: health.passed,
          failed: health.failed,
        },
        governance: {
          laws_exists: fileExists(root, '.ai', 'laws.yaml'),
          policies_count: countFiles(path.join(root, '.ai', 'policies'), /\.(yaml|yml)$/),
          agents_count: (() => {
            const agentsDir = path.join(root, '.ai', 'agents');
            if (!fs.existsSync(agentsDir)) return 0;
            return fs.readdirSync(agentsDir).filter(f => f.endsWith('.yaml') || f.endsWith('.yml')).length;
          })(),
          rules_count: countLines(path.join(root, '.ai', 'laws.yaml')),
          compiled_targets: [
            fileExists(root, 'CLAUDE.md') && 'claude',
            fileExists(root, '.cursor', 'rules', 'ai-devkit.mdc') && 'cursor',
            fileExists(root, '.github', 'copilot-instructions.md') && 'copilot',
            fileExists(root, '.windsurf', 'rules', 'governance.md') && 'windsurf',
            fileExists(root, '.clinerules') && 'cline',
            fileExists(root, 'GEMINI.md') && 'gemini',
            fileExists(root, '.continuerules') && 'continue',
            fileExists(root, '.rules') && 'zed',
            fileExists(root, '.amazonq', 'rules', 'governance.md') && 'amazon-q',
            fileExists(root, 'AGENTS.md') && 'codex',
          ].filter(Boolean) as string[],
        },
        artifacts: {
          has_claude: fileExists(root, 'CLAUDE.md'),
          has_cursor: fileExists(root, '.cursor', 'rules', 'ai-devkit.mdc'),
          has_copilot: fileExists(root, '.github', 'copilot-instructions.md'),
          has_windsurf: fileExists(root, '.windsurf', 'rules', 'governance.md'),
          has_cline: fileExists(root, '.clinerules'),
          has_gemini: fileExists(root, 'GEMINI.md'),
          has_continue: fileExists(root, '.continuerules'),
          has_zed: fileExists(root, '.rules'),
          has_amazon_q: fileExists(root, '.amazonq', 'rules', 'governance.md'),
          has_codex: fileExists(root, 'AGENTS.md'),
        },
        drift: {
          status: (() => {
            const driftDir = path.join(root, '.ai', 'reports', 'drift');
            if (!fs.existsSync(driftDir)) return 'unknown';
            const files = fs.readdirSync(driftDir).filter(f => f.endsWith('.json'));
            if (files.length === 0) return 'unknown';
            const lastReport = readJsonSafe(root, '.ai', 'reports', 'drift', files[files.length - 1]);
            return (lastReport as any)?.drifted ? 'drifted' : 'synced';
          })(),
          last_check: (() => {
            const driftDir = path.join(root, '.ai', 'reports', 'drift');
            if (!fs.existsSync(driftDir)) return null;
            const files = fs.readdirSync(driftDir).filter(f => f.endsWith('.json'));
            if (files.length === 0) return null;
            return files[files.length - 1].replace('.json', '');
          })(),
        },
        last_session: (() => {
          const sessionFile = path.join(root, '.ai', 'session-mode.json');
          if (!fs.existsSync(sessionFile)) return { timestamp: null, mode: null, summary: null };
          try {
            const session = JSON.parse(fs.readFileSync(sessionFile, 'utf8'));
            return {
              timestamp: session.timestamp || null,
              mode: session.mode || null,
              summary: session.summary || null,
            };
          } catch { return { timestamp: null, mode: null, summary: null }; }
        })(),
        tasks: (() => {
          const tasksDir = path.join(root, '.ai', 'tasks');
          if (!fs.existsSync(tasksDir)) return { total: 0, completed: 0, pending: 0, in_progress: 0 };
          const files = fs.readdirSync(tasksDir).filter(f => f.endsWith('.md'));
          let total = 0, completed = 0, pending = 0, inProgress = 0;
          for (const file of files) {
            try {
              const content = fs.readFileSync(path.join(tasksDir, file), 'utf8');
              const tasks = content.match(/- \[([ x~])\]/g) || [];
              for (const t of tasks) {
                total++;
                if (t === '- [x]') completed++;
                else if (t === '- [~]') inProgress++;
                else pending++;
              }
            } catch {}
          }
          return { total, completed, pending, in_progress: inProgress };
        })(),
        memory: {
          decisions_count: countLines(path.join(root, '.ai', 'memory', 'decisions-log.md')),
          knowledge_entries: (() => {
            const kbFile = path.join(root, '.ai', 'memory', 'knowledge-base.json');
            if (!fs.existsSync(kbFile)) return 0;
            try {
              const kb = JSON.parse(fs.readFileSync(kbFile, 'utf8'));
              return Array.isArray(kb) ? kb.length : 0;
            } catch { return 0; }
          })(),
          traces_count: (() => {
            const tracesFile = path.join(root, '.ai', 'reports', 'observability', 'traces.jsonl');
            if (!fs.existsSync(tracesFile)) return 0;
            return fs.readFileSync(tracesFile, 'utf8').split('\n').filter(l => l.trim()).length;
          })(),
        },
      };

      const elapsed = Date.now() - startTime;

      if (options.save) {
        const snapshotDir = path.join(root, '.ai', 'reports');
        fs.mkdirSync(snapshotDir, { recursive: true });
        const snapshotPath = path.join(snapshotDir, 'snapshot.json');
        fs.writeFileSync(snapshotPath, JSON.stringify(snapshot, null, 2));
        printLine(`Snapshot saved to: ${snapshotPath}`);
      }

      if (options.pretty) {
        printHeader(`📸 Snapshot — ${snapshot.project.name} v${snapshot.project.version}`);
        printLine(`Generated in ${elapsed}ms`);
        printLine('');
        printLine(`🏥 Health: ${snapshot.health.score}/100 (${snapshot.health.status})`);
        printLine(`📦 Stack: ${snapshot.project.stack.join(', ') || 'unknown'}`);
        printLine(`🔧 Frameworks: ${snapshot.project.frameworks.join(', ') || 'none'}`);
        printLine(`📋 Governance: ${snapshot.governance.compiled_targets.length}/${snapshot.governance.compiled_targets.length} targets compiled`);
        printLine(`📝 Tasks: ${snapshot.tasks.completed}/${snapshot.tasks.total} completed`);
        printLine(`🧠 Memory: ${snapshot.memory.decisions_count} decisions, ${snapshot.memory.knowledge_entries} knowledge entries`);
        printLine(`🔄 Drift: ${snapshot.drift.status}`);
        printLine(`💻 Last session: ${snapshot.last_session.mode || 'N/A'}`);
      }

      finish({
        checkpoint: 'snapshot',
        ok: true,
        status: 'passed',
        context_summary: `Snapshot generated in ${elapsed}ms — Health: ${snapshot.health.score}/100`,
        data: snapshot as unknown as Record<string, unknown>,
      });
    });

  cmd
    .command('status')
    .description('Exibe resumo rapido do snapshot (sem gerar arquivo)')
    .action(() => {
      const root = process.cwd();
      const health = getHealthScore(root);
      const stack = detectStack(root);

      printHeader('📸 Quick Status');
      printLine(`Project: ${path.basename(root)}`);
      printLine(`Health: ${health.score}/100 (${health.passed}/${health.checks} checks passed)`);
      printLine(`Stack: ${stack.languages.join(', ') || 'unknown'}`);
      printLine(`Frameworks: ${stack.frameworks.join(', ') || 'none'}`);
      printLine('');
      printLine('Run `ai-devkit snapshot generate --save` for full snapshot');

      finish({
        checkpoint: 'snapshot_status',
        ok: true,
        status: 'passed',
        context_summary: `Quick status: ${health.score}/100`,
        data: { health, stack },
      });
    });

  return cmd;
}

import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import { REQUIRED_FILE_GROUPS } from "../core/health/required-files";
import { printHeader, printLine, printSummary, finish } from "../utils/output";
import { detectStack } from "./detect";

type StatusArea = {
  id: string;
  label: string;
  score: number;
  findings: string[];
};

export type StatusReport = {
  areas: StatusArea[];
  finalHealth: number;
  belowRecommended: boolean;
};

function projectPath(filePath: string): string {
  return path.join(process.cwd(), filePath);
}

function exists(filePath: string): boolean {
  return fs.existsSync(projectPath(filePath));
}

function daysSinceModified(filePath: string): number | null {
  const fullPath = projectPath(filePath);
  if (!fs.existsSync(fullPath)) return null;
  const stat = fs.statSync(fullPath);
  const diff = Date.now() - stat.mtimeMs;
  return Math.floor(diff / (1000 * 60 * 60 * 24));
}

export function computeStatus(): StatusReport {
  const areas: StatusArea[] = [];
  let totalScore = 0;

  for (const group of REQUIRED_FILE_GROUPS) {
    let categoryScore = 100;
    const findings: string[] = [];

    for (const file of group.required) {
      if (!exists(file)) {
        categoryScore -= (100 / group.required.length);
        findings.push(`Ausente: ${file}`);
      } else {
        findings.push(`OK: ${file}`);
      }
    }

    if (group.id === "context") {
      const age = daysSinceModified(".ai/context/ai-handoff.md");
      if (age !== null) {
        if (age > 14) categoryScore -= 30;
        findings.push(`Idade do Handoff: ${age} dia(s)`);
      }
    }

    const finalScore = Math.max(0, Math.round(categoryScore));
    areas.push({ id: group.id, label: group.label, score: finalScore, findings });
    totalScore += finalScore;
  }

  const finalHealth = Math.round(totalScore / REQUIRED_FILE_GROUPS.length);
  return { areas, finalHealth, belowRecommended: finalHealth < 85 };
}

export function statusCommand(): Command {
  return new Command("status")
    .description("Audita a saúde do projeto atual")
    .action(() => {
      const { areas, finalHealth, belowRecommended } = computeStatus();
      const stack = detectStack();

      printHeader("AI DevKit Project Status");
      printLine(`Stack: ${stack.languages.join(', ') || 'nao detectada'}`);
      if (stack.frameworks.length) printLine(`Frameworks: ${stack.frameworks.join(', ')}`);
      printLine('');

      for (const area of areas) {
        printSummary(area.score, 100, area.label);
        area.findings.forEach(f => printLine(`   - ${f}`));
      }

      printLine(`\nProject Health: ${finalHealth}/100\n`);
      const ok = !belowRecommended;
      finish({
        checkpoint: "status",
        ok,
        status: ok ? "passed" : "failed",
        context_summary: ok
          ? "Projeto em bom estado."
          : "Projeto abaixo do nível recomendado de saúde.",
        data: {
          areas: areas.map(a => ({ id: a.id, label: a.label, score: a.score, findings: a.findings })),
          finalHealth,
          stack,
        },
      });
    });
}

import { Command } from 'commander';
import { printHeader, printLine, printResult, finish } from "../utils/output";

// ============================================================
// TASK-GAP-13: Streaming Architecture (SSE/WebSocket)
// ============================================================

export function streamCommand(): Command {
  const cmd = new Command('stream')
    .description('Streaming Architecture (SSE/WebSocket)');

  cmd
    .command('sse')
    .description('Inicia um servidor SSE para streaming de eventos')
    .option('--port <port>', 'Porta do servidor SSE', '3001')
    .action((options) => {
      const port = parseInt(options.port, 10);
      printHeader('SSE Stream Server');
      printLine(`Starting SSE server on port ${port}...`);
      printLine('');
      printLine('SSE endpoints:');
      printLine(`  GET http://localhost:${port}/events`);
      printLine(`  POST http://localhost:${port}/emit`);
      printLine('');
      printLine('To emit an event:');
      printLine(`  curl -X POST http://localhost:${port}/emit \\`);
      printLine(`    -H "Content-Type: application/json" \\`);
      printLine(`    -d '{"event":"ai:response","data":{"text":"Hello"}}'`);
      printLine('');
      printLine('To consume events:');
      printLine(`  curl -N http://localhost:${port}/events`);
      printLine('');
      printLine('Note: Full SSE server requires a running Node.js process.');
      printLine('Use the --detach flag to run in background.');

      finish({
        checkpoint: 'stream_sse',
        ok: true,
        status: 'passed',
        context_summary: `SSE server configured on port ${port}`,
        data: { port, protocol: 'SSE', endpoints: [`/events`, `/emit`] },
      });
    });

  cmd
    .command('websocket')
    .description('Inicia um servidor WebSocket para streaming bidirecional')
    .option('--port <port>', 'Porta do servidor WebSocket', '3002')
    .action((options) => {
      const port = parseInt(options.port, 10);
      printHeader('WebSocket Stream Server');
      printLine(`Starting WebSocket server on port ${port}...`);
      printLine('');
      printLine('WebSocket endpoint:');
      printLine(`  ws://localhost:${port}`);
      printLine('');
      printLine('To connect:');
      printLine(`  wscat -c ws://localhost:${port}`);
      printLine('');
      printLine('Message types:');
      printLine('  { "type": "ping" } → { "type": "pong" }');
      printLine('  { "type": "subscribe", "channel": "ai:events" }');
      printLine('  { "type": "unsubscribe", "channel": "ai:events" }');
      printLine('');
      printLine('Note: Full WebSocket server requires a running Node.js process.');

      finish({
        checkpoint: 'stream_websocket',
        ok: true,
        status: 'passed',
        context_summary: `WebSocket server configured on port ${port}`,
        data: { port, protocol: 'WebSocket', endpoint: `ws://localhost:${port}` },
      });
    });

  cmd
    .command('emit')
    .description('Envia um evento via streaming (simulado)')
    .requiredOption('--event <event>', 'Nome do evento (ex: ai:response, ai:error)')
    .requiredOption('--data <json>', 'Dados do evento em JSON')
    .option('--protocol <protocol>', 'Protocolo (sse, websocket)', 'sse')
    .action((options) => {
      let data: Record<string, unknown>;
      try {
        data = JSON.parse(options.data);
      } catch {
        printResult('emit', false, 'Dados JSON invalidos');
        finish({
          checkpoint: 'stream_emit',
          ok: false,
          status: 'failed',
          context_summary: 'Invalid JSON data',
        });
        return;
      }

      const event = {
        event: options.event,
        data,
        timestamp: new Date().toISOString(),
        protocol: options.protocol,
      };

      printHeader(`Stream Event: ${options.event}`);
      printLine(`Protocol: ${options.protocol}`);
      printLine(`Timestamp: ${event.timestamp}`);
      printLine(`Data: ${JSON.stringify(data, null, 2)}`);
      printLine('');
      printLine('Event emitted successfully (simulated).');
      printLine('For real streaming, start the server with:');
      printLine(`  ai-devkit stream ${options.protocol} --port 3001`);

      finish({
        checkpoint: 'stream_emit',
        ok: true,
        status: 'passed',
        context_summary: `Emitted event: ${options.event}`,
        data: event,
      });
    });

  cmd
    .command('status')
    .description('Verifica o status dos servidores de streaming')
    .action(() => {
      printHeader('Streaming Status');
      printLine('SSE Server:      ⚪ Not running (start with `ai-devkit stream sse`)');
      printLine('WebSocket Server: ⚪ Not running (start with `ai-devkit stream websocket`)');
      printLine('');
      printLine('To start a server:');
      printLine('  ai-devkit stream sse --port 3001');
      printLine('  ai-devkit stream websocket --port 3002');

      finish({
        checkpoint: 'stream_status',
        ok: true,
        status: 'passed',
        context_summary: 'Streaming servers status checked',
        data: { sse: { running: false }, websocket: { running: false } },
      });
    });

  return cmd;
}

import { Command } from 'commander';
import { scan, generateSbom, audit, verifyPackage, printScanReport } from '../utils/supply-chain/index';
import fs from 'node:fs';
import path from 'node:path';

export function supplyChainCommand(): Command {
  const cmd = new Command('supply-chain')
    .description('Supply chain security: CVE scanning, SBOM generation, package verification');

  cmd.command('scan')
    .description('Scan dependencies for CVEs')
    .option('--ci', 'Exit with code 1 on critical vulnerabilities')
    .option('--json', 'JSON output')
    .action((opts: Record<string, unknown>) => {
      const cwd = process.cwd();
      const result = scan(cwd);
      printScanReport(result, cwd, !!opts.json);
      if (opts.ci && result.summary.critical > 0) process.exit(1);
    });

  cmd.command('sbom')
    .description('Generate Software Bill of Materials (CycloneDX)')
    .action(() => {
      const cwd = process.cwd();
      const sbom = generateSbom(cwd);
      const outPath = path.join(cwd, 'sbom.json');
      fs.writeFileSync(outPath, JSON.stringify(sbom, null, 2), 'utf-8');
      console.log(`SBOM gerado: ${path.relative(cwd, outPath)}`);
      console.log(`Componentes: ${(sbom.components as any[]).length}`);
    });

  cmd.command('audit')
    .description('Compare SBOM against baseline')
    .option('--baseline <path>', 'Path to baseline SBOM')
    .action((opts: Record<string, unknown>) => {
      const cwd = process.cwd();
      const result = scan(cwd);
      const diff = audit(result.entries, opts.baseline as string);
      if (diff.changed) {
        console.log('Mudancas detectadas em relacao ao baseline:');
        if (diff.added.length > 0) console.log(`  Novas vulnerabilidades: ${diff.added.length}`);
        if (diff.removed.length > 0) console.log(`  Removidas: ${diff.removed.length}`);
      } else {
        console.log('Nenhuma mudanca em relacao ao baseline.');
      }
    });

  cmd.command('verify <package>')
    .description('Verify package integrity')
    .action((pkg: string) => {
      const cwd = process.cwd();
      const result = verifyPackage(pkg, cwd);
      console.log(`Pacote: ${pkg}`);
      console.log(`Verificado: ${result.verified}`);
      if (result.integrity) console.log(`Integridade: ${result.integrity}`);
      if (result.error) console.error(`Erro: ${result.error}`);
    });

  return cmd;
}

