import { Command } from "commander";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

export interface TimelineEntry {
  id: string;
  timestamp: string;
  event_type: string;
  actor: string;
  payload: Record<string, unknown>;
  prev_hash: string;
  hash: string;
}

const TIMELINE_DIR = ".ai/audit";
const TIMELINE_FILE = "timeline.jsonl";

function getTimelinePath(): string {
  return path.join(process.cwd(), TIMELINE_DIR, TIMELINE_FILE);
}

function ensureTimelineDir(): void {
  const dir = path.join(process.cwd(), TIMELINE_DIR);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function computeHash(content: string): string {
  return crypto.createHash("sha256").update(content).digest("hex");
}

function getLastEntry(): TimelineEntry | null {
  const timelinePath = getTimelinePath();
  if (!fs.existsSync(timelinePath)) {
    return null;
  }

  const content = fs.readFileSync(timelinePath, "utf8").trim();
  if (!content) {
    return null;
  }

  const lines = content.split("\n");
  const lastLine = lines[lines.length - 1];
  return JSON.parse(lastLine);
}

function appendEntry(entry: TimelineEntry): void {
  ensureTimelineDir();
  const timelinePath = getTimelinePath();
  fs.appendFileSync(timelinePath, JSON.stringify(entry) + "\n");
}

export function logEvent(
  eventType: string,
  actor: string,
  payload: Record<string, unknown>
): TimelineEntry {
  const lastEntry = getLastEntry();
  const prevHash = lastEntry ? lastEntry.hash : "0".repeat(64);

  const entry: TimelineEntry = {
    id: crypto.randomUUID(),
    timestamp: new Date().toISOString(),
    event_type: eventType,
    actor,
    payload,
    prev_hash: prevHash,
    hash: ""
  };

  const hashContent = JSON.stringify({
    id: entry.id,
    timestamp: entry.timestamp,
    event_type: entry.event_type,
    actor: entry.actor,
    payload: entry.payload,
    prev_hash: entry.prev_hash
  });

  entry.hash = computeHash(hashContent);
  appendEntry(entry);

  return entry;
}

export function verifyTimeline(): {
  valid: boolean;
  brokenAt: number;
  totalEntries: number;
} {
  const timelinePath = getTimelinePath();
  if (!fs.existsSync(timelinePath)) {
    return { valid: true, brokenAt: -1, totalEntries: 0 };
  }

  const content = fs.readFileSync(timelinePath, "utf8").trim();
  if (!content) {
    return { valid: true, brokenAt: -1, totalEntries: 0 };
  }

  const lines = content.split("\n");
  let prevHash = "0".repeat(64);

  for (let i = 0; i < lines.length; i++) {
    const entry: TimelineEntry = JSON.parse(lines[i]);

    if (entry.prev_hash !== prevHash) {
      return { valid: false, brokenAt: i, totalEntries: lines.length };
    }

    const hashContent = JSON.stringify({
      id: entry.id,
      timestamp: entry.timestamp,
      event_type: entry.event_type,
      actor: entry.actor,
      payload: entry.payload,
      prev_hash: entry.prev_hash
    });

    const expectedHash = computeHash(hashContent);
    if (entry.hash !== expectedHash) {
      return { valid: false, brokenAt: i, totalEntries: lines.length };
    }

    prevHash = entry.hash;
  }

  return { valid: true, brokenAt: -1, totalEntries: lines.length };
}

export function searchTimeline(
  eventType?: string,
  since?: string
): TimelineEntry[] {
  const timelinePath = getTimelinePath();
  if (!fs.existsSync(timelinePath)) {
    return [];
  }

  const content = fs.readFileSync(timelinePath, "utf8").trim();
  if (!content) {
    return [];
  }

  const lines = content.split("\n");
  let entries: TimelineEntry[] = lines.map(line => JSON.parse(line));

  if (eventType) {
    entries = entries.filter(e => e.event_type === eventType);
  }

  if (since) {
    const sinceDate = new Date(since);
    entries = entries.filter(e => new Date(e.timestamp) >= sinceDate);
  }

  return entries;
}

export function exportTimeline(): TimelineEntry[] {
  const timelinePath = getTimelinePath();
  if (!fs.existsSync(timelinePath)) {
    return [];
  }

  const content = fs.readFileSync(timelinePath, "utf8").trim();
  if (!content) {
    return [];
  }

  return content.split("\n").map(line => JSON.parse(line));
}

export function timelineCommand(): Command {
  const timeline = new Command("timeline")
    .description("Gerencia audit timeline append-only com encadeamento criptográfico");

  timeline
    .command("log")
    .description("Registra evento na timeline")
    .requiredOption("-t, --type <type>", "Tipo do evento")
    .requiredOption("-a, --actor <actor>", "Ator responsável")
    .option("-p, --payload <json>", "Payload em JSON", "{}")
    .action((options) => {
      try {
        const payload = JSON.parse(options.payload);
        const entry = logEvent(options.type, options.actor, payload);
        console.log("✅ Evento registrado na timeline:");
        console.log(JSON.stringify(entry, null, 2));
      } catch (e) {
        console.error("❌ Erro ao registrar evento:", e);
        process.exit(1);
      }
    });

  timeline
    .command("verify")
    .description("Valida integridade da cadeia de hashes")
    .action(() => {
      console.log("\n🔐 Verificando integridade da Audit Timeline...\n");
      const result = verifyTimeline();

      if (result.totalEntries === 0) {
        console.log("📭 Timeline vazia. Nenhum evento registrado.");
        return;
      }

      if (result.valid) {
        console.log(`✅ Timeline íntegra. Total de eventos: ${result.totalEntries}`);
      } else {
        console.error(`❌ ALERTA: Adulteração detectada na entrada ${result.brokenAt + 1}.`);
        console.error("A cadeia de hashes foi quebrada. A timeline pode ter sido modificada.");
        process.exit(1);
      }
    });

  timeline
    .command("search")
    .description("Busca eventos na timeline")
    .option("-t, --type <type>", "Filtrar por tipo de evento")
    .option("-s, --since <date>", "Filtrar eventos desde data (ISO 8601)")
    .option("--json", "Retorna resultado em JSON")
    .action((options) => {
      const entries = searchTimeline(options.type, options.since);

      if (entries.length === 0) {
        console.log("Nenhum evento encontrado.");
        return;
      }

      if (options.json) {
        console.log(JSON.stringify(entries, null, 2));
      } else {
        console.log(`\n📋 Eventos encontrados: ${entries.length}\n`);
        entries.forEach((entry, index) => {
          console.log(`${index + 1}. [${entry.timestamp}] ${entry.event_type}`);
          console.log(`   Ator: ${entry.actor}`);
          console.log(`   Payload: ${JSON.stringify(entry.payload)}`);
          console.log();
        });
      }
    });

  timeline
    .command("export")
    .description("Exporta timeline completa em formato JSON")
    .action(() => {
      const entries = exportTimeline();
      console.log(JSON.stringify(entries, null, 2));
    });

  timeline
    .command("replay")
    .description("Reconstrói sequência de eventos")
    .action(() => {
      const entries = exportTimeline();

      if (entries.length === 0) {
        console.log("Nenhum evento para replay.");
        return;
      }

      console.log("\n🔄 Replay da Audit Timeline:\n");
      entries.forEach((entry, index) => {
        console.log(`[${index + 1}/${entries.length}] ${entry.timestamp}`);
        console.log(`  Tipo: ${entry.event_type}`);
        console.log(`  Ator: ${entry.actor}`);
        console.log(`  Hash: ${entry.hash.substring(0, 16)}...`);
        console.log(`  Prev: ${entry.prev_hash.substring(0, 16)}...`);
        console.log();
      });
    });

  return timeline;
}

import { Command } from "commander";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { REQUIRED_FILE_GROUPS } from "../core/health/required-files";
import { printHeader, printLine, printResult, finish } from "../utils/output";
import { getMode, SessionMode } from "./mode";

export function verifyCommand(): Command {
  return new Command("verify")
    .description("Executa todos os quality gates disponíveis")
    .action(() => {
      let appendEntry: (cmd: string, status: number, output: string) => void = () => {};
      try {
        appendEntry = require(path.join(process.cwd(), '.ai/bin/ledger.js')).appendEntry;
      } catch {
        // ledger.js optional — proceed with noop attestation
      }
      let fullOutput = "\nAI DevKit Verify\n\n";
      const log = (msg: string) => { if (!isLLMMode) console.log(msg); fullOutput += msg + "\n"; };
      const isLLMMode = process.env.AI_LLM_MODE === '1';

      const root = process.cwd();
      const { mode } = getMode(root);
      let missing = false;
      let exitCode = 0;

      log(`Modo de sessao: ${mode}`);

      REQUIRED_FILE_GROUPS.flatMap(g => g.required).forEach(file => {
          if (!fs.existsSync(path.join(root, file))) {
              log(`❌ Arquivo obrigatório ausente: ${file}`);
              missing = true;
          } else {
              log(`✅ Encontrado: ${file}`);
          }
      });

      if (missing) {
         log("\n❌ Falha na verificação de arquivos estruturais.");
         exitCode = 1;
      }

      if (exitCode === 0) {
          const statusRes = spawnSync("node", [path.join(__dirname, "../index.js"), "status"], { cwd: root, encoding: 'utf8' });
          if (statusRes.status !== 0) {
              log("\n❌ Health Consistency Failed: verify cannot pass if status reports critical/high missing files.");
              exitCode = 1;
          }
      }

      const skipPrevention = mode === 'debugging' || mode === 'documentation';
      if (exitCode === 0 && !process.env.AI_DEVKIT_NO_RECURSION && !skipPrevention) {
          const preventionSuite = path.join(root, ".ai/bin/run-prevention-suite.js");
          if (fs.existsSync(preventionSuite)) {
            log("\nExecutando prevention suite...");
            const result = spawnSync("node", [preventionSuite], { stdio: "pipe", cwd: root, encoding: 'utf8' });
            fullOutput += result.stdout + "\n" + result.stderr + "\n";
            if (!isLLMMode) console.log(result.stdout);
            if (result.stderr && !isLLMMode) console.error(result.stderr);
            if (result.status !== 0) {
              log("\n❌ Prevention suite falhou.");
              exitCode = 1;
            }
          }
      } else if (skipPrevention) {
          log(`\nModo ${mode}: prevention suite ignorada.`);
      }

      const skipQualityAgent = mode === 'debugging' || mode === 'documentation' || mode === 'performance';
      if (exitCode === 0 && !skipQualityAgent) {
          const qgPath = path.join(root, ".ai/bin/quality-agent.js");
          if (fs.existsSync(qgPath)) {
            log("\nExecutando quality-agent...");
            const result = spawnSync("node", [qgPath], { stdio: "pipe", cwd: root, encoding: 'utf8' });
            fullOutput += result.stdout + "\n" + result.stderr + "\n";
            if (!isLLMMode) console.log(result.stdout);
            if (result.stderr && !isLLMMode) console.error(result.stderr);
            if (result.status !== 0) {
                log("\n❌ Quality gates falharam.");
                exitCode = 1;
            }
          }
      } else if (skipQualityAgent) {
          log(`Modo ${mode}: quality-agent ignorado.`);
      }

      if (exitCode === 0) {
          log("\n✅ Todos os quality gates passaram.");
      }

      appendEntry('verify', exitCode, fullOutput);

      if (isLLMMode) {
        console.log(JSON.stringify({
          ok: exitCode === 0,
          checkpoint: "verify",
          status: exitCode === 0 ? "passed" : "failed",
          context_summary: exitCode === 0
            ? "Todos os quality gates passaram."
            : "Quality gates falharam.",
          next_actions: exitCode === 0 ? [] : ["Corrigir falhas e executar ai-devkit verify novamente"],
          cost_usd: 0.00,
          mode,
        }, null, 2));
      }
      process.exit(exitCode);
    });
}

import { Command } from 'commander';
import fs from 'node:fs';
import path from 'node:path';
import readline from 'node:readline';
import { detectStack } from './detect';
import { printLine, finish } from "../utils/output";

function ask(rl: readline.Interface, question: string): Promise<string> {
  return new Promise(resolve => rl.question(question + ' ', resolve));
}

export async function runWizard(root: string): Promise<Record<string, string>> {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  const stack = detectStack(root);

  printLine('=== AI-Devkit Wizard ===');
  printLine('');

  const name = await ask(rl, `Nome do projeto [${path.basename(root)}]:`) || path.basename(root);

  const langDefault = stack.languages[0] || 'nodejs';
  const lang = await ask(rl, `Linguagem (${['nodejs', 'python', 'go', 'rust'].join(', ')}) [${langDefault}]:`) || langDefault;

  const frameworkHint = stack.frameworks.length
    ? stack.frameworks.join(', ')
    : 'nenhum detectado';
  const flavor = await ask(rl, `Framework (nestjs, express, fastify, fastapi, go) [${frameworkHint}]:`);

  const features = await ask(rl, 'Features (separadas por virgula: eslint,prettier,jest):');

  const pkgManager = await ask(rl, `Gerenciador de pacotes [${stack.packageManager || 'npm'}]:`) || stack.packageManager || 'npm';

  rl.close();

  return {
    name,
    language: lang,
    framework: flavor || stack.frameworks[0] || 'nestjs',
    features,
    packageManager: pkgManager,
  };
}

export function wizardCommand(): Command {
  return new Command('wizard')
    .description('Wizard interativo para configuracao inicial do projeto')
    .option('--no-wizard', 'Forca modo CLI classico mesmo sem pipe')
    .action(async (options) => {
      const isPiped = !process.stdin.isTTY;

      if (options.wizard === false || isPiped) {
        printLine('[ai-devkit] Modo wizard desativado. Use "ai-devkit init" para CLI classico.');
        return;
      }

      try {
        const root = process.cwd();
        const answers = await runWizard(root);

        printLine('');
        printLine('=== Resumo da Configuracao ===');
        printLine(`Nome: ${answers.name}`);
        printLine(`Linguagem: ${answers.language}`);
        printLine(`Framework: ${answers.framework}`);
        printLine(`Features: ${answers.features || 'nenhuma'}`);
        printLine(`Package manager: ${answers.packageManager}`);
        printLine('');

        process.exit(0);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.error(`\n❌ Erro no wizard: ${message}`);
        process.exit(1);
      }
    });
}

import { Command } from 'commander';
import { execSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { printHeader, printLine, printResult, finish } from "../utils/output";

// ============================================================
// TASK-GAP-14: Worktree Isolation para Agentes
// ============================================================

const WORKTREE_DIR = '.ai/worktrees';

function getWorktreePath(root: string, agentName: string): string {
  return path.join(root, WORKTREE_DIR, agentName);
}

function isGitRepo(root: string): boolean {
  return fs.existsSync(path.join(root, '.git'));
}

function runGit(root: string, args: string[]): { stdout: string; stderr: string; exitCode: number } {
  try {
    const stdout = execSync(`git ${args.join(' ')}`, {
      cwd: root,
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    return { stdout: stdout.trim(), stderr: '', exitCode: 0 };
  } catch (err: unknown) {
    const error = err as { stdout?: string; stderr?: string; status?: number };
    return {
      stdout: (error.stdout || '').toString().trim(),
      stderr: (error.stderr || '').toString().trim(),
      exitCode: error.status || 1,
    };
  }
}

export function worktreeCommand(): Command {
  const cmd = new Command('worktree')
    .description('Worktree Isolation para Agentes');

  cmd
    .command('create <agent>')
    .description('Cria uma worktree isolada para um agente')
    .option('--branch <branch>', 'Nome do branch para a worktree', 'feature/agent-<agent>')
    .action((agent: string, options) => {
      const root = process.cwd();

      if (!isGitRepo(root)) {
        printResult('create', false, 'Not a git repository');
        finish({
          checkpoint: 'worktree_create',
          ok: false,
          status: 'failed',
          context_summary: 'Not a git repository',
        });
        return;
      }

      const worktreePath = getWorktreePath(root, agent);
      const branchName = options.branch.replace('<agent>', agent);

      if (fs.existsSync(worktreePath)) {
        printResult('create', false, `Worktree for "${agent}" already exists at ${worktreePath}`);
        finish({
          checkpoint: 'worktree_create',
          ok: false,
          status: 'failed',
          context_summary: `Worktree for ${agent} already exists`,
        });
        return;
      }

      // Check if branch exists
      const branchCheck = runGit(root, ['rev-parse', '--verify', branchName]);
      if (branchCheck.exitCode === 0) {
        // Branch exists, just add worktree
        const result = runGit(root, ['worktree', 'add', worktreePath, branchName]);
        if (result.exitCode !== 0) {
          printResult('create', false, result.stderr);
          finish({
            checkpoint: 'worktree_create',
            ok: false,
            status: 'failed',
            context_summary: result.stderr,
          });
          return;
        }
      } else {
        // Create new branch and worktree
        const result = runGit(root, ['worktree', 'add', '-b', branchName, worktreePath, 'HEAD']);
        if (result.exitCode !== 0) {
          printResult('create', false, result.stderr);
          finish({
            checkpoint: 'worktree_create',
            ok: false,
            status: 'failed',
            context_summary: result.stderr,
          });
          return;
        }
      }

      printResult('create', true, `Worktree for "${agent}" created at ${worktreePath} (branch: ${branchName})`);
      finish({
        checkpoint: 'worktree_create',
        ok: true,
        status: 'passed',
        context_summary: `Created worktree for ${agent}`,
        data: { agent, path: worktreePath, branch: branchName },
      });
    });

  cmd
    .command('list')
    .description('Lista todas as worktrees de agentes')
    .action(() => {
      const root = process.cwd();

      if (!isGitRepo(root)) {
        printLine('Not a git repository');
        finish({
          checkpoint: 'worktree_list',
          ok: true,
          status: 'passed',
          context_summary: 'Not a git repository',
        });
        return;
      }

      const result = runGit(root, ['worktree', 'list']);
      if (result.exitCode !== 0) {
        printLine('No worktrees found');
        finish({
          checkpoint: 'worktree_list',
          ok: true,
          status: 'passed',
          context_summary: 'No worktrees',
        });
        return;
      }

      printHeader('Git Worktrees');
      printLine(result.stdout);
      printLine('');
      printLine('Agent worktrees:');

      const worktreesDir = path.join(root, WORKTREE_DIR);
      if (fs.existsSync(worktreesDir)) {
        const agents = fs.readdirSync(worktreesDir, { withFileTypes: true })
          .filter(d => d.isDirectory())
          .map(d => d.name);

        if (agents.length === 0) {
          printLine('  No agent worktrees found');
        } else {
          for (const agent of agents) {
            const agentPath = path.join(worktreesDir, agent);
            const branchResult = runGit(agentPath, ['rev-parse', '--abbrev-ref', 'HEAD']);
            const branch = branchResult.exitCode === 0 ? branchResult.stdout : 'unknown';
            printLine(`  ${agent.padEnd(15)} → ${agentPath} (branch: ${branch})`);
          }
        }
      } else {
        printLine('  No agent worktrees found');
      }

      finish({
        checkpoint: 'worktree_list',
        ok: true,
        status: 'passed',
        context_summary: 'Listed worktrees',
      });
    });

  cmd
    .command('remove <agent>')
    .description('Remove a worktree de um agente')
    .option('--force', 'Forca a remocao mesmo se houver mudancas nao commitadas')
    .action((agent: string, options) => {
      const root = process.cwd();
      const worktreePath = getWorktreePath(root, agent);

      if (!fs.existsSync(worktreePath)) {
        printResult('remove', false, `Worktree for "${agent}" not found`);
        finish({
          checkpoint: 'worktree_remove',
          ok: false,
          status: 'failed',
          context_summary: `Worktree for ${agent} not found`,
        });
        return;
      }

      const args = ['worktree', 'remove'];
      if (options.force) args.push('--force');
      args.push(worktreePath);

      const result = runGit(root, args);
      if (result.exitCode !== 0) {
        printResult('remove', false, result.stderr);
        finish({
          checkpoint: 'worktree_remove',
          ok: false,
          status: 'failed',
          context_summary: result.stderr,
        });
        return;
      }

      // Remove the directory if it still exists
      if (fs.existsSync(worktreePath)) {
        fs.rmSync(worktreePath, { recursive: true, force: true });
      }

      printResult('remove', true, `Worktree for "${agent}" removed`);
      finish({
        checkpoint: 'worktree_remove',
        ok: true,
        status: 'passed',
        context_summary: `Removed worktree for ${agent}`,
        data: { agent },
      });
    });

  cmd
    .command('merge <agent>')
    .description('Merge o branch da worktree do agente de volta ao branch principal')
    .option('--target <branch>', 'Branch alvo para o merge', 'main')
    .option('--no-push', 'Nao faz push apos o merge')
    .action((agent: string, options) => {
      const root = process.cwd();
      const worktreePath = getWorktreePath(root, agent);

      if (!fs.existsSync(worktreePath)) {
        printResult('merge', false, `Worktree for "${agent}" not found`);
        finish({
          checkpoint: 'worktree_merge',
          ok: false,
          status: 'failed',
          context_summary: `Worktree for ${agent} not found`,
        });
        return;
      }

      // Get current branch of worktree
      const branchResult = runGit(worktreePath, ['rev-parse', '--abbrev-ref', 'HEAD']);
      if (branchResult.exitCode !== 0) {
        printResult('merge', false, 'Could not determine worktree branch');
        finish({
          checkpoint: 'worktree_merge',
          ok: false,
          status: 'failed',
          context_summary: 'Could not determine branch',
        });
        return;
      }
      const agentBranch = branchResult.stdout;

      // Fetch latest
      runGit(root, ['fetch', '--all']);

      // Checkout target branch
      const checkoutResult = runGit(root, ['checkout', options.target]);
      if (checkoutResult.exitCode !== 0) {
        printResult('merge', false, checkoutResult.stderr);
        finish({
          checkpoint: 'worktree_merge',
          ok: false,
          status: 'failed',
          context_summary: checkoutResult.stderr,
        });
        return;
      }

      // Pull latest
      runGit(root, ['pull']);

      // Merge agent branch
      const mergeResult = runGit(root, ['merge', agentBranch, '--no-edit']);
      if (mergeResult.exitCode !== 0) {
        printResult('merge', false, `Merge conflict: ${mergeResult.stderr}`);
        finish({
          checkpoint: 'worktree_merge',
          ok: false,
          status: 'failed',
          context_summary: `Merge conflict merging ${agentBranch}`,
        });
        return;
      }

      // Push if requested
      if (options.push !== false) {
        const pushResult = runGit(root, ['push']);
        if (pushResult.exitCode !== 0) {
          printLine(`Warning: Push failed: ${pushResult.stderr}`);
        }
      }

      printResult('merge', true, `Merged "${agentBranch}" into "${options.target}"`);
      finish({
        checkpoint: 'worktree_merge',
        ok: true,
        status: 'passed',
        context_summary: `Merged ${agentBranch} into ${options.target}`,
        data: { agent, fromBranch: agentBranch, toBranch: options.target },
      });
    });

  cmd
    .command('status')
    .description('Mostra o status de todas as worktrees de agentes')
    .action(() => {
      const root = process.cwd();
      const worktreesDir = path.join(root, WORKTREE_DIR);

      if (!fs.existsSync(worktreesDir)) {
        printLine('No agent worktrees found');
        finish({
          checkpoint: 'worktree_status',
          ok: true,
          status: 'passed',
          context_summary: 'No worktrees',
        });
        return;
      }

      const agents = fs.readdirSync(worktreesDir, { withFileTypes: true })
        .filter(d => d.isDirectory())
        .map(d => d.name);

      printHeader('Agent Worktrees Status');
      for (const agent of agents) {
        const agentPath = path.join(worktreesDir, agent);
        const branchResult = runGit(agentPath, ['rev-parse', '--abbrev-ref', 'HEAD']);
        const branch = branchResult.exitCode === 0 ? branchResult.stdout : 'unknown';

        const statusResult = runGit(agentPath, ['status', '--porcelain']);
        const hasChanges = statusResult.stdout.length > 0;

        const aheadResult = runGit(agentPath, ['rev-list', '--count', `${branch}..origin/${branch}`, '--']);
        const behindResult = runGit(agentPath, ['rev-list', '--count', `origin/${branch}..${branch}`, '--']);
        const ahead = aheadResult.exitCode === 0 ? parseInt(aheadResult.stdout, 10) : 0;
        const behind = behindResult.exitCode === 0 ? parseInt(behindResult.stdout, 10) : 0;

        const icon = hasChanges ? '⚠️' : '✅';
        printLine(`${icon} ${agent}`);
        printLine(`   Path:   ${agentPath}`);
        printLine(`   Branch: ${branch}`);
        printLine(`   Status: ${hasChanges ? 'Uncommitted changes' : 'Clean'}`);
        if (ahead > 0 || behind > 0) {
          printLine(`   Remote: ${ahead > 0 ? `${ahead} ahead` : ''}${ahead > 0 && behind > 0 ? ', ' : ''}${behind > 0 ? `${behind} behind` : ''}`);
        }
        printLine('');
      }

      finish({
        checkpoint: 'worktree_status',
        ok: true,
        status: 'passed',
        context_summary: `Status checked for ${agents.length} worktrees`,
        data: { agents: agents.length },
      });
    });

  return cmd;
}

