export function getFramework(id: string): FrameworkDefinition | undefined {
  return FRAMEWORKS.find(f => f.id === id);
}

export function listFrameworks(): string[] {
  return FRAMEWORKS.map(f => f.id);
}

import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { getFramework, listFrameworks, FrameworkRequirement } from './frameworks';

export interface RuleEntry {
  text: string;
  source: string;
}

export interface ComplianceMapping {
  framework: string;
  frameworkName: string;
  matched: number;
  total: number;
  matches: Array<{ requirement: string; rule: string }>;
  gaps: string[];
  score: number;
}

export interface ComplianceReport {
  generatedAt: string;
  mappings: ComplianceMapping[];
  overallScore: number;
}

function loadRules(root: string): RuleEntry[] {
  const rules: RuleEntry[] = [];

  const lawsPath = path.join(root, '.ai/laws.yaml');
  if (fs.existsSync(lawsPath)) {
    try {
      const data = YAML.parse(fs.readFileSync(lawsPath, 'utf8'));
      const rawRules: string[] = data?.rules || [];
      for (const r of rawRules) {
        rules.push({ text: r, source: '.ai/laws.yaml' });
      }
    } catch { }
  }

  for (const policyDir of ['.ai/policies', '.ai/security', '.ai/quality']) {
    const fullDir = path.join(root, policyDir);
    if (!fs.existsSync(fullDir)) continue;
    for (const entry of fs.readdirSync(fullDir)) {
      if (!entry.endsWith('.md') && !entry.endsWith('.yaml')) continue;
      const content = fs.readFileSync(path.join(fullDir, entry), 'utf8');
      const lines = content.split('\n').filter(l => l.trim().startsWith('- '));
      for (const line of lines) {
        rules.push({ text: line.trim().replace(/^- /, ''), source: `${policyDir}/${entry}` });
      }
    }
  }

  return rules;
}

function matchRuleToRequirements(rule: string, requirements: FrameworkRequirement[]): string[] {
  const lower = rule.toLowerCase();
  return requirements
    .filter(req => req.keywords.some(kw => lower.includes(kw.toLowerCase())))
    .map(req => req.id);
}

export function mapRulesToFramework(root: string, frameworkId: string): ComplianceMapping {
  const framework = getFramework(frameworkId);
  if (!framework) {
    return { framework: frameworkId, frameworkName: frameworkId, matched: 0, total: 0, matches: [], gaps: ['Framework nao encontrado'], score: 0 };
  }

  const rules = loadRules(root);
  const matched: Array<{ requirement: string; rule: string }> = [];
  const matchedReqs = new Set<string>();

  for (const rule of rules) {
    const matchedReqIds = matchRuleToRequirements(rule.text, framework.requirements);
    for (const reqId of matchedReqIds) {
      matched.push({ requirement: reqId, rule: rule.text });
      matchedReqs.add(reqId);
    }
  }

  const gaps = framework.requirements
    .filter(req => !matchedReqs.has(req.id))
    .map(req => `${req.id} — ${req.title}`);

  const score = framework.requirements.length > 0
    ? Math.round((matchedReqs.size / framework.requirements.length) * 100)
    : 0;

  return {
    framework: frameworkId,
    frameworkName: framework.name,
    matched: matchedReqs.size,
    total: framework.requirements.length,
    matches: matched,
    gaps,
    score
  };
}

export function generateReport(root: string): ComplianceReport {
  const frameworkIds = listFrameworks();
  const mappings = frameworkIds.map(id => mapRulesToFramework(root, id));
  const overallScore = mappings.length > 0
    ? Math.round(mappings.reduce((sum, m) => sum + m.score, 0) / mappings.length)
    : 0;

  const report: ComplianceReport = {
    generatedAt: new Date().toISOString(),
    mappings,
    overallScore
  };

  const reportDir = path.join(root, '.ai/reports/compliance');
  fs.mkdirSync(reportDir, { recursive: true });

  for (const m of mappings) {
    fs.writeFileSync(path.join(reportDir, `${m.framework}.json`), JSON.stringify(m, null, 2));
  }

  return report;
}

import fs from 'node:fs';
import path from 'node:path';
import { parse } from 'yaml';
import { detectSpecType } from './validator';

export interface DiffEntry {
  type: 'breaking' | 'non-breaking';
  path: string;
  field: string;
  change: string;
  oldValue?: unknown;
  newValue?: unknown;
}

export interface DiffResult {
  specType: string;
  breaking: DiffEntry[];
  nonBreaking: DiffEntry[];
  total: number;
}

function loadSpec(filePath: string): Record<string, unknown> {
  const ext = path.extname(filePath).toLowerCase();
  const raw = fs.readFileSync(filePath, 'utf-8');
  if (ext === '.json') return JSON.parse(raw);
  if (ext === '.yaml' || ext === '.yml') return parse(raw) as Record<string, unknown>;
  try { return JSON.parse(raw); } catch { return parse(raw) as Record<string, unknown>; }
}

function deepDiff(oldObj: Record<string, unknown>, newObj: Record<string, unknown>, basePath: string = ''): DiffEntry[] {
  const results: DiffEntry[] = [];
  const allKeys = new Set([...Object.keys(oldObj), ...Object.keys(newObj)]);

  for (const key of allKeys) {
    const currentPath = basePath ? `${basePath}.${key}` : key;
    const oldVal = oldObj[key];
    const newVal = newObj[key];

    if (key === 'description' || key === 'summary') continue;

    if (oldVal === undefined && newVal !== undefined) {
      results.push({ type: 'non-breaking', path: basePath, field: currentPath, change: 'adicionado', newValue: newVal });
    } else if (oldVal !== undefined && newVal === undefined) {
      const isBreakingField = ['required', 'minimum', 'maximum', 'minLength', 'maxLength', 'pattern', 'type'].includes(key);
      results.push({ type: isBreakingField ? 'breaking' : 'non-breaking', path: basePath, field: currentPath, change: 'removido', oldValue: oldVal });
    } else if (typeof oldVal === 'object' && typeof newVal === 'object' && oldVal !== null && newVal !== null && !Array.isArray(oldVal) && !Array.isArray(newVal)) {
      results.push(...deepDiff(oldVal as Record<string, unknown>, newVal as Record<string, unknown>, currentPath));
    } else if (Array.isArray(oldVal) && Array.isArray(newVal)) {
      if (newVal.length < oldVal.length && basePath.includes('required')) {
        results.push({ type: 'breaking', path: basePath, field: currentPath, change: 'campo obrigatorio removido', oldValue: oldVal, newValue: newVal });
      } else if (JSON.stringify(oldVal) !== JSON.stringify(newVal)) {
        results.push({ type: 'non-breaking', path: basePath, field: currentPath, change: 'lista modificada', oldValue: oldVal, newValue: newVal });
      }
    } else if (oldVal !== newVal) {
      const isBreaking = key === 'type' || key === 'required';
      results.push({ type: isBreaking ? 'breaking' : 'non-breaking', path: basePath, field: currentPath, change: `modificado: ${String(oldVal)} → ${String(newVal)}`, oldValue: oldVal, newValue: newVal });
    }
  }

  return results;
}

export function diffSpecs(oldFile: string, newFile: string): DiffResult {
  const oldSpec = loadSpec(oldFile);
  const newSpec = loadSpec(newFile);
  const specType = detectSpecType(oldFile);
  const specTypeNew = detectSpecType(newFile);

  if (specType !== specTypeNew) {
    return { specType: `${specType} → ${specTypeNew}`, breaking: [], nonBreaking: [{ type: 'non-breaking', path: '', field: 'specType', change: `Tipo alterado: ${specType} → ${specTypeNew}`, oldValue: specType, newValue: specTypeNew }], total: 1 };
  }

  const allChanges = deepDiff(oldSpec, newSpec);
  const breaking = allChanges.filter(e => e.type === 'breaking');
  const nonBreaking = allChanges.filter(e => e.type === 'non-breaking');

  return { specType, breaking, nonBreaking, total: allChanges.length };
}

import fs from 'node:fs';
import path from 'node:path';
import { parse } from 'yaml';

export interface GeneratedFile {
  path: string;
  content: string;
}

function loadSpec(filePath: string): { spec: Record<string, unknown>; name: string } {
  const ext = path.extname(filePath).toLowerCase();
  const raw = fs.readFileSync(filePath, 'utf-8');
  let spec: Record<string, unknown>;
  if (ext === '.json') spec = JSON.parse(raw);
  else spec = parse(raw) as Record<string, unknown>;
  const name = (spec.info as Record<string, unknown>)?.title as string || path.basename(filePath, ext);
  return { spec, name };
}

function toPascalCase(str: string): string {
  return str.replace(/[^a-zA-Z0-9]+(.)/g, (_, c) => c.toUpperCase()).replace(/^[a-z]/, c => c.toUpperCase()).replace(/[^a-zA-Z0-9]/g, '');
}

function toCamelCase(str: string): string {
  return str.replace(/[^a-zA-Z0-9]+(.)/g, (_, c) => c.toUpperCase()).replace(/^[A-Z]/, c => c.toLowerCase()).replace(/[^a-zA-Z0-9]/g, '');
}

function resolveRef(ref: string, spec: Record<string, unknown>): Record<string, unknown> | null {
  const parts = ref.replace('#/', '').split('/');
  let current: unknown = spec;
  for (const p of parts) {
    if (current && typeof current === 'object') current = (current as Record<string, unknown>)[p];
    else return null;
  }
  return current as Record<string, unknown> || null;
}

function tsTypeFromSchema(schema: Record<string, unknown>, spec: Record<string, unknown>, depth: number = 0): string {
  if (depth > 10) return 'unknown';

  if (schema.$ref) {
    const resolved = resolveRef(schema.$ref as string, spec);
    const refName = (schema.$ref as string).split('/').pop() || 'Unknown';
    if (resolved) return refName;
    return 'unknown';
  }

  if (schema.allOf) return (schema.allOf as Array<Record<string, unknown>>).map(s => tsTypeFromSchema(s, spec, depth + 1)).join(' & ') || 'unknown';
  if (schema.oneOf) return (schema.oneOf as Array<Record<string, unknown>>).map(s => tsTypeFromSchema(s, spec, depth + 1)).join(' | ') || 'unknown';
  if (schema.anyOf) return (schema.anyOf as Array<Record<string, unknown>>).map(s => tsTypeFromSchema(s, spec, depth + 1)).join(' | ') || 'unknown';

  const type = schema.type as string || 'object';
  switch (type) {
    case 'string':
      if (schema.enum) return (schema.enum as string[]).map(e => `'${e}'`).join(' | ');
      if (schema.format === 'date-time') return 'string';
      if (schema.format === 'date') return 'string';
      if (schema.format === 'binary') return 'Blob';
      return 'string';
    case 'integer':
    case 'number': return 'number';
    case 'boolean': return 'boolean';
    case 'array': {
      if (schema.items) return `${tsTypeFromSchema(schema.items as Record<string, unknown>, spec, depth + 1)}[]`;
      return 'unknown[]';
    }
    case 'object':
    default: {
      if (schema.properties) {
        const props = schema.properties as Record<string, unknown>;
        const lines = Object.entries(props).map(([k, v]) => {
          const s = v as Record<string, unknown>;
          const required = (schema.required as string[] || []).includes(k);
          return `  ${k}${required ? '' : '?'}: ${tsTypeFromSchema(s, spec, depth + 1)};`;
        });
        return `{\n${lines.join('\n')}\n}`;
      }
      if (schema.additionalProperties) return `Record<string, ${tsTypeFromSchema(schema.additionalProperties as Record<string, unknown>, spec, depth + 1)}>`;
      return 'Record<string, unknown>';
    }
  }
}

export function generateClient(filePath: string, outDir?: string): GeneratedFile[] {
  const { spec, name } = loadSpec(filePath);
  const files: GeneratedFile[] = [];
  const paths = spec.paths as Record<string, unknown> || {};
  const components = spec.components as Record<string, unknown> || {};
  const schemas = components.schemas as Record<string, unknown> || {};
  const types: string[] = [];
  const functions: string[] = [];

  for (const [schemaName, schemaDef] of Object.entries(schemas)) {
    const tsType = tsTypeFromSchema(schemaDef as Record<string, unknown>, spec);
    types.push(`export interface ${toPascalCase(schemaName)} ${tsType}`);
  }

  for (const [p, methods] of Object.entries(paths)) {
    if (typeof methods !== 'object') continue;
    for (const [method, op] of Object.entries(methods as Record<string, unknown>)) {
      if (!['get', 'post', 'put', 'patch', 'delete'].includes(method)) continue;
      const opObj = op as Record<string, unknown>;
      const opId = (opObj.operationId as string) || `${method}${toPascalCase(p)}`;
      const params: string[] = [];

      const parameters = opObj.parameters as Array<Record<string, unknown>> || [];
      for (const param of parameters) {
        const pName = param.name as string;
        const required = param.required as boolean || false;
        const schema = param.schema as Record<string, unknown> || {};
        const tsType = tsTypeFromSchema(schema, spec);
        params.push(`${pName}${required ? '' : '?'}: ${tsType}`);
      }

      const requestBody = opObj.requestBody as Record<string, unknown>;
      if (requestBody) {
        const content = requestBody.content as Record<string, unknown> || {};
        const jsonContent = content['application/json'] as Record<string, unknown>;
        if (jsonContent?.schema) {
          params.push(`body: ${tsTypeFromSchema(jsonContent.schema as Record<string, unknown>, spec)}`);
        }
      }

      const urlTemplate = p.replace(/\{([^}]+)\}/g, '${$1}');
      const paramDecl = params.length > 0 ? `params: { ${params.join('; ')} }` : '';
      const bodyArg = requestBody ? ', params.body' : '';

      functions.push(`export async function ${toCamelCase(opId)}(${paramDecl}): Promise<Response> {
  return fetch(\`${urlTemplate}\`, {
    method: '${method.toUpperCase()}',
    headers: { 'Content-Type': 'application/json' },
    ${requestBody ? `body: JSON.stringify(params.body),` : ''}
  });
}`);
    }
  }

  const typesContent = types.length > 0 ? types.join('\n\n') + '\n\n' : '// No schemas defined\n\n';
  const clientContent = functions.join('\n\n');
  const fullContent = `// Auto-generated client for ${name}\n// Generated by ai-devkit contract generate-client\n\n${typesContent}${clientContent}\n`;

  const outputPath = outDir ? path.join(outDir, `${toCamelCase(name)}-client.ts`) : `${toCamelCase(name)}-client.ts`;
  files.push({ path: outputPath, content: fullContent });

  return files;
}

export function generateServer(filePath: string, outDir?: string): GeneratedFile[] {
  const { spec, name } = loadSpec(filePath);
  const files: GeneratedFile[] = [];
  const paths = spec.paths as Record<string, unknown> || {};
  const routes: string[] = [];

  routes.push(`import { Router, Request, Response } from 'express';\n`);

  for (const [p, methods] of Object.entries(paths)) {
    if (typeof methods !== 'object') continue;
    for (const [method, op] of Object.entries(methods as Record<string, unknown>)) {
      if (!['get', 'post', 'put', 'patch', 'delete'].includes(method)) continue;
      const opObj = op as Record<string, unknown>;
      const opId = (opObj.operationId as string) || `${method}${toPascalCase(p)}`;
      const summary = (opObj.summary as string) || '';

      routes.push(`// ${summary}`);
      routes.push(`router.${method}('${p}', async (req: Request, res: Response) => {`);
      routes.push(`  // TODO: Implement ${opId}`);
      routes.push(`  res.status(501).json({ message: 'Not implemented: ${opId}' });`);
      routes.push(`});\n`);
    }
  }

  routes.push(`export default router;\n`);

  const fullContent = routes.join('\n');
  const outputPath = outDir ? path.join(outDir, `${toCamelCase(name)}-routes.ts`) : `${toCamelCase(name)}-routes.ts`;
  files.push({ path: outputPath, content: fullContent });

  return files;
}

import fs from 'node:fs';
import path from 'node:path';
import { parse } from 'yaml';

export interface LintIssue {
  severity: 'error' | 'warning' | 'info';
  rule: string;
  path: string;
  message: string;
}

export interface LintResult {
  specType: string;
  issues: LintIssue[];
  score: number;
}

function loadSpec(filePath: string): { raw: string; spec: Record<string, unknown>; ext: string } {
  const ext = path.extname(filePath).toLowerCase();
  const raw = fs.readFileSync(filePath, 'utf-8');
  let spec: Record<string, unknown>;
  if (ext === '.json') spec = JSON.parse(raw);
  else spec = parse(raw) as Record<string, unknown>;
  return { raw, spec, ext };
}

function lintOpenAPI(spec: Record<string, unknown>): LintIssue[] {
  const issues: LintIssue[] = [];

  if (!spec.servers) issues.push({ severity: 'warning', rule: 'no-servers', path: 'root', message: 'Nenhum server definido — spec pode nao ser executavel' });

  const paths = spec.paths as Record<string, unknown> || {};
  for (const [p, methods] of Object.entries(paths)) {
    if (typeof methods !== 'object') continue;
    for (const [method, op] of Object.entries(methods as Record<string, unknown>)) {
      if (!['get', 'post', 'put', 'patch', 'delete', 'options', 'head'].includes(method)) continue;
      const opObj = op as Record<string, unknown>;

      if (!opObj.operationId) issues.push({ severity: 'warning', rule: 'operation-id', path: `${p}.${method}`, message: 'operationId ausente — documentacao automatica prejudicada' });

      if (method === 'get' && opObj.requestBody) issues.push({ severity: 'warning', rule: 'get-body', path: `${p}.${method}`, message: 'GET com requestBody — nao recomendado' });

      if (!opObj.responses) issues.push({ severity: 'error', rule: 'responses', path: `${p}.${method}`, message: 'Nenhuma resposta definida' });

      const responses = opObj.responses as Record<string, unknown> || {};
      if (!responses['200'] && !responses['201'] && !responses['204']) issues.push({ severity: 'warning', rule: 'success-response', path: `${p}.${method}`, message: 'Nenhuma resposta de sucesso (2xx) definida' });

      if (method === 'post' || method === 'put' || method === 'patch') {
        if (!responses['201'] && method === 'post') issues.push({ severity: 'info', rule: 'created-response', path: `${p}.${method}`, message: 'POST tipicamente retorna 201 Created' });
        if (!responses['400']) issues.push({ severity: 'info', rule: 'validation-response', path: `${p}.${method}`, message: 'Considere adicionar resposta 400 Bad Request' });
        if (!responses['422']) issues.push({ severity: 'info', rule: 'unprocessable-response', path: `${p}.${method}`, message: 'Considere adicionar resposta 422 Unprocessable Entity' });
      }
    }
  }

  const components = spec.components as Record<string, unknown> || {};
  const securitySchemes = components.securitySchemes as Record<string, unknown> || {};
  if (Object.keys(securitySchemes).length === 0) issues.push({ severity: 'warning', rule: 'security', path: 'root', message: 'Nenhum security scheme definido — considere adicionar autenticacao' });

  return issues;
}

function lintAsyncAPI(spec: Record<string, unknown>): LintIssue[] {
  const issues: LintIssue[] = [];

  const channels = spec.channels as Record<string, unknown> || {};
  if (Object.keys(channels).length === 0) issues.push({ severity: 'error', rule: 'no-channels', path: 'root', message: 'Nenhum channel definido' });

  for (const [ch, chObj] of Object.entries(channels)) {
    if (typeof chObj !== 'object') continue;
    const c = chObj as Record<string, unknown>;

    const subscribe = c.subscribe as Record<string, unknown>;
    const publish = c.publish as Record<string, unknown>;
    if (!subscribe && !publish) issues.push({ severity: 'error', rule: 'channel-operation', path: ch, message: 'Channel sem subscribe ou publish' });

    if (subscribe) {
      const msg = subscribe.message as Record<string, unknown>;
      if (!msg) issues.push({ severity: 'warning', rule: 'channel-message', path: `${ch}.subscribe`, message: 'Subscribe sem message definida' });
    }

    if (publish) {
      const msg = publish.message as Record<string, unknown>;
      if (!msg) issues.push({ severity: 'warning', rule: 'channel-message', path: `${ch}.publish`, message: 'Publish sem message definida' });
    }
  }

  const components = spec.components as Record<string, unknown> || {};
  const securitySchemes = components.securitySchemes as Record<string, unknown> || {};
  if (Object.keys(securitySchemes).length === 0) issues.push({ severity: 'info', rule: 'security', path: 'root', message: 'Nenhum security scheme definido' });

  return issues;
}

function lintGraphQL(spec: Record<string, unknown>): LintIssue[] {
  const issues: LintIssue[] = [];

  if (spec.__schema) {
    const schema = spec.__schema as Record<string, unknown>;
    const types = schema.types as Array<Record<string, unknown>> || [];

    const queryType = types.find(t => t.name === 'Query');
    const mutationType = types.find(t => t.name === 'Mutation');

    if (!queryType) issues.push({ severity: 'error', rule: 'no-query', path: 'root', message: 'Tipo Query nao encontrado — consultas nao funcionarao' });

    if (!mutationType) issues.push({ severity: 'info', rule: 'no-mutation', path: 'root', message: 'Tipo Mutation nao encontrado — apenas leitura' });

    for (const t of types) {
      const tName = t.name as string || '';
      if (['Query', 'Mutation', 'Subscription', '__Type', '__Schema', '__Field', '__InputValue', '__EnumValue', '__Directive'].includes(tName)) continue;
      const fields = t.fields as Array<Record<string, unknown>> || [];
      if (fields.length === 0 && !(t.kind === 'SCALAR' || t.kind === 'ENUM')) issues.push({ severity: 'warning', rule: 'empty-type', path: `type.${tName}`, message: `Tipo "${tName}" sem campos` });

      for (const f of fields) {
        const fName = f.name as string || '';
        if (!f.description && fName !== 'id') issues.push({ severity: 'info', rule: 'field-documentation', path: `type.${tName}.${fName}`, message: `Campo "${fName}" sem descricao` });
      }
    }
  }

  return issues;
}

export function lintSpec(filePath: string): LintResult {
  const { spec, ext } = loadSpec(filePath);
  const specType = spec.openapi ? 'openapi' : spec.asyncapi ? 'asyncapi' : spec.__schema || spec.schema ? 'graphql' : 'unknown';
  let issues: LintIssue[] = [];

  switch (specType) {
    case 'openapi': issues = lintOpenAPI(spec); break;
    case 'asyncapi': issues = lintAsyncAPI(spec); break;
    case 'graphql': issues = lintGraphQL(spec); break;
    default: issues = [{ severity: 'error', rule: 'unknown-type', path: 'root', message: 'Tipo de spec nao reconhecido' }];
  }

  const errors = issues.filter(i => i.severity === 'error').length;
  const warnings = issues.filter(i => i.severity === 'warning').length;
  const infos = issues.filter(i => i.severity === 'info').length;
  const maxScore = (errors + warnings + infos) * 10 || 10;
  const deductions = errors * 10 + warnings * 5 + infos * 2;
  const score = Math.max(0, 100 - (deductions / Math.max(maxScore, 1)) * 100);

  return { specType, issues, score: Math.round(score) };
}

import fs from 'node:fs';
import path from 'node:path';
import { parse } from 'yaml';

export interface ValidationResult {
  valid: boolean;
  specType: 'openapi' | 'asyncapi' | 'graphql' | 'unknown';
  errors: string[];
  warnings: string[];
  info: Record<string, unknown>;
}

function loadSpec(filePath: string): Record<string, unknown> {
  const ext = path.extname(filePath).toLowerCase();
  const raw = fs.readFileSync(filePath, 'utf-8');
  if (ext === '.json') return JSON.parse(raw);
  if (ext === '.yaml' || ext === '.yml') return parse(raw) as Record<string, unknown>;
  try { return JSON.parse(raw); } catch { return parse(raw) as Record<string, unknown>; }
}

function detectType(spec: Record<string, unknown>): 'openapi' | 'asyncapi' | 'graphql' | 'unknown' {
  if (spec.openapi) return 'openapi';
  if (spec.asyncapi) return 'asyncapi';
  if (spec.__schema || (typeof spec.schema === 'object' && spec.schema !== null)) return 'graphql';
  return 'unknown';
}

function validateOpenAPI(spec: Record<string, unknown>): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];
  const info: Record<string, unknown> = {};

  const version = spec.openapi;
  if (!version) errors.push('Campo "openapi" (versao) é obrigatorio');
  else if (!String(version).startsWith('3.')) warnings.push(`Versao OpenAPI "${version}" nao e 3.x — alguns recursos podem nao funcionar`);

  if (!spec.info || typeof spec.info !== 'object') errors.push('Campo "info" é obrigatorio');
  else {
    const i = spec.info as Record<string, unknown>;
    if (!i.title) errors.push('info.title é obrigatorio');
    if (!i.version) errors.push('info.version é obrigatorio');
    info.title = i.title || '(sem titulo)';
    info.version = i.version || '(sem versao)';
  }

  if (!spec.paths || typeof spec.paths !== 'object') errors.push('Campo "paths" é obrigatorio');
  else {
    const paths = spec.paths as Record<string, unknown>;
    const pathCount = Object.keys(paths).length;
    info.paths = pathCount;
    for (const [p, methods] of Object.entries(paths)) {
      if (typeof methods !== 'object') continue;
      for (const [method, op] of Object.entries(methods as Record<string, unknown>)) {
        if (['get', 'post', 'put', 'patch', 'delete', 'options', 'head'].includes(method)) {
          const opObj = op as Record<string, unknown>;
          if (!opObj.operationId) warnings.push(`Path "${p}" method "${method}" sem operationId`);
          if (!opObj.responses) warnings.push(`Path "${p}" method "${method}" sem responses`);
        }
      }
    }
  }

  if (spec.components) {
    const c = spec.components as Record<string, unknown>;
    if (c.schemas) info.schemas = Object.keys(c.schemas as Record<string, unknown>).length;
    if (c.securitySchemes) info.securitySchemes = Object.keys(c.securitySchemes as Record<string, unknown>).length;
  }

  if (!spec.paths || Object.keys(spec.paths as Record<string, unknown>).length === 0) warnings.push('Nenhum path definido');

  return { valid: errors.length === 0, specType: 'openapi', errors, warnings, info };
}

function validateAsyncAPI(spec: Record<string, unknown>): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];
  const info: Record<string, unknown> = {};

  const version = spec.asyncapi;
  if (!version) errors.push('Campo "asyncapi" (versao) é obrigatorio');
  info.asyncapi = version || '(desconhecido)';

  if (!spec.info || typeof spec.info !== 'object') errors.push('Campo "info" é obrigatorio');
  else {
    const i = spec.info as Record<string, unknown>;
    if (!i.title) errors.push('info.title é obrigatorio');
    if (!i.version) errors.push('info.version é obrigatorio');
    info.title = i.title || '(sem titulo)';
    info.version = i.version || '(sem versao)';
  }

  if (!spec.channels || typeof spec.channels !== 'object') errors.push('Campo "channels" é obrigatorio');
  else {
    const channels = spec.channels as Record<string, unknown>;
    info.channels = Object.keys(channels).length;
    if (Object.keys(channels).length === 0) warnings.push('Nenhum channel definido');
  }

  if (spec.components) {
    const c = spec.components as Record<string, unknown>;
    if (c.messages) info.messages = Object.keys(c.messages as Record<string, unknown>).length;
    if (c.schemas) info.schemas = Object.keys(c.schemas as Record<string, unknown>).length;
  }

  return { valid: errors.length === 0, specType: 'asyncapi', errors, warnings, info };
}

function validateGraphQL(spec: Record<string, unknown>): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];
  const info: Record<string, unknown> = {};

  if (spec.__schema) {
    const schema = spec.__schema as Record<string, unknown>;
    const types = schema.types as Array<Record<string, unknown>> || [];
    const queryType = schema.queryType as Record<string, unknown>;
    info.types = types.length;
    info.queryType = queryType?.name || '(desconhecido)';

    const hasQuery = types.some((t: Record<string, unknown>) => t.name === 'Query');
    if (!hasQuery) errors.push('Schema nao possui tipo "Query" — consultas GraphQL nao funcionarao');

    const typeNames = types.map((t: Record<string, unknown>) => t.name).filter(Boolean);
    if (typeNames.length < 3) warnings.push('Schema possui poucos tipos — verifique se esta completo');
  } else if (spec.schema) {
    const s = spec.schema as Record<string, unknown>;
    info.type = s.kind || '(desconhecido)';
    if (s.fields) info.fields = (s.fields as Array<unknown>).length;
  } else {
    errors.push('Schema GraphQL nao reconhecido — necessario __schema ou schema');
  }

  return { valid: errors.length === 0, specType: 'graphql', errors, warnings, info };
}

export function validateSpec(filePath: string): ValidationResult {
  const spec = loadSpec(filePath);
  const type = detectType(spec);

  switch (type) {
    case 'openapi': return validateOpenAPI(spec);
    case 'asyncapi': return validateAsyncAPI(spec);
    case 'graphql': return validateGraphQL(spec);
    default: return { valid: false, specType: 'unknown', errors: ['Tipo de spec nao reconhecido — use openapi, asyncapi ou graphql'], warnings: [], info: {} };
  }
}

export function detectSpecType(filePath: string): string {
  const spec = loadSpec(filePath);
  return detectType(spec);
}

