const LATENCY_LOG = '.ai/reports/local-ai/routing.jsonl';
const LATENCY_CACHE_TTL = 5 * 60 * 1000; // 5 min

const providers: Record<string, AiProvider> = {
  openai: new OpenAiProvider(),
  anthropic: new AnthropicProvider(),
  google: new GoogleProvider(),
  aws: new AwsProvider(),
};

export function getProvider(name: string): AiProvider | undefined {
  return providers[name];
}

export function getAllProviders(): AiProvider[] {
  return Object.values(providers);
}

export function getAvailableProviders(root: string): AiProvider[] {
  return Object.values(providers).filter(p => p.healthCheck());
}

export async function queryWithRouting(
  prompt: string,
  root: string,
  preferredProvider?: string,
  model?: string,
  config?: ProviderConfig
): Promise<ProviderResponse> {
  const availProviders = preferredProvider
    ? [getProvider(preferredProvider)].filter(Boolean) as AiProvider[]
    : getAvailableProviders(root);

  if (availProviders.length === 0) {
    // Fallback to Ollama
    return fallbackToOllama(prompt, model || 'local-small', root, config);
  }

  // Try each provider in order, fallback on failure
  let lastError: string | undefined;

  for (const provider of availProviders) {
    try {
      const result = await provider.query(prompt, model || getDefaultModel(provider.name), config);
      logLatency(root, { provider: provider.name, model: model || 'auto', latencyMs: result.latencyMs, timestamp: Date.now(), success: true });
      return result;
    } catch (err) {
      lastError = err instanceof Error ? err.message : String(err);
      logLatency(root, { provider: provider.name, model: model || 'auto', latencyMs: 0, timestamp: Date.now(), success: false });
      // Try next provider
    }
  }

  // All remote providers failed, fallback to Ollama
  return fallbackToOllama(prompt, model || 'local-small', root, config);
}

async function fallbackToOllama(prompt: string, model: string, root: string, _config?: ProviderConfig): Promise<ProviderResponse> {
  const { queryOllama } = await import('./ollama');
  const start = Date.now();
  const content = await queryOllama(prompt, model, root, 'fallback', 30000);
  return { content, model, provider: 'ollama', latencyMs: Date.now() - start };
}

function getDefaultModel(provider: string): string {
  const models: Record<string, string> = {
    openai: 'gpt-4o-mini',
    anthropic: 'claude-3-haiku-20240307',
    google: 'gemini-1.5-flash',
    aws: 'amazon.titan-text-lite',
    ollama: 'local-small',
  };
  return models[provider] || 'gpt-4o-mini';
}

function logLatency(root: string, entry: LatencyEntry): void {
  const logPath = path.join(root, LATENCY_LOG);
  fs.mkdirSync(path.dirname(logPath), { recursive: true });
  fs.appendFileSync(logPath, JSON.stringify(entry) + '\n');
}

export async function testLatency(root: string): Promise<Array<{ provider: string; latencyMs: number; healthy: boolean }>> {
  const results: Array<{ provider: string; latencyMs: number; healthy: boolean }> = [];
  for (const [name, provider] of Object.entries(providers)) {
    const start = Date.now();
    try {
      const healthy = await provider.healthCheck();
      if (healthy) {
        // Quick ping
        await provider.query('Responda apenas "ok"', getDefaultModel(name), { timeoutMs: 5000 });
        results.push({ provider: name, latencyMs: Date.now() - start, healthy: true });
      } else {
        results.push({ provider: name, latencyMs: 0, healthy: false });
      }
    } catch {
      results.push({ provider: name, latencyMs: Date.now() - start, healthy: false });
    }
  }
  return results;
}

