}

export interface RoutingConfig {
  classify_task: RouteConfig;
  summarize_file: RouteConfig;
  generate_code: { enabled: false };
  explain_violation: RouteConfig;
  suggest_context: RouteConfig;
  extract_entities: RouteConfig;
}

const DEFAULT_ROUTING: RoutingConfig = {
  classify_task: { model: 'local-small', allow_write: false, timeout_secs: 30 },
  summarize_file: { model: 'local-small', allow_write: false, timeout_secs: 30 },
  generate_code: { enabled: false },
  explain_violation: { model: 'local-small', allow_write: false, timeout_secs: 30 },
  suggest_context: { model: 'local-small', allow_write: false, timeout_secs: 30 },
  extract_entities: { model: 'local-small', allow_write: false, timeout_secs: 30 },
};

const ROUTING_PATH = '.ai/local-ai/routing.yaml';

export function loadRouting(root: string): RoutingConfig {
  const filePath = path.join(root, ROUTING_PATH);
  if (!fs.existsSync(filePath)) {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, YAML.stringify(DEFAULT_ROUTING as unknown as Record<string, unknown>));
    return DEFAULT_ROUTING;
  }
  try {
    const data = YAML.parse(fs.readFileSync(filePath, 'utf8')) as RoutingConfig;
    return { ...DEFAULT_ROUTING, ...data };
  } catch {
    return DEFAULT_ROUTING;
  }
}

export function getRouteFor(key: string, root: string): RouteConfig | { enabled: false } | null {
  const routing = loadRouting(root);
  const k = key as keyof RoutingConfig;
  if (k in routing) return routing[k];
  return null;
}

import { IndexedDocument, cosineSimilarity, generateTFIDFVector, extractRelevantChunk } from './embeddings';

export interface SearchResult {
  path: string;
  score: number;
  chunk: string;
}

export function searchDocuments(
  docs: IndexedDocument[],
  query: string,
  maxResults: number = 10,
  filterExt?: string
): SearchResult[] {
  const queryVector = generateTFIDFVector(query);

  let scored = docs.map(doc => ({
    path: doc.path,
    score: cosineSimilarity(queryVector, doc.vector),
    chunk: extractRelevantChunk(doc.content, query),
  }));

  if (filterExt) {
    scored = scored.filter(s => s.path.endsWith(filterExt));
  }

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, maxResults);
}

export function findSimilarDocuments(
  docs: IndexedDocument[],
  targetPath: string,
  maxResults: number = 5
): SearchResult[] {
  const target = docs.find(d => d.path === targetPath);
  if (!target) return [];

  let scored = docs
    .filter(d => d.path !== targetPath)
    .map(doc => ({
      path: doc.path,
      score: cosineSimilarity(target.vector, doc.vector),
      chunk: extractRelevantChunk(doc.content, targetPath),
    }));

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, maxResults);
}

import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { LoadedPlugin } from './loader';

export type HookName = 'onLoad' | 'onVerify' | 'onAudit' | 'onScaffold';

const HOOK_ORDER: HookName[] = ['onLoad', 'onVerify', 'onAudit', 'onScaffold'];

export interface HookResult {
  plugin: string;
  hook: HookName;
  success: boolean;
  output?: string;
  error?: string;
}

function runHookScript(pluginDir: string, script: string, context: Record<string, string>): HookResult {
  const scriptPath = path.resolve(pluginDir, script);
  if (!scriptPath.startsWith(path.resolve(pluginDir))) {
    return {
      plugin: path.basename(pluginDir),
      hook: 'onVerify' as HookName,
      success: false,
      error: `Hook script ${script} esta fora do diretorio do plugin`
    };
  }

  const env = { ...process.env, ...context };
  const result = spawnSync(process.execPath, [scriptPath], { env, encoding: 'utf8', timeout: 30000 });

  return {
    plugin: path.basename(pluginDir),
    hook: 'onVerify' as HookName,
    success: result.status === 0,
    output: result.stdout?.slice(0, 1000),
    error: result.stderr?.slice(0, 1000) || (result.status !== 0 ? `exit code ${result.status}` : undefined)
  };
}

export function runPluginHook(
  plugin: LoadedPlugin,
  hook: HookName,
  context: Record<string, string> = {}
): HookResult | null {
  const script = plugin.manifest.hooks?.[hook];
  if (!script) return null;
  return runHookScript(plugin.dir, script, context);
}

export function runAllHooks(
  plugins: LoadedPlugin[],
  hook: HookName,
  context: Record<string, string> = {}
): HookResult[] {
  return plugins
    .map(p => runPluginHook(p, hook, context))
    .filter((r): r is HookResult => r !== null);
}

import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { PluginManifest, validateManifest } from './manifest';

export interface LoadedPlugin {
  manifest: PluginManifest;
  dir: string;
}

const PLUGIN_DIRS = ['.ai/plugins'];
const NPM_PREFIX = '@ai-devkit-plugin-';

function findPluginDirs(root: string): string[] {
  const dirs: string[] = [];

  for (const rel of PLUGIN_DIRS) {
    const full = path.join(root, rel);
    if (fs.existsSync(full)) {
      for (const entry of fs.readdirSync(full, { withFileTypes: true })) {
        if (entry.isDirectory()) {
          dirs.push(path.join(full, entry.name));
        }
      }
    }
  }

  const nodeModules = path.join(root, 'node_modules');
  if (fs.existsSync(nodeModules)) {
    for (const entry of fs.readdirSync(nodeModules, { withFileTypes: true })) {
      if (entry.isDirectory() && entry.name.startsWith(NPM_PREFIX)) {
        dirs.push(path.join(nodeModules, entry.name));
      }
    }
  }

  return dirs;
}

function loadManifestFromDir(dir: string): PluginManifest | null {
  for (const name of ['plugin.yaml', 'plugin.yml', 'plugin.json']) {
    const file = path.join(dir, name);
    if (fs.existsSync(file)) {
      try {
        const raw = fs.readFileSync(file, 'utf8');
        const data = name.endsWith('.json') ? JSON.parse(raw) : YAML.parse(raw);
        const { valid, manifest } = validateManifest(data || {});
        if (valid && manifest) return manifest;
      } catch { return null; }
    }
  }
  return null;
}

export function loadPlugins(root: string): LoadedPlugin[] {
  const result: LoadedPlugin[] = [];
  const dirs = findPluginDirs(root);

  for (const dir of dirs) {
    const manifest = loadManifestFromDir(dir);
    if (manifest) {
      result.push({ manifest, dir });
    }
  }

  return result;
}

export function findPlugin(root: string, name: string): LoadedPlugin | undefined {
  return loadPlugins(root).find(p => p.manifest.name === name);
}

export type PluginCapability = 'agents' | 'skills' | 'rules' | 'commands' | 'templates';

export interface PluginManifest {
  name: string;
  version: string;
  author: string;
  description?: string;
  capabilities: PluginCapability[];
  hooks?: {
    onLoad?: string;
    onVerify?: string;
    onAudit?: string;
    onScaffold?: string;
  };
  entry?: string;
}

export const REQUIRED_MANIFEST_FIELDS: (keyof PluginManifest)[] = ['name', 'version', 'author', 'capabilities'];

export function validateManifest(data: Record<string, unknown>): { valid: boolean; errors: string[]; manifest?: PluginManifest } {
  const errors: string[] = [];

  for (const field of REQUIRED_MANIFEST_FIELDS) {
    if (!data[field]) {
      errors.push(`Campo obrigatorio ausente: ${field}`);
    }
  }

  if (!data.name || typeof data.name !== 'string') {
    errors.push('name deve ser string nao vazia');
  }
  if (!data.version || typeof data.version !== 'string') {
    errors.push('version deve ser string nao vazia');
  }
  if (!data.author || typeof data.author !== 'string') {
    errors.push('author deve ser string nao vazia');
  }
  if (data.capabilities && !Array.isArray(data.capabilities)) {
    errors.push('capabilities deve ser um array');
  }

  if (errors.length > 0) {
    return { valid: false, errors };
  }

  const manifest = data as unknown as PluginManifest;
  return { valid: true, errors: [], manifest };
}

import { execSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

export interface ReleaseNotesResult {
  version: string;
  date: string;
  features: string[];
  fixes: string[];
  breakingChanges: string[];
  other: string[];
}

export function generateReleaseNotes(fromTag: string, toTag: string, cwd?: string): ReleaseNotesResult {
  const workDir = cwd || process.cwd();
  const notes: ReleaseNotesResult = {
    version: toTag,
    date: new Date().toISOString().split('T')[0],
    features: [],
    fixes: [],
    breakingChanges: [],
    other: [],
  };

  try {
    let log: string;
    try {
      log = execSync(`git log ${fromTag}..${toTag} --oneline --format="%s"`, {
        cwd: workDir, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'],
      });
    } catch {
      log = execSync('git log --oneline -50 --format="%s"', {
        cwd: workDir, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'],
      });
    }

    for (const line of log.split('\n').filter(Boolean)) {
      const msg = line.replace(/^[a-f0-9]+\s+/, '');
      if (/^feat/i.test(msg) || /^feature/i.test(msg) || /^add/i.test(msg)) notes.features.push(msg);
      else if (/^fix/i.test(msg) || /^bug/i.test(msg) || /^hotfix/i.test(msg)) notes.fixes.push(msg);
      else if (/^breaking/i.test(msg) || /!:/i.test(msg)) notes.breakingChanges.push(msg);
      else notes.other.push(msg);
    }
  } catch {
    notes.features.push('N/A — git log nao disponivel');
  }

  return notes;
}

export function formatReleaseNotes(notes: ReleaseNotesResult): string {
  const lines: string[] = [
    `# Release ${notes.version}`,
    `**Data:** ${notes.date}`,
    '',
  ];

  if (notes.breakingChanges.length > 0) {
    lines.push('## ⚠️ Breaking Changes');
    for (const b of notes.breakingChanges) lines.push(`- ${b}`);
    lines.push('');
  }

  if (notes.features.length > 0) {
    lines.push('## 🚀 Features');
    for (const f of notes.features) lines.push(`- ${f}`);
    lines.push('');
  }

  if (notes.fixes.length > 0) {
    lines.push('## 🐛 Bug Fixes');
    for (const f of notes.fixes) lines.push(`- ${f}`);
    lines.push('');
  }

  if (notes.other.length > 0) {
    lines.push('## 🔧 Outras Mudancas');
    for (const o of notes.other) lines.push(`- ${o}`);
    lines.push('');
  }

  return lines.join('\n');
}

import { execSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

export interface ReleasePrepareResult {
  version: string;
  tag: string;
  changelogPath: string;
  previousVersion: string;
  commitsSinceLast: number;
}

export function prepareRelease(version: string, dryRun: boolean = false): ReleasePrepareResult {
  const root = process.cwd();
  let previousVersion = '0.0.0';

  try {
    const tags = execSync('git tag --sort=-v:refname 2>/dev/null', { cwd: root, encoding: 'utf-8' });
    const tagList = tags.split('\n').filter(Boolean);
    if (tagList.length > 0) previousVersion = tagList[0].replace(/^v/, '');
  } catch { /* no tags */ }

  let commitsSinceLast = 0;
  try {
    const log = previousVersion !== '0.0.0'
      ? execSync(`git log v${previousVersion}..HEAD --oneline 2>/dev/null || git log --oneline 2>/dev/null`, { cwd: root, encoding: 'utf-8' })
      : execSync('git log --oneline 2>/dev/null', { cwd: root, encoding: 'utf-8' });
    commitsSinceLast = log.split('\n').filter(Boolean).length;
  } catch { /* no commits */ }

  const tag = `v${version}`;
  const changelogPath = 'CHANGELOG.md';

  if (!dryRun) {
    const packageJsonPath = path.join(root, 'package.json');
    if (fs.existsSync(packageJsonPath)) {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf-8'));
      pkg.version = version;
      fs.writeFileSync(packageJsonPath, JSON.stringify(pkg, null, 2) + '\n');
    }

    const packagesDir = path.join(root, 'packages');
    if (fs.existsSync(packagesDir)) {
      for (const pkgDir of fs.readdirSync(packagesDir)) {
        const pkgJsonPath = path.join(packagesDir, pkgDir, 'package.json');
        if (fs.existsSync(pkgJsonPath)) {
          const pkg = JSON.parse(fs.readFileSync(pkgJsonPath, 'utf-8'));
          pkg.version = version;
          fs.writeFileSync(pkgJsonPath, JSON.stringify(pkg, null, 2) + '\n');
        }
      }
    }

    try {
      const changelogHeader = `## ${new Date().toISOString().split('T')[0]} — v${version}\n\n`;
      if (fs.existsSync(changelogPath)) {
        const existing = fs.readFileSync(changelogPath, 'utf-8');
        fs.writeFileSync(changelogPath, changelogHeader + existing);
      } else {
        fs.writeFileSync(changelogPath, `# Changelog\n\n${changelogHeader}\n`);
      }
    } catch { /* changelog write error */ }

    try {
      execSync(`git add package.json packages/*/package.json ${changelogPath} 2>/dev/null || true`, { cwd: root });
      execSync(`git commit -m "chore: bump version to ${version}" --no-verify 2>/dev/null || true`, { cwd: root });
      execSync(`git tag -a ${tag} -m "Release ${tag}" 2>/dev/null || true`, { cwd: root });
    } catch { /* git ops error */ }
  }

  return { version, tag, changelogPath, previousVersion, commitsSinceLast };
}

import { execSync } from 'node:child_process';
import path from 'node:path';
import fs from 'node:fs';

export interface PublishResult {
  published: boolean;
  registry: string;
  version: string;
  artifacts: string[];
  errors: string[];
}

export function publishRelease(version: string, dryRun: boolean = false): PublishResult {
  const root = process.cwd();
  const result: PublishResult = {
    published: false,
    registry: 'npm',
    version,
    artifacts: [],
    errors: [],
  };

  if (!dryRun) {
    try {
      const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';
      const publishArgs = ['publish', '--access', 'public'];
      execSync(`${npmBin} ${publishArgs.join(' ')} 2>&1`, { cwd: root, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
      result.artifacts.push('npm package');
    } catch (e: unknown) {
      const errorMsg = e instanceof Error ? e.message : String(e);
      result.errors.push(`npm publish: ${errorMsg}`);
    }

    try {
      execSync('git push --follow-tags 2>/dev/null', { cwd: root, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
      result.artifacts.push('git tags');
    } catch { /* git push error */ }

    try {
      execSync('git push origin --tags 2>/dev/null', { cwd: root, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
    } catch { /* git push tags error */ }
  }

  const monorepoPkgs = path.join(root, 'packages');
  if (fs.existsSync(monorepoPkgs)) {
    for (const pkgDir of fs.readdirSync(monorepoPkgs)) {
      const pkgJsonPath = path.join(monorepoPkgs, pkgDir, 'package.json');
      if (fs.existsSync(pkgJsonPath)) {
        if (!dryRun) {
          try {
            const npmBin = process.platform === 'win32' ? 'npm.cmd' : 'npm';
            execSync(`${npmBin} publish --access public 2>&1`, {
              cwd: path.join(monorepoPkgs, pkgDir),
              encoding: 'utf-8',
              stdio: ['pipe', 'pipe', 'pipe'],
            });
            result.artifacts.push(`packages/${pkgDir}`);
          } catch { /* subpackage publish error */ }
        } else {
          result.artifacts.push(`packages/${pkgDir} (dry-run)`);
        }
      }
    }
  }

  result.published = result.errors.length === 0 && !dryRun;
  if (dryRun) result.published = true;

  return result;
}

import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { RulePackManifest, BUILT_IN_PACKS } from './registry';

const PACKS_DIR = '.ai/rule-packs';

export interface InstalledPack {
  manifest: RulePackManifest;
  dir: string;
}

export function listAvailablePacks(): RulePackManifest[] {
  return [...BUILT_IN_PACKS];
}

export function findPack(name: string): RulePackManifest | undefined {
  return BUILT_IN_PACKS.find(p => p.name === name);
}

export function listInstalledPacks(root: string): InstalledPack[] {
  const packsDir = path.join(root, PACKS_DIR);
  if (!fs.existsSync(packsDir)) return [];

  const packs: InstalledPack[] = [];
  for (const entry of fs.readdirSync(packsDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const manifestPath = path.join(packsDir, entry.name, 'rule-pack.yaml');
    if (!fs.existsSync(manifestPath)) continue;
    try {
      const data = YAML.parse(fs.readFileSync(manifestPath, 'utf8')) as RulePackManifest;
      packs.push({ manifest: data, dir: path.join(packsDir, entry.name) });
    } catch { }
  }

  return packs;
}

export function isPackInstalled(root: string, name: string): boolean {
  return listInstalledPacks(root).some(p => p.manifest.name === name);
}

export function installPack(root: string, name: string): boolean {
  const pack = findPack(name);
  if (!pack) return false;

  const packsDir = path.join(root, PACKS_DIR);
  const packDir = path.join(packsDir, name);
  fs.mkdirSync(packDir, { recursive: true });

  const target: Record<string, string[]> = {};
  for (const rule of pack.rules) {
    if (!target[rule.target]) target[rule.target] = [];
    target[rule.target].push(`- [${rule.id}] ${rule.title}: ${rule.description}`);
  }

  const installContent = `# Rule Pack: ${pack.name} v${pack.version}
# ${pack.description || ''}
# Tags: ${pack.tags.join(', ')}

${Object.entries(target).map(([t, rules]) => `
## ${t}
${rules.join('\n')}
`).join('\n')}
`;

  fs.writeFileSync(path.join(packDir, 'rules.md'), installContent);

  const manifestYaml = YAML.stringify({ name: pack.name, version: pack.version, description: pack.description, tags: pack.tags, rules: pack.rules.map(r => ({ id: r.id, title: r.title, severity: r.severity })) });
  fs.writeFileSync(path.join(packDir, 'rule-pack.yaml'), manifestYaml);

  return true;
}

export function uninstallPack(root: string, name: string): boolean {
  const packsDir = path.join(root, PACKS_DIR);
  const packDir = path.join(packsDir, name);
  if (!fs.existsSync(packDir)) return false;
  fs.rmSync(packDir, { recursive: true, force: true });
  return true;
}

export function searchPacks(query: string): RulePackManifest[] {
  const lower = query.toLowerCase();
  return BUILT_IN_PACKS.filter(p =>
    p.name.toLowerCase().includes(lower) ||
    (p.description || '').toLowerCase().includes(lower) ||
    p.tags.some(t => t.toLowerCase().includes(lower))
  );
}

