import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';

export interface BaselineEntry {
  file: string;
  rules: SecurityRule[];
}

export interface SecurityRule {
  id?: string;
  text: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
}

const GOVERNANCE_FILES = ['.ai/laws.yaml', '.ai/policies/command-policy.md', '.ai/policies/ai-generated-code-policy.md'];
const BASELINE_FILE = '.ai/security/baseline.json';

function extractRulesFromLaws(root: string): SecurityRule[] {
  const lawsPath = path.join(root, '.ai/laws.yaml');
  if (!fs.existsSync(lawsPath)) return [];

  try {
    const data = YAML.parse(fs.readFileSync(lawsPath, 'utf8'));
    const rules: string[] = data?.rules || [];
    return rules.map((text: string) => ({ text, severity: 'high' as const }));
  } catch {
    return [];
  }
}

function extractRulesFromPolicy(filePath: string): SecurityRule[] {
  if (!fs.existsSync(filePath)) return [];
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n').filter(l => l.trim().startsWith('- '));
  return lines.map(l => ({ text: l.trim().replace(/^- /, ''), severity: 'medium' as const }));
}

function classifySeverity(text: string): 'critical' | 'high' | 'medium' | 'low' {
  const lower = text.toLowerCase();
  if (lower.includes('senha') || lower.includes('credential') || lower.includes('secret') || lower.includes('password')) return 'critical';
  if (lower.includes('seguranca') || lower.includes('security') || lower.includes('block') || lower.includes('proibido')) return 'high';
  if (lower.includes('valid') || lower.includes('test') || lower.includes('cobertura') || lower.includes('coverage')) return 'medium';
  return 'low';
}

export function createBaseline(root: string): BaselineEntry[] {
  const entries: BaselineEntry[] = [];

  for (const relFile of GOVERNANCE_FILES) {
    const fullPath = path.join(root, relFile);
    if (!fs.existsSync(fullPath)) continue;

    let rules: SecurityRule[] = [];
    if (relFile.endsWith('.yaml')) {
      rules = extractRulesFromLaws(root);
    } else if (relFile.endsWith('.md')) {
      rules = extractRulesFromPolicy(fullPath);
    }

    rules = rules.map(r => ({ ...r, severity: classifySeverity(r.text) }));

    if (rules.length > 0) {
      entries.push({ file: relFile, rules });
    }
  }

  const baselineDir = path.dirname(path.join(root, BASELINE_FILE));
  fs.mkdirSync(baselineDir, { recursive: true });
  fs.writeFileSync(path.join(root, BASELINE_FILE), JSON.stringify(entries, null, 2));

  return entries;
}

export function loadBaseline(root: string): BaselineEntry[] {
  const baselinePath = path.join(root, BASELINE_FILE);
  if (!fs.existsSync(baselinePath)) return [];
  try {
    return JSON.parse(fs.readFileSync(baselinePath, 'utf8'));
  } catch {
    return [];
  }
}

export function getCurrentRules(root: string): BaselineEntry[] {
  return createBaseline(root);
}

export interface DowngradeFinding {
  file: string;
  rule: string;
  severity: string;
  action: 'removed' | 'downgraded';
}

export function detectDowngrades(baseline: BaselineEntry[], current: BaselineEntry[]): DowngradeFinding[] {
  const findings: DowngradeFinding[] = [];

  for (const baseEntry of baseline) {
    const currentEntry = current.find(c => c.file === baseEntry.file);
    if (!currentEntry) {
      for (const rule of baseEntry.rules) {
        findings.push({ file: baseEntry.file, rule: rule.text, severity: rule.severity, action: 'removed' });
      }
      continue;
    }

    const currentTexts = new Set(currentEntry.rules.map(r => r.text));
    for (const baseRule of baseEntry.rules) {
      if (!currentTexts.has(baseRule.text)) {
        findings.push({ file: baseEntry.file, rule: baseRule.text, severity: baseRule.severity, action: 'removed' });
      }
    }
  }

  return findings;
}

import fs from 'node:fs';
import path from 'node:path';
import { DowngradeFinding } from './baseline';

const DOWNGRADE_LOG = '.ai/reports/security/downgrades.jsonl';

export function logDowngradeAttempt(root: string, finding: DowngradeFinding, reason?: string): void {
  const logPath = path.join(root, DOWNGRADE_LOG);
  const dir = path.dirname(logPath);
  fs.mkdirSync(dir, { recursive: true });

  const entry = {
    timestamp: new Date().toISOString(),
    file: finding.file,
    rule: finding.rule,
    severity: finding.severity,
    action: finding.action,
    reason: reason || 'sem motivo'
  };

  fs.appendFileSync(logPath, JSON.stringify(entry) + '\n');
}

export interface SecurityCheckResult {
  blocked: boolean;
  criticalCount: number;
  findings: DowngradeFinding[];
  message: string;
}

export function evaluateFindings(
  findings: DowngradeFinding[],
  force: boolean,
  reason?: string
): SecurityCheckResult {
  const critical = findings.filter(f => f.severity === 'critical');
  const blocked = !force && critical.length > 0;

  let message: string;
  if (findings.length === 0) {
    message = 'Nenhum downgrade detectado. Baseline intacta.';
  } else if (blocked) {
    message = `BLOQUEADO: ${critical.length} regra(s) critica(s) removida(s). Use --force --reason para bypassar.`;
  } else if (force && critical.length > 0) {
    message = `BYPASS com --force: ${critical.length} regra(s) critica(s) removida(s). Motivo: ${reason || 'nao informado'}`;
  } else {
    message = `ATENCAO: ${findings.length} regra(s) nao-critica(s) removida(s). Nao bloqueante.`;
  }

  return { blocked, criticalCount: critical.length, findings, message };
}

export function loadDowngradeLogs(root: string): Record<string, unknown>[] {
  const logPath = path.join(root, DOWNGRADE_LOG);
  if (!fs.existsSync(logPath)) return [];

  return fs.readFileSync(logPath, 'utf8')
    .trim()
    .split('\n')
    .filter(Boolean)
    .map(line => JSON.parse(line));
}

import fs from "node:fs";
import path from "node:path";

export type CopyMode = "safe" | "force" | "dry-run";

export interface CopyResult {
  copied: string[];
  skipped: string[];
  overwritten: string[];
  backedUp: string[];
  errors: string[];
}

export type CopyFilter = (relativePath: string) => boolean;

export function copyTemplateDirectory(sourceDir: string, targetDir: string, mode: CopyMode, filterFn?: CopyFilter): CopyResult {
  const result: CopyResult = {
    copied: [],
    skipped: [],
    overwritten: [],
    backedUp: [],
    errors: []
  };

  const backupRoot = path.join(targetDir, "backups", "setup", new Date().toISOString().replace(/[:.]/g, "-"));

  function copyRecursive(src: string, dest: string, relativePath: string = "") {
    if (!fs.existsSync(src)) return;

    const stats = fs.statSync(src);
    if (stats.isDirectory()) {
      // Para diretórios, sempre permitir a travessia quando há include list
      // O filtro será aplicado nos arquivos individualmente
      // Apenas bloquear diretórios explicitamente excluídos (exclude list)
      if (filterFn && relativePath) {
        // Verificar se é uma exclusão de diretório completo (apenas para exclude list)
        // Para include list, sempre permitir travessia
        const testPath = relativePath + "/";
        if (!filterFn(testPath) && !filterFn(relativePath)) {
          // Se o diretório é excluído tanto como "dir/" quanto como "dir", pular
          // Mas precisamos verificar se é include ou exclude list
          // Uma forma simples: se filterFn retorna false para o diretório, pular
          return;
        }
      }

      if (mode !== "dry-run" && !fs.existsSync(dest)) {
        fs.mkdirSync(dest, { recursive: true });
      }
      for (const file of fs.readdirSync(src)) {
        const newRelativePath = relativePath ? `${relativePath}/${file}` : file;
        copyRecursive(path.join(src, file), path.join(dest, file), newRelativePath);
      }
    } else {
      // Aplicar filtro no arquivo
      if (filterFn && !filterFn(relativePath)) {
        return;
      }

      if (fs.existsSync(dest)) {
        if (mode === "force") {
          const backupPath = path.join(backupRoot, path.relative(targetDir, dest));
          fs.mkdirSync(path.dirname(backupPath), { recursive: true });
          fs.copyFileSync(dest, backupPath);
          fs.copyFileSync(src, dest);
          result.backedUp.push(backupPath);
          result.overwritten.push(dest);
        } else {
          result.skipped.push(dest);
        }
      } else {
        if (mode !== "dry-run") {
          fs.mkdirSync(path.dirname(dest), { recursive: true });
          fs.copyFileSync(src, dest);
        }
        result.copied.push(dest);
      }
    }
  }

  try {
    copyRecursive(sourceDir, targetDir);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    result.errors.push(message);
  }

  return result;
}

import fs from 'node:fs';
import path from 'node:path';

export interface StageResult {
  stage: string;
  passed: boolean;
  durationMs: number;
  output: string;
  exitCode: number;
}

export interface Checkpoint {
  id: string;
  timestamp: string;
  stages: StageResult[];
  currentStage: number;
  completed: boolean;
}

const CHECKPOINT_DIR = '.ai/checkpoints';

function getCheckpointPath(cwd: string): string {
  return path.join(cwd, CHECKPOINT_DIR);
}

export function saveCheckpoint(cwd: string, checkpoint: Checkpoint): void {
  const dir = getCheckpointPath(cwd);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, `${checkpoint.id}.json`), JSON.stringify(checkpoint, null, 2), 'utf-8');
  fs.writeFileSync(path.join(dir, 'latest.json'), JSON.stringify(checkpoint, null, 2), 'utf-8');
}

export function loadLatestCheckpoint(cwd: string): Checkpoint | null {
  const latestPath = path.join(getCheckpointPath(cwd), 'latest.json');
  if (fs.existsSync(latestPath)) {
    try {
      return JSON.parse(fs.readFileSync(latestPath, 'utf-8'));
    } catch { }
  }
  return null;
}

export function listCheckpoints(cwd: string): string[] {
  const dir = getCheckpointPath(cwd);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter(f => f.endsWith('.json') && f !== 'latest.json')
    .map(f => f.replace('.json', ''));
}

import { Checkpoint, saveCheckpoint, loadLatestCheckpoint, listCheckpoints } from './checkpoint';
import { getStages, runStages, StageDef } from './stages';

export function runPipeline(cwd: string, startStage?: string, resume?: boolean, json?: boolean): void {
  let stages: StageDef[];

  if (resume) {
    const checkpoint = loadLatestCheckpoint(cwd);
    if (checkpoint) {
      const failedStage = checkpoint.stages.find(s => !s.passed);
      if (failedStage) {
        stages = getStages(failedStage.stage);
      } else {
        console.log('Pipeline ja foi concluida com sucesso.');
        if (json) console.log(JSON.stringify(checkpoint, null, 2));
        return;
      }
    } else {
      console.log('Nenhum checkpoint encontrado. Iniciando do inicio.');
      stages = getStages();
    }
  } else {
    stages = startStage ? getStages(startStage) : getStages();
  }

  const checkpoint: Checkpoint = {
    id: `gate-${Date.now()}`,
    timestamp: new Date().toISOString(),
    stages: [],
    currentStage: 0,
    completed: false,
  };

  const results = runStages(stages, cwd, (result) => {
    checkpoint.stages.push(result);
    checkpoint.currentStage++;
    saveCheckpoint(cwd, checkpoint);
  });

  const allPassed = results.every(r => r.passed);
  checkpoint.completed = allPassed;
  saveCheckpoint(cwd, checkpoint);

  const failed = results.filter(r => !r.passed).length;

  if (json) {
    console.log(JSON.stringify(checkpoint, null, 2));
  } else {
    console.log(`\n=== Quality Gate Pipeline ===`);
    console.log(`Estagios: ${results.length}`);
    console.log(`Passaram: ${results.filter(r => r.passed).length}`);
    console.log(`Falharam: ${failed}`);
    console.log(`Status: ${allPassed ? '✅ TODOS OK' : '❌ FALHAS DETECTADAS'}`);
  }

  process.exit(failed);
}

export function printStatus(cwd: string, json?: boolean): void {
  const cp = loadLatestCheckpoint(cwd);
  if (!cp) {
    console.log('Nenhum checkpoint encontrado. Execute "ai-devkit gate run" primeiro.');
    return;
  }

  if (json) {
    console.log(JSON.stringify(cp, null, 2));
    return;
  }

  console.log(`\n=== Quality Gate Status ===`);
  console.log(`Ultima execucao: ${cp.timestamp}`);
  console.log(`Estagios: ${cp.stages.length}/${getStages().length}`);
  console.log(`Completo: ${cp.completed}`);
  console.log('');

  for (const stage of cp.stages) {
    const icon = stage.passed ? '✅' : '❌';
    console.log(`  ${icon} ${stage.stage} (${stage.durationMs}ms)`);
  }
}

