import fs from 'node:fs';
import path from 'node:path';

export interface ReviewFinding {
  type: 'anti-slop' | 'regression' | 'security' | 'performance';
  severity: 'critical' | 'high' | 'medium' | 'low';
  file: string;
  line?: number;
  message: string;
  suggestion?: string;
}

export interface ReviewResult {
  findings: ReviewFinding[];
  summary: { total: number; critical: number; high: number; medium: number; low: number };
}

function summarize(findings: ReviewFinding[]): ReviewResult['summary'] {
  const s = { total: findings.length, critical: 0, high: 0, medium: 0, low: 0 };
  for (const f of findings) { s[f.severity]++; }
  return s;
}

function readFiles(root: string, pattern?: RegExp): Map<string, string> {
  const files = new Map<string, string>();
  function walk(dir: string) {
    try {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'node_modules') walk(full);
        else if (entry.isFile() && (entry.name.endsWith('.ts') || entry.name.endsWith('.js') || entry.name.endsWith('.tsx') || entry.name.endsWith('.jsx'))) {
          if (!pattern || pattern.test(full)) files.set(full, fs.readFileSync(full, 'utf-8'));
        }
      }
    } catch { }
  }
  walk(root || process.cwd());
  return files;
}

export const antiSlop = (cwd: string): ReviewFinding[] => {
  const findings: ReviewFinding[] = [];
  const files = readFiles(cwd);
  for (const [file, content] of files) {
    const lines = content.split('\n');
    // Detect TODO/FIXME/HACK without ticket reference
    const todoLines = lines.map((l, i) => ({ line: i + 1, text: l })).filter(l => /\/\/\s*(TODO|FIXME|HACK|XXX)\b(?!\s*\([A-Z]+-\d+\))/.test(l.text));
    for (const l of todoLines) findings.push({ type: 'anti-slop', severity: 'medium', file: path.relative(cwd, file), line: l.line, message: 'TODO/FIXME sem referencia de ticket', suggestion: 'Adicione referencia (ex: TODO(PRJ-123))' });
    // Detect console.log in non-test files
    if (!file.includes('.test.') && !file.includes('__tests__')) {
      const consoleLines = lines.map((l, i) => ({ line: i + 1, text: l })).filter(l => /console\.(log|debug)\(/.test(l.text));
      for (const l of consoleLines) findings.push({ type: 'anti-slop', severity: 'low', file: path.relative(cwd, file), line: l.line, message: 'console.log em codigo de producao', suggestion: 'Substitua por logger estruturado' });
    }
    // Detect empty catch blocks
    const emptyCatch = lines.map((l, i) => ({ line: i + 1, text: l })).filter(l => /catch\s*\(.*\)\s*\{\s*\}/.test(l.text));
    for (const l of emptyCatch) findings.push({ type: 'anti-slop', severity: 'high', file: path.relative(cwd, file), line: l.line, message: 'Catch block vazio — engole erros', suggestion: 'Adicione tratamento ou re-lance o erro' });
    // Detect duplicate lines (>80% similar within 50 lines)
    for (let i = 0; i < lines.length - 1; i++) {
      for (let j = i + 1; j < Math.min(i + 50, lines.length); j++) {
        if (lines[i].trim() && lines[i] === lines[j] && lines[i].length > 20) {
          findings.push({ type: 'anti-slop', severity: 'medium', file: path.relative(cwd, file), line: j + 1, message: 'Linha duplicada', suggestion: 'Extraia para funcao ou variavel' });
          break;
        }
      }
    }
  }
  return findings;
};

export const regressionCheck = (cwd: string): ReviewFinding[] => {
  const findings: ReviewFinding[] = [];
  const files = readFiles(cwd, /\.(ts|tsx)$/);
  const exports = new Map<string, { file: string; line: number }[]>();
  for (const [file, content] of files) {
    const rel = path.relative(cwd, file);
    const exportRegex = /^export\s+(interface|type|class|function|const|enum|abstract\s+class)\s+(\w+)/gm;
    let match;
    while ((match = exportRegex.exec(content)) !== null) {
      const name = match[2];
      if (!exports.has(name)) exports.set(name, []);
      exports.get(name)!.push({ file: rel, line: content.slice(0, match.index).split('\n').length });
    }
  }
  for (const [name, locations] of exports) {
    if (locations.length > 1) {
      findings.push({ type: 'regression', severity: 'medium', file: locations[0].file, line: locations[0].line, message: `Export "${name}" definido em ${locations.length} lugares — possivel conflito`, suggestion: 'Renomeie exports duplicados' });
    }
  }
  return findings;
};

export const securityScan = (cwd: string): ReviewFinding[] => {
  const findings: ReviewFinding[] = [];
  const files = readFiles(cwd);

  const secretPatterns = [
    { pattern: /(?:api[_-]?key|apikey|secret|password|token|credential)\s*[:=]\s*['"][^'"]+['"]/i, severity: 'critical' as const, msg: 'Possivel segredo hardcoded', suggestion: 'Use .env + variavel de ambiente' },
    { pattern: /(?:-----BEGIN\s+(?:RSA\s+)?PRIVATE\s+KEY-----)/, severity: 'critical' as const, msg: 'Chave privada detectada no codigo', suggestion: 'Remova e use gerenciamento de secrets' },
    { pattern: /process\.env\.(?:NODE_ENV|PORT|HOST)\s*=\s*['"][^'"]+['"]/, severity: 'high' as const, msg: 'Variavel de ambiente sendo sobrescrita', suggestion: 'Defina em .env, nao no codigo' },
  ];

  for (const [file, content] of files) {
    for (const sp of secretPatterns) {
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (sp.pattern.test(lines[i])) {
          findings.push({ type: 'security', severity: sp.severity, file: path.relative(cwd, file), line: i + 1, message: sp.msg, suggestion: sp.suggestion });
        }
      }
    }
  }
  return findings;
};

export const performanceCheck = (cwd: string): ReviewFinding[] => {
  const findings: ReviewFinding[] = [];
  const files = readFiles(cwd, /\.(ts|tsx)$/);

  for (const [file, content] of files) {
    const lines = content.split('\n');
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      // N+1 query detection: for loop with await inside
      if (/(for|while)\s*\(/.test(line) && /await/.test(line)) {
        findings.push({ type: 'performance', severity: 'high', file: path.relative(cwd, file), line: i + 1, message: 'Possivel N+1: await dentro de loop', suggestion: 'Use Promise.all() ou batch query' });
      }
      // Large array literal
      if (/\[[\s\S]{0,100}\]/.test(line) && (line.match(/,/g)?.length ?? 0) > 20) {
        findings.push({ type: 'performance', severity: 'low', file: path.relative(cwd, file), line: i + 1, message: 'Array literal grande inline', suggestion: 'Extraia para constante ou arquivo separado' });
      }
      // Sync fs operations
      if (/\bfs\.(readFileSync|writeFileSync|existsSync)\b/.test(line)) {
        findings.push({ type: 'performance', severity: 'medium', file: path.relative(cwd, file), line: i + 1, message: 'Operacao de I/O sincrona', suggestion: 'Use fs.promises com async/await' });
      }
    }
  }
  return findings;
};

export function runReview(checks: string[], cwd: string, json?: boolean): { findings: ReviewFinding[]; summary: ReviewResult['summary'] } {
  let allFindings: ReviewFinding[] = [];
  const checkMap: Record<string, (cwd: string) => ReviewFinding[]> = {
    'anti-slop': antiSlop, regression: regressionCheck, security: securityScan, performance: performanceCheck,
  };

  for (const check of checks) {
    if (checkMap[check]) allFindings = allFindings.concat(checkMap[check](cwd));
  }

  const summary = summarize(allFindings);

  if (json) {
    console.log(JSON.stringify({ findings: allFindings, summary }, null, 2));
  } else {
    const report = [`# Adversarial Review Report\n`, `Date: ${new Date().toISOString()}\n`, `Checks: ${checks.join(', ')}\n`];
    report.push(`\n## Summary\n| Severity | Count |\n|----------|-------|\n`);
    for (const sev of ['critical', 'high', 'medium', 'low']) report.push(`| ${sev} | ${(summary as any)[sev]} |\n`);
    report.push(`\n## Findings (${summary.total})\n`);
    for (const f of allFindings) {
      report.push(`- [${f.severity.toUpperCase()}] [${f.type}] ${f.file}:${f.line || 1} — ${f.message}\n`);
      if (f.suggestion) report.push(`  Suggestion: ${f.suggestion}\n`);
    }
    const reportStr = report.join('');
    const reportDir = path.join(cwd, '.ai', 'reports');
    fs.mkdirSync(reportDir, { recursive: true });
    const reportFile = path.join(reportDir, `review-${Date.now()}.md`);
    fs.writeFileSync(reportFile, reportStr, 'utf-8');
    console.log(reportStr);
    console.log(`\nRelatorio salvo: ${path.relative(cwd, reportFile)}`);
  }

  return { findings: allFindings, summary };
}

import fs from 'node:fs';
import path from 'node:path';

export interface BarrierRule {
  pattern: string;
  severity: 'block' | 'warn';
  description: string;
}

const DEFAULT_RULES: BarrierRule[] = [
  { pattern: 'auth*.ts', severity: 'block', description: 'Arquivos de autenticacao' },
  { pattern: '*.auth.ts', severity: 'block', description: 'Arquivos de autenticacao' },
  { pattern: 'passport*', severity: 'block', description: 'Configuracao Passport' },
  { pattern: '.env*', severity: 'block', description: 'Arquivos de ambiente' },
  { pattern: 'credentials*', severity: 'block', description: 'Arquivos de credenciais' },
  { pattern: 'secrets*', severity: 'block', description: 'Arquivos de secrets' },
  { pattern: 'prisma/schema.prisma', severity: 'block', description: 'Schema do banco' },
  { pattern: '*schema*.ts', severity: 'warn', description: 'Arquivos de schema' },
];

function getRulesPath(cwd: string): string {
  return path.join(cwd, '.ai', 'policies', 'barriers.json');
}

export function loadRules(cwd: string): BarrierRule[] {
  const rulesPath = getRulesPath(cwd);
  if (fs.existsSync(rulesPath)) {
    try {
      return JSON.parse(fs.readFileSync(rulesPath, 'utf-8'));
    } catch { }
  }
  return DEFAULT_RULES;
}

export function saveRules(cwd: string, rules: BarrierRule[]): void {
  const rulesPath = getRulesPath(cwd);
  fs.mkdirSync(path.dirname(rulesPath), { recursive: true });
  fs.writeFileSync(rulesPath, JSON.stringify(rules, null, 2), 'utf-8');
}

function matchPattern(filePath: string, pattern: string): boolean {
  const regexSafe = pattern.replace(/\*/g, '.*').replace(/\?/g, '.');
  try {
    return new RegExp(regexSafe).test(filePath);
  } catch {
    return filePath.includes(pattern);
  }
}

export interface BarrierCheckResult {
  blocked: string[];
  warnings: string[];
  bypass: string | null;
}

export function checkBarriers(cwd: string, changedFiles: string[], bypassReason?: string): BarrierCheckResult {
  const rules = loadRules(cwd);
  const result: BarrierCheckResult = { blocked: [], warnings: [], bypass: bypassReason || null };

  for (const file of changedFiles) {
    for (const rule of rules) {
      if (matchPattern(file, rule.pattern)) {
        if (rule.severity === 'block') {
          result.blocked.push(file);
        } else {
          result.warnings.push(file);
        }
      }
    }
  }

  // Apply bypass
  if (bypassReason && result.blocked.length > 0) {
    const auditPath = path.join(cwd, '.ai', 'audit-trail', 'barrier-bypass.log');
    fs.mkdirSync(path.dirname(auditPath), { recursive: true });
    const entry = `[${new Date().toISOString()}] BYPASS: ${result.blocked.join(', ')} — Reason: ${bypassReason}\n`;
    fs.appendFileSync(auditPath, entry, 'utf-8');
    result.blocked = [];
  }

  return result;
}

export function addRule(cwd: string, pattern: string, severity: 'block' | 'warn', description: string): void {
  const rules = loadRules(cwd);
  rules.push({ pattern, severity, description });
  saveRules(cwd, rules);
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

export interface CveEntry {
  package: string;
  version: string;
  cve: string;
  severity: string;
  fixVersion?: string;
}

export interface ScanResult {
  entries: CveEntry[];
  summary: { total: number; critical: number; high: number; medium: number; low: number };
}

export function scan(cwd: string): ScanResult {
  const entries: CveEntry[] = [];

  // Check package-lock.json
  const pkgLock = path.join(cwd, 'package-lock.json');
  if (fs.existsSync(pkgLock)) {
    try {
      const result = spawnSync('npm', ['audit', '--json'], { cwd, encoding: 'utf-8', timeout: 30000 });
      if (result.stdout) {
        try {
          const audit = JSON.parse(result.stdout);
          if (audit.vulnerabilities) {
            for (const [pkg, data] of Object.entries(audit.vulnerabilities) as [string, any][]) {
              entries.push({
                package: pkg,
                version: data.range || 'unknown',
                cve: data.cves?.[0] || `NPM-${data.severity?.toUpperCase() || 'UNKNOWN'}`,
                severity: data.severity || 'medium',
                fixVersion: data.fixAvailable?.version,
              });
            }
          }
        } catch { }
      }
    } catch { }
  }

  // Check yarn.lock
  const yarnLock = path.join(cwd, 'yarn.lock');
  if (fs.existsSync(yarnLock)) {
    try {
      const result = spawnSync('yarn', ['audit', '--json'], { cwd, encoding: 'utf-8', timeout: 30000 });
      if (result.stdout) {
        const lines = result.stdout.split('\n').filter(Boolean);
        for (const line of lines) {
          try {
            const data = JSON.parse(line);
            if (data.type === 'auditAdvisory') {
              entries.push({
                package: data.data?.advisory?.package_name || 'unknown',
                version: data.data?.advisory?.vulnerable_versions || 'unknown',
                cve: data.data?.advisory?.cves?.[0] || data.data?.advisory?.id?.toString() || 'UNKNOWN',
                severity: data.data?.advisory?.severity || 'medium',
                fixVersion: data.data?.advisory?.patched_versions,
              });
            }
          } catch { }
        }
      }
    } catch { }
  }

  const summary = { total: entries.length, critical: 0, high: 0, medium: 0, low: 0 };
  for (const e of entries) { (summary as any)[e.severity]++; }

  return { entries, summary };
}

export function generateSbom(cwd: string): Record<string, unknown> {
  const sbom: Record<string, unknown> = {
    bomFormat: 'CycloneDX',
    specVersion: '1.5',
    serialNumber: `urn:uuid:${crypto.randomUUID()}`,
    version: 1,
    metadata: { timestamp: new Date().toISOString(), tools: [{ vendor: 'ai-devkit', name: 'supply-chain' }] },
    components: [],
  };

  const pkgPath = path.join(cwd, 'package.json');
  if (fs.existsSync(pkgPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
      const deps = { ...pkg.dependencies, ...pkg.devDependencies };
      (sbom.components as any[]) = Object.entries(deps).map(([name, version]) => ({
        type: 'library',
        name,
        version: (version as string).replace(/^\^|~/, ''),
        purl: `pkg:npm/${name}@${(version as string).replace(/^\^|~/, '')}`,
      }));
    } catch { }
  }

  return sbom;
}

export function audit(entries: CveEntry[], baselinePath?: string): { changed: boolean; added: CveEntry[]; removed: CveEntry[] } {
  const result = { changed: false, added: entries, removed: [] as CveEntry[] };

  if (baselinePath && fs.existsSync(baselinePath)) {
    try {
      const baseline: CveEntry[] = JSON.parse(fs.readFileSync(baselinePath, 'utf-8'));
      const baselineKeys = new Set(baseline.map(e => `${e.package}@${e.cve}`));
      result.added = entries.filter(e => !baselineKeys.has(`${e.package}@${e.cve}`));
      const currentKeys = new Set(entries.map(e => `${e.package}@${e.cve}`));
      result.removed = baseline.filter(e => !currentKeys.has(`${e.package}@${e.cve}`));
      result.changed = result.added.length > 0 || result.removed.length > 0;
    } catch { }
  }

  return result;
}

export function verifyPackage(name: string, cwd: string): { verified: boolean; integrity?: string; error?: string } {
  try {
    const result = spawnSync('npm', ['pack', name, '--dry-run', '--json'], { cwd, encoding: 'utf-8', timeout: 15000 });
    if (result.stdout) {
      const data = JSON.parse(result.stdout);
      return { verified: true, integrity: data[0]?.integrity || 'unknown' };
    }
    return { verified: false, error: result.stderr };
  } catch (err) {
    return { verified: false, error: err instanceof Error ? err.message : String(err) };
  }
}

function summarize(arr: CveEntry[]): { total: number; critical: number; high: number; medium: number; low: number } {
  const s = { total: arr.length, critical: 0, high: 0, medium: 0, low: 0 };
  for (const e of arr) { (s as any)[e.severity]++; }
  return s;
}

export function printScanReport(result: ScanResult, cwd: string, json?: boolean): void {
  if (json) {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const report = [`# Supply Chain Scan Report\n`, `Date: ${new Date().toISOString()}\n`];
  report.push(`\n## Summary\n| Severity | Count |\n|----------|-------|\n`);
  for (const sev of ['critical', 'high', 'medium', 'low']) report.push(`| ${sev} | ${(result.summary as any)[sev]} |\n`);
  report.push(`\n## Vulnerabilities (${result.entries.length})\n`);
  for (const e of result.entries) {
    report.push(`- [${e.severity.toUpperCase()}] ${e.package}@${e.version} — ${e.cve}`);
    if (e.fixVersion) report.push(` (fix: ${e.fixVersion})`);
    report.push('\n');
  }

  const reportStr = report.join('');
  const reportDir = path.join(cwd, '.ai', 'reports');
  fs.mkdirSync(reportDir, { recursive: true });
  const reportFile = path.join(reportDir, `supply-chain-${Date.now()}.md`);
  fs.writeFileSync(reportFile, reportStr, 'utf-8');
  console.log(reportStr);
  console.log(`\nRelatorio salvo: ${path.relative(cwd, reportFile)}`);
}

import fs from "node:fs";
import path from "node:path";

export function findTemplateAiDir(): string {
  const candidates = [
    path.resolve(__dirname, "../../templates/.ai"),
    path.resolve(__dirname, "../templates/.ai"),
    path.resolve(__dirname, "../../../../.ai"),
    path.resolve(__dirname, "../../../../../.ai"),
    path.resolve(process.cwd(), ".ai-template")
  ];

  for (const candidate of candidates) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
      return candidate;
    }
  }

  throw new Error("AI-DevKit template .ai directory not found. Checked: " + candidates.join(", "));
}

import fs from "node:fs";
import path from "node:path";

export function getCliVersion(): string {
  try {
    const pkgPath = path.resolve(__dirname, "../../package.json");
    if (fs.existsSync(pkgPath)) {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
      return pkg.version || "1.0.0";
    }
  } catch {}
  return "1.0.0";
}

